export const authors=[{"id": "writer-347", "name": "Aakash Nayak", "bio": "", "photo": "assets/writers/347-earth-voice-v1.webp"}, {"id": "writer-243", "name": "Aarti Mittal", "bio": "Aarti Mittal alias Rita Jain is a bilingual poet, born and brought up in Mumbai, a teacher by profession at Rahul International School Mumbai, Nallasopara. She also writes short skits with morals for children. She believes that her writings can win the hearts and help to bring some change to make this world a better place. Her writings include the themes based on women empowerment and child exploitation.", "photo": "assets/writers/243-earth-voice-v1.webp"}, {"id": "writer-330", "name": "Abanindra Udgata/ ଅବନୀନ୍ଦ୍ର ଉଦଗାତା", "bio": "Abanindra Udgata retired as Principal Chief General Manager from Reserve Bank of India. He lives in Bhubaneswar. Shri Udgata writes both in English and Odia. He has won awards in all India Poetry competitions and been anthologised. E-mail: ", "photo": "assets/writers/330-earth-voice-v1.webp"}, {"id": "writer-394", "name": "Abeera Mirza", "bio": "Internationally recognized poet, Abeera Mirza, was born on January 16, 2001, in Sargodha, Pakistan. She belongs to the Mughal Empire and currently resides in Gujrat. A gold medalist and graduate of the University of Lahore, Pakistan, Abeera has emerged as a prominent voice in contemporary poetry. Abeera serves as an Assistant Professor of English Literature at Queen College, Gujrat. Her passion for words has earned her numerous awards, and her poem \"Sorry\" has inspired readers worldwide to heal. She has contributed to over 200 anthologies and international magazines, including Raven Cage (Germany), Barcelona Magazine (Spain), and International Literature Language Journal (USA). Abeera`s work has been translated into multiple languages, and she has been featured in publications such as The Mount Kenya Times and Poetic Essence Publications (India). She has won titles like Miss Literary Critic from the University of Lahore, Pakistan.", "photo": "assets/writers/394-earth-voice-v1.webp"}, {"id": "writer-168", "name": "Adyasha Das", "bio": "Dr. Adyasha Das, an Associate Professor at Indian Institute of Tourism & Travel Management (IITTM) Bhubaneswar, Ministry of Tourism, Government of India is a contemporary writer and travel blogger from Odisha known for her insightful and colourful portrayals of life. Suffused with sensitivity, she uses words and imagery with an uninhibited freedom, modulated with quality. An Amazon best-selling author, her stories have a rare psychological insight and are at the same time reflective, sensuous and elegant in their observations. She is the author of poetry collections Anuchharita (Odia), Nemesis, Brass Flowers & The Yogini Poems: Love and Life (English), apart from academic and non-fiction books.", "photo": "assets/writers/168-earth-voice-v1.webp"}, {"id": "writer-77", "name": "Adyasha Priyadarshini", "bio": "Adyasha Priyadarshini, currently studying in the 9th grade, is a student of SAI International school. She started expressing her emotions through the help of words at the age of 11 which later developed into her passion. She has an extraordinary interest in different accents and is a table tennis player amongst other things. She`s an avid reader and sees words as her escape from the strain of the world", "photo": "assets/writers/77-earth-voice-v1.webp"}, {"id": "writer-369", "name": "Afruja Akhtar", "bio": "A silent literature enthusiast, Afruja Akhtar, is one among many writers who quietly and tirelessly contribute to literary discussions. Writing is not her profession, but she takes up the pen solely out of passion. Afruja is a sensitive writer, translator, and poet of the new generation. Currently residing in Duliajan, Afrouza is a teacher by profession. She holds multiple degrees: BA and MA in English from Cotton College, B.Ed. from K.R.D. College of Education, Chaigaon, Post Graduate Diploma in Mass Communication and Journalism from Dibrugarh University, and MA in Assamese from Her poems, stories, and essays have been published in renowned newspapers and magazines like Aamar Asom, Prantashree, and Dainik Asom. She was a regular contributor to the popular magazine \"Priyo Sakhii\". Her published poetry collection, \"Moi Yedi Holohente Konoba Khayali Kobi-r Abhimani Premika\" (If I Were a Romantic Poet`s Ardent Lover), has been praised by critics.", "photo": "assets/writers/369-earth-voice-v1.webp"}, {"id": "writer-125", "name": "Agnivesh Mahapatra", "bio": "Agnivesh Mahapatra is a therapist, counsellor, coach, trainer, speaker, editor and translator who—reads the book of Life and—expresses his take by means of poetry. A trilingual poet who writes with equal flair in English, Hindi, and Odia; he`s much acclaimed as a gifted reciter and is known for developing a new form of poetry, Trione, a collection of which is his Amazon bestseller book—Midnight Musings. Popularly known as The Agnivesh, he`s a winner of the Nissim International Prize 2019, and numerous other accolades. He has also edited a poetry anthology—Moontide—and through his firm ManahSodhanam, has established the ManoSrijan Award for the young wordsmiths of the country.", "photo": "assets/writers/125-earth-voice-v1.webp"}, {"id": "writer-398", "name": "Aishwariya Laxmi", "bio": "Aishwariya Laxmi is an author based in Chennai. Her debut book ` Birds of Paradise: Poems on Life, Liberty, and the Pursuit of Happiness` released on Amazon USA in November 2024. Her work has been widely anthologized. She blogs at www.aishwariyalaxmi.com", "photo": "assets/writers/398-earth-voice-v1.webp"}, {"id": "writer-388", "name": "Aiswarya Pradhan /ଐଶ୍ୱର୍ଯ୍ୟା ପ୍ରଧାନ", "bio": "Aiswarya Pradhan writes poetry in Odia. She resides at Bhawanipatna, Kalahandi.", "photo": "assets/writers/388-earth-voice-v1.webp"}, {"id": "writer-178", "name": "Ajit Dash", "bio": "Poet Sri Ajit Dash by birth inherits his forefather Pariskhit Rathasharma`s legacy as one of the Navaratna Ministers of a Royal King. Being an astute organiser, socio-political as well as Development activist, he has made his presence globally. A freelance journalist and motivator, Sri Ajit Dash leads his life with lots of diversifications as an expert, imbued with utmost passion in the fields of Literature, Language, Environment, Governance, Entrepreneurship Promotion. He is experienced in Media house promotion and Electoral Politics too. Now a days his study is going on in the Use of Multilingualism, Wavelength and frequency of Odia Script, Words and Sentence pronunciation by different speakers in a multilingual perspective.", "photo": "assets/writers/178-earth-voice-v1.webp"}, {"id": "writer-476", "name": "Akash Naik", "bio": "Akash Naik is a kathak dancer choreographer, theater person, work as a assistant director in theaters. He wrote plays. He  spend 12 years in kathak. 10 years in theater. \nHe  writes poems..His poems published in well known gujarati literature magazines like vahi, vi, shacharya prakashan, navneet samarpan, Indian literature from Delhi sahitya academy. At vijayvada international poet meet and Kolkata poet meet.", "photo": "assets/writers/476-earth-voice-v1.webp"}, {"id": "writer-174", "name": "Akhil Kumar Mishra", "bio": "Akhil Kumar Mishra is a bilingual poet writing both in Odia and English with few collections to his credit. He says: I belive as a poet that every human being must face the existential dillemmas provided by Life at different junctures.Poetry is a reflection of what is going inside and outside human living. Therefore,I beleive if we try to live and embrace the earthly realities in a better way,we can create better poetry too.", "photo": "assets/writers/174-earth-voice-v1.webp"}, {"id": "writer-126", "name": "Akshaya Kumar Das", "bio": "Akshaya Kumar Das is the author of \"The Dew Drops\".Sri Das is an internationally published poet with many of his poems published in India & abroad. Sri Das is a retired Insurance Manager with a passion for literature. Sri Das organised a Poetry Festival at KIIT under the aegis of Feelings International Artists Society in April,2017.", "photo": "assets/writers/126-earth-voice-v1.webp"}, {"id": "writer-285", "name": "Alka Nigam", "bio": "Alka Nigam is a Lucknow based Poetess, Writer and Singer. She owned a successful literary page \"Lafzon Ki Potli\". Her poetry collection \"Vama- Mukhar Maun Ki Samvahak\" has been published under \"Anudaan Yojna\" of Uttar Pradesh Hindi Sansthan in the year of 21-22.", "photo": "assets/writers/285-earth-voice-v1.webp"}, {"id": "writer-455", "name": "Alok Kumar Ray", "bio": "Dr. Alok Kumar Ray is a bilingual poet from Odisha,India. He writes both in Odia and English. Being a published poet his poems have been featured in a great number of newspapers, anthologies, magazines and tabloids.", "photo": "assets/writers/455-earth-voice-v1.webp"}, {"id": "writer-381", "name": "Amanita Sen", "bio": "Amanita Sen, a post-graduate in English Literature from Kolkata University, is a poet, editor, and literary critic. Her poetry collections have received considerable acclaim in both India and other English-speaking regions. Her works have been widely published in numerous esteemed literary journals over the years. In recognition of her contributions to poetry, she has been awarded the prestigious “Dr. Maheswar Neog Memorial IPPL” Award. Beyond her literary achievements, Sen is actively engaged in moderating and participating in academic and literary activities on a consistent basis.", "photo": "assets/writers/381-earth-voice-v1.webp"}, {"id": "writer-97", "name": "Amit Shankar Saha", "bio": "Amit Shankar Saha is an award-winning short story writer and poet. He is the author of three collections of poems. His works have been included in Best Indian Poetry 2018, the Yearbook of Indian Poetry in English 2020 and 2021 and Converse: Contemporary English Poetry by Indians. His first poetry collection Balconies of Time was nominated for the Griffin Poetry Prize. He has also been nominated for the Pushcart Prize and Best of Net anthology and has won the Wordweavers Prize both for short story and poetry. His works have appeared in magazines, journals and anthologies nationally and internationally. He has a PhD in English from Calcutta University and teaches as an Assistant Professor in the Department of English at Seacom Skills University.", "photo": "assets/writers/97-earth-voice-v1.webp"}, {"id": "writer-52", "name": "Amita Roy", "bio": "Amita Roy, former associate professor of English in a college resides in Kolkata. She is a Translator, short story writer poet and reviewer. She has five published books to her credit and another book is on the anvil.", "photo": "assets/writers/52-earth-voice-v1.webp"}, {"id": "writer-83", "name": "Amiya Ranjan Mohapatra / ଅମିୟ ରଞ୍ଜନ ମହାପାତ୍ର", "bio": "", "photo": "assets/writers/83-earth-voice-v1.webp"}, {"id": "writer-129", "name": "Anadi Charan Pradhan", "bio": "Anadi Charan Pradhan, M.A.(Eng) M.Ed, is a retired Vice Principal from Navodaya Vidyalaya Samiti with teaching experience of more than three decades as TGT and PGT English in different JNVs. He has a keen interest in literature and he writes poems and short stories related to life and nature in both Odia and English with equal flare. He is co-translator of Rivulets of Reflections, a collection of translated short stories.", "photo": "assets/writers/129-earth-voice-v2.webp"}, {"id": "writer-460", "name": "Anamika Nath", "bio": "Dr. Anamika Nath is an Assistant Professor of Forensic Medicine at Tezpur Medical College and Hospital, Assam. A poet, short story writer, and researcher, her work has been recognized through several national and international literary awards, including the Delhi Poetry Slam Award (2023), the Deepti Srivastava Memorial Award (2025), the Verse of Silence Award (2025), the Bharat Award for Literature (2026), and the Rabindranath Tagore International Poetry Award (2024). Her poetry and fiction have appeared in various journals and anthologies. She serves as Poetry Editor at The Boundless Press and is a member of the Bangla Academy, Agartala, and the Assam Sahitya Sabha. Her writing often explores memory, grief, medicine, womanhood, and the intersections between science and the human condition.", "photo": "assets/writers/460-earth-voice-v1.webp"}, {"id": "writer-194", "name": "Ananya Goswami", "bio": "A writer and poet by heart, Ananya Goswami is a relentless learner of art and literature. She looks forward to make a difference in the world with the power of her words. Her works have been published in many prestigious online and print publications.", "photo": "assets/writers/194-earth-voice-v1.webp"}, {"id": "writer-74", "name": "Aneek Chatterjee", "bio": "Aneek Chatterjee is a poet and academic. He has been published in several reputed literary magazines and anthologies across the globe. He has authored and edited 16 books including four poetry collections and a novel. Chatterjee has a Ph.D. in International Relations and he has been teaching in leading Indian and foreign universities. He was a Fulbright Visting Professor at the University of Virginia, USA and a recipient of the prestigious ICCR Chair (Govt of India) to teach abroad. His poetry has been archived at Yale University.", "photo": "assets/writers/74-earth-voice-v1.webp"}, {"id": "writer-170", "name": "Angurbala Parida", "bio": "Angurbala Parida is a Rourkela based prolific poet who has six poetry collections to her credit.", "photo": "assets/writers/170-earth-voice-v1.webp"}, {"id": "writer-171", "name": "Anindita Bose", "bio": "Anindita Bose`s `I-Know-the-Truth-of-a-Broken-Mirror` (Writers-Workshop-2018), ‘illuminate-darkness-the-fireflies’ (Raa-Publication- 2020) and short stories collection ‘words-breathe-in-silence’ (Ukiyoto-2022) are widely acclaimed. Co-edited Dynami-Zois [Life Force] (Virasat-Art-Publication). Independent scriptwriter of short film, Anubhobe (2020). An academician and a translator of several Bengali books written by popular authors from Kolkata. Co-founder of Rhythm-Divine-Poets, editor of EKL-Review, program manager of Chair Poetry Evenings, Kolkata’s International-Poetry-Festival.", "photo": "assets/writers/171-earth-voice-v1.webp"}, {"id": "writer-323", "name": "Anish Kanjilal", "bio": "Kanjilal has a heart and soul like us full of emotions – he laughs in pain, and weeps in anger yet fulfills his routine responsibilities to get going. His beliefs are framed around the notion of `constantly` committing good to negate the evil deed, which is portrayed through his composed poetry. In 2015, he penned his first book titled Fateless 13 (publisher: partridge) , an accumulation of thirteen poems that demonstrate every aspect of life, beginning from birth to death. After more than six years, in 2022, he authored the book 11 Oracles, published by White Falcon Publishing which comprises a five-part series of poems. In addition, he is a director and senior lecturer at Educare The Institute (E.T.I) Kolkata, one of the prestigious academic institute that has guided over 15000 students. In 2009, he received recognition for contributions in literature and education sector from Rajasthan Patrika and was awarded the best poet award in the kolkata literary Carnival 2024.", "photo": "assets/writers/323-earth-voice-v1.webp"}, {"id": "writer-380", "name": "Anita Panda/ अनिता पंडा", "bio": "Anita Panda is a Mumbai based author-poet, Blogger, Flash-fiction, Features writer, Nature lover & an aspiring Bollywood lyricist. A self-published author of `GENESIS`, dedicated to her valiant Late Brother, she is a prolific writer widely anthologised & her work published in- `TOI, Mumbai Mirror, New Woman & eShe`. `SONGS OF MY SOUL`- is her debut Book & her work showcased on global literary platforms- UBI, The Fertile Brains, Virtual Book Fair India (VBFI) & upcoming `Paraguay International Book Fair`.", "photo": "assets/writers/380-earth-voice-v1.webp"}, {"id": "writer-240", "name": "Anita Ray", "bio": "", "photo": "assets/writers/240-earth-voice-v1.webp"}, {"id": "writer-379", "name": "Anjali Pattnaik / ଅଂଜଳି ପଟ୍ଟନାୟକ", "bio": "A poet from Odisha her poems get published in different journals and magazines. She`s also very active in social media.", "photo": "assets/writers/379-earth-voice-v1.webp"}, {"id": "writer-130", "name": "Anjali Sahoo", "bio": "Anjali Sahoo is a bilingual poet, writing both in English and Odia. Her published works include 3 poetry books, two short story books in Odia and one poetry book A TRYST WITH THUNDER in English. She has earned her M.A. in English Literature.", "photo": "assets/writers/130-earth-voice-v1.webp"}, {"id": "writer-292", "name": "Anju kapoor", "bio": "Anju kapoor is an avid and a sensitive writer. She is currently residing in the Kingdom Of Bahrain . Born in Shimla, Himachal pradesh, she has done her Masters in Banking and Finance from University of Mumbai She is a bilingual poet, in English and Hindi. Her emotions lends a voice to her poems. Pen and paper are her wings and rhymes her lifeline Power and beauty for poetry to her is the ability of her words to transcend in time, language and culture. Her compelling thoughts lends a voice to her writing Her poems have been published in various Anthologies, and she shares creative space with many gifted poets on various Global platforms", "photo": "assets/writers/292-earth-voice-v1.webp"}, {"id": "writer-433", "name": "Annwesa Abhipsa Pani", "bio": "Annwesa Abhipsa Pani is a poet and organisation and people development professional and a student of English Literature based in Pune . Born in Rourkela, Odisha, her work explores silence, belonging, and the delicate negotiations between inner and outer worlds. Her poems often linger at the intersections of tenderness and restraint, drawing from everyday moments to uncover quiet revelations. When not writing, she works in organizational and leadership development, where her fascination with human growth continues in another language — that of empathy, learning, and change.", "photo": "assets/writers/433-earth-voice-v1.webp"}, {"id": "writer-456", "name": "Antara Mukherjee", "bio": "An editor of 3 books and a member of Review Boards of International Journals, Dr Antara Mukherjee, Associate Professor, PG Dept of English, Taki Government College, has been a part of WBES, Govt of WB, for twenty years. She has several National and International publications to her credit and has presented in India and abroad. She has completed 3 International projects and has also tried her hands at directing documentaries. She has been the External Reader of dissertations, Central European University, Budapest, Hungary, and an Adjudicator, Alliance University, Bangalore. Awarded with a Letter of Excellence by Global South Colloquium, University of Victoria, she is also a bilingual poet and short story writer who loves to travel, observe, listen to the sounds of winds and rain to medicate herself; her creative works have appeared in Setu, The Gray Sparrow Journal, Kitaab, Boderless Journal, The Chakkar, Bombay Duck, Lothlorien Poetry Journal, Café Dissensus, Prayas: Ei Somoy, Char Number Platform, Dear O Deer! etc.", "photo": "assets/writers/456-earth-voice-v1.webp"}, {"id": "writer-131", "name": "Antaryami Mishra", "bio": "Antaryami Mishra is a bi-lingual poet writing both in Odia and English. He has acollection of Odia poems —-“Maa Nishaada” (2017). He is a regular contributor to more than 20 national and international literary forums and published in half a dozen of international Anthologies. Poetry for him is a passion, a manner of dreaming and leading happy life. Odisha, ( India.", "photo": "assets/writers/131-earth-voice-v1.webp"}, {"id": "writer-91", "name": "Anu Girdhar", "bio": "Dr. Anu Girdhar is MDS in Prosthodontics, Professor and HOD In National Dental college DeraBassi . She is the national president of Women Dental Council as well. Her journey in poetry started during the period of lockdown. She has written many poems and some of them have been published in various web magazines and various anthologies. She is the author of books\" As the life unfolds \" and \"Heartstrings\".", "photo": "assets/writers/91-earth-voice-v1.webp"}, {"id": "writer-253", "name": "Aparna Mohanty /", "bio": "Aparna Mohanty is an Odia poet residing at Kendrapara. She is a recipient of Odisha Sahitya Akademi Award for poetry.", "photo": "assets/writers/253-earth-voice-v1.webp"}, {"id": "writer-260", "name": "Aparna Pradhan", "bio": "Aparna Pradhan, doctorate in Zoology is a bilingual author, poetess, writer, moderator and an artist. She has authored three Hindi Poetry books “?? ?????? ??????”, ??????? ?? ????????, ??… ??? ?? ???. Her paintings adorn the cover pages of all her books. She has published articles in leading newspapers and magazines. Her poems have been published in International and National magazines, newspapers and anthologies (Hindi and English). She has contributed poems and writes ups in more than 45 anthologies.", "photo": "assets/writers/260-earth-voice-v1.webp"}, {"id": "writer-92", "name": "Archana Bahadur Zutshi", "bio": "Dr Archana Bahadur Zutshi has three published volumes of poetry. Featured poet by `Culturium` (March 18, 2019) and `Poetic Candour` added to their collection.The Speaking Muse was featured in The Asian Extract, a print Magazine. `Careless Verse Whispers` is available on Kindle. Her translated novel is `Meerabai the Legend: Her Life and Struggle as a Woman` (Kindle) Her poems have found space in well-known anthologies and journals. Her detailed interviews appeared in print by The Poet Magazine (UK), 21st Century Critical Thought Volume 2 (India).", "photo": "assets/writers/92-earth-voice-v1.webp"}, {"id": "writer-113", "name": "Arti Kumari", "bio": "Dr. Arti Kumari is a bilingual poet writing both in Hindi and English. She is a lecturer in Govt Teacher Training College in Bihar. Her articles and poems are being published in the reputed journals. She has one book of hindi poems `Dhadkanon ka Sangeet` and one book of Ghazals `Sath Rakhna Hai` to her credit. She has edited two books of ghazals, namely, `Ye Naye Mizaj Ka Shahar Hai` and `Bihar ki Mahila Ghazalkar`. She loves to write about nature, love, social issues and different shades of life. Her poems are being telecast on Doordarshan. She is being honoured by many awards for her contribution to the literature.", "photo": "assets/writers/113-earth-voice-v1.webp"}, {"id": "writer-415", "name": "Arun Sahu", "bio": "Arun Sahu is a diplomat, writes in English and Odia.", "photo": "assets/writers/415-earth-voice-v1.webp"}, {"id": "writer-20", "name": "Arundhati Mohanty/ ଡ. ଅରୁନ୍ଧତୀ ମହାନ୍ତି", "bio": "Dr Arundhati Mohanty M.A,M.Phil,(from Vanivihar) Ph.D from ViswaBharati Shanti niketan", "photo": "assets/writers/20-earth-voice-v1.webp"}, {"id": "writer-321", "name": "Ashish Vidyarthi/ आशीष विद्यार्थी", "bio": "Ashish Vidyarthi ia a wellknown Hindi poet.", "photo": "assets/writers/321-earth-voice-v1.webp"}, {"id": "writer-286", "name": "Ashok Bhargab", "bio": "Ashok Bhargava is a bilingual Canadian poet. His poetry reveals a world of light & peace and welcomes the reader into a fresh understanding about the meaning of life. His poetry whispers the secrets of life and shows the joys of living in a moment. He has authored seven books of poetry.", "photo": "assets/writers/286-earth-voice-v1.webp"}, {"id": "writer-158", "name": "Ashok Kumar Singh/ ଡ଼ଃ ଅଶୋକ କୁମାର ସିଂହ", "bio": "Ashok Singha is a management professional with 30 years of experience. He has been writing since class V. He has authored 11 anthologies of Odia poems and one anthology in English The raging tide and quiet shore . He has also authored a bilingual book Drishyantar .", "photo": "assets/writers/158-earth-voice-v2.webp"}, {"id": "writer-206", "name": "Asish Kumar Mishra/ ଆଶିଷ କୁମାର ମିଶ୍ର", "bio": "Asish Kumar Mishra is a promising young poet from Subarnapur district, Odisha. His poems get published in various magazines regularly.", "photo": "assets/writers/206-earth-voice-v1.webp"}, {"id": "writer-275", "name": "Avantika Vijay Singh", "bio": "Avantika Vijay Singh has been awarded the Nissim International Award 2023 Runners-up for poetry. Poetry is her song from the heart to express her thoughts and emotions. Flowing…in the river of life is her first published book of poems on paperback.", "photo": "assets/writers/275-earth-voice-v1.webp"}, {"id": "writer-73", "name": "Babita Mohapatra/ବବିତା ମହାପାତ୍ର", "bio": "Babita Mohapatra is an Advocate and Social Worker turned Poet. She resides in Rourkela the industrial city of Odisha. She is involved with many socio cultural organisations and she is an avid reader.", "photo": "assets/writers/73-earth-voice-v1.webp"}, {"id": "writer-409", "name": "Badal Mohanty/ ବାଦଲ ମହାନ୍ତି", "bio": "Badal Mohanty writes poetry, novel and stories in Odia. He is the proprietor of prestigious publisher Barsha publications.", "photo": "assets/writers/409-earth-voice-v1.webp"}, {"id": "writer-405", "name": "Baijnath Gupta", "bio": ": Dr. Baijnath Gupta is Associate Professor and Head, Department of English, DSN Postgraduate College, Unnao (Affiliated to CSJM University, Kanpur). He has edited an Anthology of Poems and has contributed thirty one research papers/articles to various National and International journals and edited books. Some of his poems have found spaces in such prestigious journals as Setu Bilingual Journal (published from Pittsburgh, USA), Creative Saplings and The Wise Owl. He has also contributed some poems to some anthologies including \"The Silent Syllables of the Heart\" edited by Orbindu Ganga. Moreover, he has also published a book of poems titled \"Echoes of a Sensitive Heart\".", "photo": "assets/writers/405-earth-voice-v1.webp"}, {"id": "writer-124", "name": "Balaram Pujari/ବଳରାମ ପୂଜାରୀ", "bio": "", "photo": "assets/writers/124-earth-voice-v2.webp"}, {"id": "writer-439", "name": "Banasmita Pati", "bio": "Banasmita Pati is a bilingual poet , writer and podcaster based in Bhubaneswar.", "photo": "assets/writers/439-earth-voice-v1.webp"}, {"id": "writer-437", "name": "Bandana Sahoo", "bio": "Bandana Sahoo is a young writer and her pen name is \"Shibangi Dhara\". She belongs to Jajpur, Odisha. She writes in Odia, English and Hindi languages. Apart from poetry, she also likes to write Fiction, Article,Quotes, Columns , Novels etc.", "photo": "assets/writers/437-earth-voice-v1.webp"}, {"id": "writer-477", "name": "Bani Mohanty", "bio": "Bani Mohanty writes poetry in English.", "photo": "assets/writers/477-earth-voice-v1.webp"}, {"id": "writer-271", "name": "Bebina Rath/ ବେବିନା ରଥ", "bio": "Bebina Rath alias Smita writes in Odia. She is a Post Graduate in Odia from Utkal University. She introduces herself as a Home maker. She resides in VSS Nagar, Bhubaneswar, Odisha.", "photo": "assets/writers/271-earth-voice-v1.webp"}, {"id": "writer-54", "name": "Bhagaban Jayasingh", "bio": "Bhagaban Jayasingh: is an eminent bilingual writer, who has published nine books in Odia, including Sahitya Akademi award winning Ferranti Ghar and about seven in English and English translation. Black Eagle Books has published The Dapples of Darkness, an anthology of his poetry in English and Footprints of Fire, a translation of seventy-four contemporary Odia poets. Recently Central Sahitya Akademi has brought out Sitakant Mahapatra: A Reader, edited by him. His critical work on modern Odia poetry Door to Despair: Modernism in Odia Poetry has been published by Authors Press, New Delhi. Dr Jayasingh has received a flurry of literary awards, including Vishub Jhankar, Jivan Rang, Utkal Sahitya Samaj and Odisha Sahitya Akademi awards for poetry.", "photo": "assets/writers/54-earth-voice-v1.webp"}, {"id": "writer-119", "name": "Bhagirathi Mishra/ ଭାଗିରଥି ମିଶ୍ର", "bio": "Bhagirathi Mishra (1958) is a well-known poet and translater from Odisha. He has published four collections of Odia poems and translated many world poets into Odia. Contact: ", "photo": "assets/writers/119-earth-voice-v1.webp"}, {"id": "writer-133", "name": "Bhagyashree Mishra", "bio": "Bhagyashree Mishra is a Software Engineer by profession. Presently, she is on a career break and plans to continue her education to advance her career. Her passions include weaving her emotions into poems, crafting short stories, and writing essays and articles. She is from the beautiful town of Sunabeda in the state of Odisha. Her poetry vividly depicts social issues, a love of nature, soulful romance, and patriotism. She passed the Cambridge University ESOL Examination and received British English Council (BEC) certification. Manosodhanam, a literary platform that nurtures young writers, awarded her the Manosrijan award in 2017.", "photo": "assets/writers/133-earth-voice-v1.webp"}, {"id": "writer-386", "name": "Bharadwaj Mishra", "bio": "Bharadwaj Mishra, November 1975 Odisha born, a Delhi University Post Graduate in Social Sciences, with a professional career in banking for over two decades, is engaged in creative writing and is involved with the Film Society of Bhubaneswar. As on date he has two English poetry collections published, “Farewell To Kalpana Saikia” (Author`s Press, New Delhi) and “Bathing Ghat At Kotipalli” (Athena Books, Bhubaneswar). He has published English Essays, Poetry and Short Stories with English language magazine of Kendriya Sahitya Academy, Indian Literature, Woman`s Era and with few others. He has done English subtitles for Odia language film and does captions for paintings and photographs. He is single and lives with his parents in Bhubaneswar.", "photo": "assets/writers/386-earth-voice-v1.webp"}, {"id": "writer-429", "name": "Bharati Hazarika", "bio": "Bharati Hazarika is a multilingual poet from Lakhimi Nagar, Guwahati. She is a poet, children`s writer, story and essayist, lyricist and composer at the same time. Her poems, children`s poems, stories, short stories , children`s stories, essays etc. have been published in Assamese, national and international newspapers, books, magazines, e-magazines etc. in Assamese, English, Hindi and Bengali.", "photo": "assets/writers/429-earth-voice-v1.webp"}, {"id": "writer-390", "name": "Bharati Nayak", "bio": "Bharati Nayak writes English poetry.", "photo": "assets/writers/390-earth-voice-v1.webp"}, {"id": "writer-47", "name": "Bhaskaranand Jha Bhaskar", "bio": "Bhaskaranand Jha Bhaskar is a trilingual poet (Maithili, Hindi and English), short story writer, critic and reviewer. Regularly published in various national and international magazines, both printed and online he has to his credit three collections of poems in English: Soothing Serenades: Straight From the Heart (2018), Two Indias and Other Poems (2019) and Thoughts in Solitude (2020). One of his poems on Nelson Mandela is included in the academic syllabus prescribed for the school students of Philippines. Besides, he is also a contributor to journals like The Criterion: An International Journal in English, IJML (International Journal On Multicultural Literature), The Anvil (Forum of Literature & Academic Research in English) and Harvests of New Millennium, The Interiors, Taj Mahal Review, IJES (The Indian Journal of English Studies). He is also the Review Editor of Asian Signature, a literary e-journal, managed from Kolkata.", "photo": "assets/writers/47-earth-voice-v1.webp"}, {"id": "writer-32", "name": "Bhaswati Basu/ଭାସ୍ୱତୀ ବସୁ", "bio": "", "photo": "assets/writers/32-earth-voice-v1.webp"}, {"id": "writer-216", "name": "Bibhu Padhi", "bio": "Bibhu Padhi was born on 16 January 1951 in Cuttack, Odisha.He studied at Ravenshaw College, Cuttack for Master of Arts in English literature in 1971. He received a Doctor of Letters (D.Litt.) from Utkal University in 1991 in English literature. He has 13 volumes of poetry in English and 5 volumes of poetry in Odia. His poems have been included in numerous anthologies. He has also authored a novel, called Absences.", "photo": "assets/writers/216-earth-voice-v1.webp"}, {"id": "writer-329", "name": "Bichitra Dash/ ବିଚିତ୍ରା ଦାଶ", "bio": "Bichitra Dash writes in Odia. Postgraduate in three languages i.e. Odia, Sanskrit and Hindi, Bichitra Dash resides in Puri.", "photo": "assets/writers/329-earth-voice-v1.webp"}, {"id": "writer-80", "name": "Bidyutaprava Gantayat/ ବିଦ୍ୟୁତ ପ୍ରଭା ଗନ୍ତାୟତ", "bio": "Prof Dr Bidyut Prabha Gantayat is a contemporary poet ,writer and translator of Odia language . She pens for children and an acclaimed haiku poet . She has published about twenty books to her credit comprising poetry , short stories and essays and translation . Her translation of works of Mahadevi Verma of Hindi literature and Gyanpeeth awardee is commandable. Kendra Sahiya Academy has published her translated Anthology of poems from Hindi to Odia of award winning poets . . Bidyut Prabha is a retired professor of Chemistry and lives in Bhubaneswar with her family .", "photo": "assets/writers/80-earth-voice-v1.webp"}, {"id": "writer-406", "name": "Bijay Mohapatra/ବିଜୟ ମହାପାତ୍ର", "bio": "Bijay Mahapatra is a senior poet and critic based at Bhubaneswar after his retirement as a Reader in Odia. He has four poetry collections and one book of criticism to his credit.", "photo": "assets/writers/406-earth-voice-v1.webp"}, {"id": "writer-179", "name": "Bijayalaxmi Rath", "bio": "Bijayalaxmi Rath is from Bhubaneswar. Done Master in English from Utkal University Bhubaneswar Odisha. Works as PGT, English in St Xavier International school Patia. She is a Multilingual poetess, recipient of various awards in respected poetic meets, Olive Ridley poetic meet, Naba chetana etc. She has been published in various respected anthologies.", "photo": "assets/writers/179-earth-voice-v1.webp"}, {"id": "writer-24", "name": "Bina Singh", "bio": "Prof. Bina Singh born and brought up in Varanasi, obtained her M. A. PhD in English from BHU Varanasi. Prof. Singh, former head of the department of English Vasant Kanya Mahavidyalaya BHU Varanasi. Presently Ms Singh is President of Kashi Tatav Sabha Theosophical Society Indian section Varanasi. Prof. Singh taught English literature and language for 40 years. Her area of interest is American literature, feminist literature Indian literature and other world literature. Dr. Singh has chaired participated and organized various national and international seminars conferences, literary festival and workshops. She has published 8 books, 3 on literature and 5 anthology of poems. Prof. Singh has received many national and international awards and recognition for her service to literature and humanity. Dr. Bina Singh is member of various academic and socio cultural organizations. Dr. Singh is patron of Vaidik foundation Kashi and Ashav, war against cancer. Literature is her passion and poetry first love. She believes that serving the suffering is serving the Supreme.", "photo": "assets/writers/24-earth-voice-v1.webp"}, {"id": "writer-346", "name": "Binapani Debta / ବୀଣାପାଣି ଦେବତା", "bio": "", "photo": "assets/writers/346-earth-voice-v1.webp"}, {"id": "writer-370", "name": "Binati Satapathy/ ବିନତି ଶତପଥି", "bio": "Binati Satapathy writes poetry in Odia. She resides at Bolangir.", "photo": "assets/writers/370-earth-voice-v1.webp"}, {"id": "writer-447", "name": "Binay Laha", "bio": "Binay Laha has authored many books in English.He is the editor of Indology English Magazine,the oldest surviving printed english little magazine of West Bengal.", "photo": "assets/writers/447-earth-voice-v1.webp"}, {"id": "writer-217", "name": "Binaya Kumar Mohanty / ବିନୟ କୁମାର ମହାନ୍ତି", "bio": "Binaya Kumar Mohanty was born in 1968 in a remote village Anduli, of Kendrapara District. Mr Mohanty has been working as a College teacher in the Department of higher education in the subject Animal Science. Among his literary work a collection of Odia Poems `ANANDE EKBAR` got published. His poems are expressive of grim realities of life,shattered illusion and romantic dreams.", "photo": "assets/writers/217-earth-voice-v1.webp"}, {"id": "writer-320", "name": "Binod Kumar / विनोद कुमार `बल्लोपुरी`", "bio": "Binod Kumar is a distingished Hindi poet.", "photo": "assets/writers/320-earth-voice-v1.webp"}, {"id": "writer-159", "name": "Bipin Naik/ ବିପିନ ନାୟକ", "bio": "Bipin nayak established himself as as a leading voice in contemporary odia poetry He has won odissa sahitya akademi award along with many prestigious award s like, jhankar puraskar, gangadhar meher kabita samman, koraput literary festival award,sarala sarswat samman, chandrabhaga samman and many more awards Bipin Nayak has an inimitable style and stance for his free play words and for his ability to evoke a deeper sense of understanding of poetry .", "photo": "assets/writers/159-earth-voice-v1.webp"}, {"id": "writer-61", "name": "Bipin Patsani", "bio": "Bipin Patsani (b.1951) has published poems in many prestigious literary journals and over fifty poetry anthologies brought out in India and elsewhere. He has published three poetry collections: VOICE OF THE VALLEY (W/W, 1993), ANOTHER VOYAGE (2010) and HOMECOMING(2010). Three more collections are in manuscript forms from which almost all poems have appeared in different journals. He is a recipient of Michael Madhusudan Award in 1996 for Voice of The Valley and received Rock Pebbles National Award in 2018. A Post Graduate in English from Ravenshaw College, Cuttack (1973-1975), he lives with his family at Barunei Colony, Badatota in Khordha District of Odisha after his retirement in 2012 from Arunachal Pradesh, where he worked as a teacher for 34 years and received State Award in 2002.", "photo": "assets/writers/61-earth-voice-v1.webp"}, {"id": "writer-473", "name": "Bishnu Charan Parida", "bio": "Bishnu Charan Parida is a bilingual poet from Jajpur Road of Odisha. Professionally an engineer though, he loves poetry. His poems have been published in many anthologies and magazines of national and international repute. He has been awarded in the state level Kalinga Nagar book festival, Odisha in 2015, honored in the 11th Guntur International Poetry Festival, honored as a World Featured Poet 2019 of Pentasi-B, China. He also received the 8th R.N.Tagore award from X-press Publications, Kerala", "photo": "assets/writers/473-earth-voice-v1.webp"}, {"id": "writer-407", "name": "Biswanath Kundu", "bio": "A science graduate and a retired Accounts Official in Indian Railways, Biswanath Kundu (b.1963) is an author of fourteen books, seven of them being books of poems. His poems and articles have been published in different prestigious anthologies and internationally famous journals. He has co-authored two books of criticism with Dr. Ramesh Chandra Mukhopadhyaya. ", "photo": "assets/writers/407-earth-voice-v1.webp"}, {"id": "writer-202", "name": "Boby Borah", "bio": "Boby Borah writes in English with three poetry collections to her credit. She is the Founder/ Pricipal of Shankardev Shishu Niketan, Doom Doom, Assam.", "photo": "assets/writers/202-earth-voice-v1.webp"}, {"id": "writer-134", "name": "Braja K Sorkar", "bio": "Braja K Sorkar, a bilingual poet, editor and Essayist. His major published works includes - Nine titles in Bengali (Poems and Prose) and a collection of English poems “ Syllables of Broken silence” and selected poems of Hiren Bhattacharya (Assames) in Bengali translation. His poems have been translated in English, Hindi, Assamese and Manipuri and also included in many anthologies .Braja K Sorkar is the editor of the prestigious literary journal `Trstoop` since 2001. Braja K Sorkar edited a few anthologies including an anthology, titled `Voices Now: World Poetry Today` and also Modern Manipuri Poetry in translation. He has started a new Literary journal in English ,titled ` Eastern Poetry Review` recently. He is associated with Sahitya Akademi as a Translator. He lives at Durgapur,West Bengal. Contact: , ", "photo": "assets/writers/134-earth-voice-v1.webp"}, {"id": "writer-219", "name": "Chaitali Chattopadhyay", "bio": "Chaitali Chattopadhyay, born and brought up in Kolkata, studied physics as major at college. Worked in various fields of the creative world including copy writing in advertising. basically a poet, but also a storywriter and essayist. Acclaimed author of several books in Bengali and a regular columnist for leading newspapers and popular magazines. She is recipient of several prestigious governmental and non-governmental awards. She loves music, traveling and making friends.", "photo": "assets/writers/219-earth-voice-v1.webp"}, {"id": "writer-355", "name": "Chaitali Sengupta", "bio": "Chaitali Sengupta is an accomplished writer and translator, and her works travel fluidly between fiction, poetry, non-fiction, and works on translation. Her latest book “The Crossings-poems on War, migration & Survival won the Runners-Up award at the London Book Festival 2024. She garnered recognition for her debut collection of prose poems, “Cross Stitched Words,” which earned the `Honourable Mention` award at the New England Book Festival in 2021. Her expertise in translation is evident in her notable work, “Timeless Tales in Translation,” which received the special jury award at the Panorama International Literature Festival in 2023. With three translation books to her name, Chaitali has been a consistent contributor to both online and print media.", "photo": "assets/writers/355-earth-voice-v1.webp"}, {"id": "writer-338", "name": "Chirashree Indrasingh", "bio": "Chirashree Indrasingh is an eminent story teller, poet and trnslater writing in Odia.", "photo": "assets/writers/338-earth-voice-v1.webp"}, {"id": "writer-204", "name": "Chittaranjan Mishra/ ଚିତ୍ତ ରଞ୍ଜନ ମିଶ୍ର", "bio": "", "photo": "assets/writers/204-earth-voice-v2.webp"}, {"id": "writer-250", "name": "Daipayan Nair", "bio": "Hailing from Silchar, Assam, India, Daipayan Nair is a haikuist. He writes micropoetry, mostly haiku and tanka poems. His works have been featured on various international platforms and weekly columns like Haiku Dialogue of The Haiku Foundation, Haiku in Action of Nick Virgilio Haiku Association, and FreshOutMag. He has also been published in the Frogpond Journal, the prune juice journal, Under the Basho Journal, Failed Haiku Journal, Cold Moon Journal, Scarlet Dragonfly Journal, Triya Mag, Kingfisher Journal, Poetry Pea Journal, Time Haiku Journal, Failed haiku — a journal of English Senryu, the Akitsu Quarterly, The Wales Haiku Journal among others. His haiku, senryu and tanka have appeared in the prestigious monthly of haikuKATHA from Triveni Haikai India. His recent collection of haiku and senryu titled \"tilt of the winnowing fan\" was published in 2022 by Hawakal.", "photo": "assets/writers/250-earth-voice-v1.webp"}, {"id": "writer-29", "name": "Debajani Ray/ଦେବଯାନୀ ରାୟ", "bio": "", "photo": "assets/writers/29-earth-voice-v1.webp"}, {"id": "writer-67", "name": "Debajani Tripathy/ଦେବଯାନୀ ତ୍ରିପାଠୀ", "bio": "Debajani Tripathy is an USA based Odia poet. who has two Poetry collections to her credit.", "photo": "assets/writers/67-earth-voice-v1.webp"}, {"id": "writer-56", "name": "Debarati Sen", "bio": "Debarati Sen works in Presidency University Kolkata as a Junior Assistant. Her debut poetry book called `Blurred Musings` was published in January 2022 and was launched by Literoma at the Newtown Book Fair. Recipient of the Tagore Award 2022 and the Sylvia Plath Women`s Literary Award, Debarati finds emancipation in her poetry! She has also been the winner of the International Poetry Writing competition held by the Elite Book Awards in November 2021. She has grabbed the third position in the National Poetry Writing Month 2022 contest hosted by the Elite Book Awards. Debarati features in the Council Year Book launched on the occasion of Women`s Day 2022 by Literoma in association with the Public Safety and Security Council of Bengal. She has also been declared as an Empanelled Author in the International Author`s Conclave held by Literoma in December 2021. She is one among the top ten poets of the Women;`s Day poetry contest organised by Delhi Poetry Slam. She has been recently nominated by Beyond the Box as a finalist for the BTB Wordsmiths Award 2022 as the most eloquent writer and for the category of the Most impactful contribution of the year 2022 (for the poem Time`s Tentacles). She has co-authored more than 15 anthologies and is recently compiling her first anthology as a compiler with the Quill House Publishers. Her poems have found shelter in prestigious websites like The Antonym, The Yugen Quest Review, The Kolkata Arts, Lapis Lazuli, The Das Literarisch, The Sindh Courier, Synchronized Chaos, to name a few.", "photo": "assets/writers/56-earth-voice-v1.webp"}, {"id": "writer-68", "name": "Debendra Lal/ଦେବେନ୍ଦ୍ର ଲାଲ୍", "bio": "", "photo": "assets/writers/68-earth-voice-v1.webp"}, {"id": "writer-284", "name": "Deepika Dash", "bio": "Deepika Dash is an Odia poet living in Berhampur. She has three collection of poetry to her credit.", "photo": "assets/writers/284-earth-voice-v1.webp"}, {"id": "writer-452", "name": "Devendra K Mishra", "bio": "Devendra K Mishra is the author of The Cursed Crow, Whenever I Feel, The Cara Coffee Bar, and The Colour of Forgotten Sounds. He is drawn to the classics and sees living poetry woven through the natural world. Following no creed but a quiet religion of humanity, he feels blessed, contented, and serene. Literary activities bring happiness and peace of mind to him.", "photo": "assets/writers/452-earth-voice-v1.webp"}, {"id": "writer-373", "name": "Devika Tripathy", "bio": "A lifelong student of literature, always keen to learn the flow of words of verses in proses, poetry, essays and novels. Completed graduation at Savitri Women’s College, yr-1998. A devotee of music, and currently learning the most authentic Dhrupad style of Indian classical music from Guru Shri Mukund Dev Sahoo. Fluent in Odia, Hindi, English and American English. Goals: To continue acquiring more and more knowledge and resources by exploring authors and their work worldwide. To keep writing so my minute work can reach the masses of readers and would help me grow more as a worshiper of literature.", "photo": "assets/writers/373-earth-voice-v1.webp"}, {"id": "writer-251", "name": "Dhananjay Kumar", "bio": "Dhananjay Kumar is from village Padumker in East Champaran district of Bihar. He currently works for a People Awareness Campaign of the Indian Govt.", "photo": "assets/writers/251-earth-voice-v1.webp"}, {"id": "writer-23", "name": "Dilip Mohapatra", "bio": "Cmde Dilip Mohapatra, VSM (b.1950), a decorated Navy Veteran is a well acclaimed poet in contemporary English and his poems appear in many literary journals of and anthologies worldwide. He has six poetry collections, one short story collection and two professional books to his credit so far all published by Authorspress. He is the recipient of the prestigious Honour Award for complete work under Naji Naaman Literary Awards for 2020 and holds the honorary title of ‘Member of Maison Naaman pour la Culture’. He holds two masters degrees: in Physics and Management Studies. He lives with his wife in Pune. His website may be accessed at dilipmohapatra.com.", "photo": "assets/writers/23-earth-voice-v1.webp"}, {"id": "writer-344", "name": "Dilip Rakshit", "bio": "Dilip Rakshit is a bilingual poet and a regular contributor to various literary journal in India. He is a private teacher, teaches English literature. Apart from his literary activities, he is a painter, based at Durgapur, West Bengal . he may be contacted through .", "photo": "assets/writers/344-earth-voice-v2.webp"}, {"id": "writer-153", "name": "Dipak Samantarai", "bio": "Dipak Samantarai is a bilingual poet and broadcater. He is the Convenor of Cuttack Heritage Walks.", "photo": "assets/writers/153-earth-voice-v1.webp"}, {"id": "writer-36", "name": "Diptirekha Das", "bio": "Diptirekha Das is a bilingual poet;basically writing in English and Odia. She is also a blogger blogging both in English & Hindi. She hails from Bhubaneswar, Odisha. She is a post graduate in Economics from Utkal University. Literature is her passion. And writing poetry is her most doing activity so far. She has authored two poetry books in English & one book in Odia. She has also co-edited a multilingual literature anthology. Her poems, blogs & articles were featured in various national & international literary magazines. She loves to write addressing contemporary issues regarding women &society as well.", "photo": "assets/writers/36-earth-voice-v1.webp"}, {"id": "writer-454", "name": "Divya K Unni", "bio": "Born and spent growing years in Palakkad, Kerala. Lived in Dallas, Texas for a few years. Residing in Bangalore for the past two decades. Worked as a Lecturer in Dept of English, Kristu Jayanti University, Bangalore and Hindi translator in Ministry of Defence, India. Author of the poetry collection “UnBridled” published by Authorspress, 2025. Selected poems have featured in various online platforms like The Wise Owl Magazine, Asian Literary Society, Quotidian Quills, etc.", "photo": "assets/writers/454-earth-voice-v1.webp"}, {"id": "writer-236", "name": "Divya Vats", "bio": "Divya Vats is Founder/Director of ADITH AADVAN CONSULTANCY. She is a Parent coach, Counsellor, speaker, host, writer and author.", "photo": "assets/writers/236-earth-voice-v1.webp"}, {"id": "writer-198", "name": "Dola Dutta Roy", "bio": "Born and raised basically in Kolkata. Got my first Master`s in English Literature from Jadavpore University and later from Marquette University, USA. After a brief spell of work experience in the teaching profession in Calcutta, also taught English in Tehran and Rasht in Iran. Subsequently, left for the USA for further studies followed by years of being a lecturer at Claremont University, California. Returning to India, I joined the world of Advertising, working with JWT, a leading Ad agency in Calcutta. Have always loved travelling, learning languages, Music and Art.", "photo": "assets/writers/198-earth-voice-v2.webp"}, {"id": "writer-238", "name": "Eileen Moynihan", "bio": "", "photo": "assets/writers/238-user-selected-20261004.webp"}, {"id": "writer-55", "name": "Elanaaga", "bio": "Born in 1953 in Telanagana State, Elanaaga is a well-known poet, translator and critic in the field of Telugu literature. He is a paediatrician, but now only pursuing his literary interest. After working as a Medical Officer abroad for 6 years, he rendered his services in Andhra Pradesh VaidyaVidhanaParishat and retired in 2012 in the rank of Deputy Commissioner. He penned 31 books so far, 15 of which are original writings and 16 are translations. Of the latter, 8 are from English to Telugu, and 8 are from Telugu to English. His works comprise books of free verse, prosodic poems, experimental poetry, language-related essays, essays of criticism, standard crosswords and so on. He is an ardent lover of Indian classical music, especially Hindustani music.", "photo": "assets/writers/55-earth-voice-v1.webp"}, {"id": "writer-351", "name": "Eli Mohanty/ ଏଲି ମହାନ୍ତି", "bio": "", "photo": "assets/writers/351-earth-voice-v1.webp"}, {"id": "writer-211", "name": "Eva Petropoulou-Lianou", "bio": "Eva Petropoulou-Lianou was born in Xylokastro, Greece. She collaborates with the electronic literary magazine The poet c. She is the partner International Literary Union based in America. Collaborates for the promotion of literature and promotes the work of Greek poets. Eva is a member of the \"Association Alia Mundi Serbia\", the \"International Society of Writers and Artists of Greece\" and the \"Piraeus Society of Letters and Arts\" as well as the Corinthian Writers Society.", "photo": "assets/writers/211-earth-voice-v1.webp"}, {"id": "writer-446", "name": "GANESWAR BEHERA", "bio": "GANESWAR BEHERA is a bilingual poet, active both online and offline. Affiliated to many Literary Organisations holding responsible portfolios. He is also an active member of District Cultural committee Jajpur.", "photo": "assets/writers/446-earth-voice-v1.webp"}, {"id": "writer-135", "name": "Gargi Saha", "bio": "Ms Gargi Saha is a creative writer from Pune, India. She had an affinity for penning poems since her childhood. Her poems have been featured in National and International Journals like `Bizz Buzz`, `Poetcrit` `Poet`, `Contemporary Vibes` etc. She has published two poem books namely, `The Muse in My Salad Days` (2000) and `Letters to Him` (2012).Recently she has received the `Rabindranath Tagore Memorial Award for poetry and also the India Independence Day Award` for poetry.She can be reached at ", "photo": "assets/writers/135-earth-voice-v1.webp"}, {"id": "writer-163", "name": "Garima / गरिमा", "bio": "Garima Garg is a published poet and translator of repute. She`s well versed in multiple languages like Hindi, Punjabi and English. She has a number of publications to her credit. Based at Panchkula , Haryana she`s actively engaged in her literary journey.", "photo": "assets/writers/163-earth-voice-v1.webp"}, {"id": "writer-176", "name": "Gayatree G Lahon", "bio": "Hailing from Assam , Gayatree G Lahon is a teacher by profession and a poet by passion. She is a post graduate in English literature from Gauhati University .She is closely akin to nature and her poems delineate her feelings beautifully. Being a true aesthete, she finds beauty in every aspect of life and nature and her ink pours those elements in a subtle way .Even the complexities of life compel her to scribble in her own way. Her poems have been published in various anthologies and magazines, both in India and abroad.", "photo": "assets/writers/176-earth-voice-v1.webp"}, {"id": "writer-389", "name": "Gayatri Das", "bio": "Gayatri das writes both in English and Odia. She is from Anugul, Odisha.", "photo": "assets/writers/389-earth-voice-v1.webp"}, {"id": "writer-417", "name": "Gayatri Mavuru", "bio": "Gayatri Mavuru, an internationally renowned artist, multilingual poet, and educator, authored \"Sizzling Verses\" and \"Drizzling Colours.\" She holds two world records in art, an honorary doctorate for contributions to art and culture, and a Young Author Award. Currently, she is a school principal.", "photo": "assets/writers/417-earth-voice-v1.webp"}, {"id": "writer-264", "name": "Geethanjali Dilip", "bio": "Professor of French heading Zone Francofone, poet by passion, Geethanjali Dilip`s published poetry books include, « Geethatmaa , Song of the Soul » , “ Hansa Geetham- Song of the Celestial Swan”, “ Poetry Voice- Geeth Dhvani” , and « Soul Riff « - ATMATARANG « , “ Rosée- The Dewdrop “with good reviews. Recipient of “The Reuel International Award for Poetry`, awardee in the category of commendable mention for her poem at “ The Great Indian Poetry Contest”, awardee in “recognition of exhibiting literary brilliance par global standards”-Gujarat Sahitya Academy, Indian Women`s Achievers Award from Asian Literary Society, she curates Yercaud Poetry Festival, since 2018, strongly believing that poetry connects the world.", "photo": "assets/writers/264-earth-voice-v1.webp"}, {"id": "writer-99", "name": "Gopa Bhattacharjee", "bio": "English Poet Gopa Bhattacharjee is born and brought up in Kolkata. Though being an entrepreneur ,she is passionate and enthusiastic about weaving poetry relating to the realities of lives and diversities of nature. Her two poetry books UNTURNED VERSES and THIRTY BIRDS was published in Kolkata International Book Fair 2020 and 2022 . Her verses has been published in various national and international magazines and journals She has been the featured poet at the American Consulate, Tata Kolkata Lit Meet, Russian Consulate, Latin American Consulate ,Nagar Kirrtibas and many other cultural meets in and out of Kolkata.", "photo": "assets/writers/99-earth-voice-v1.webp"}, {"id": "writer-95", "name": "Gopa Nayak", "bio": "Gopa Nayak is a bilingual poet writing in English and Odia her mother tongue. Translating Odia literature to English is one of her favorite past times. Gopa is currently serving as the Director of English LanguageCentre at O. P. Jindal Global University, India. Gopa graduated from Ravenshaw College with a FirstClass Hons in Psychology and completed her education with a DPhilfrom theUniversity of Oxford, UK.", "photo": "assets/writers/95-earth-voice-v1.webp"}, {"id": "writer-39", "name": "Gopal Lahiri", "bio": "Gopal Lahiri is a Kolkata-based bilingual poet, critic, editor, writer and translator. He has 33 books in English and Bengali, including eight edited volumes. His poetry and prose appear in 150+ journals and anthologies worldwide, translated into 18 languages and published in 17 countries. He received the inaugural Jayanta Mahapatra National Award for Literature (2024), the Setu Excellence Award (2020, Pittsburgh, US), and was Poet of the Year at Destiny Poets, UK (2016). He was nominated for the Pushcart Prize (2021) and Best of the Net (2025). His work is included in `The Penguin Book of Poems on Indian Cities`.", "photo": "assets/writers/39-earth-voice-v1.webp"}, {"id": "writer-382", "name": "Gopikrishnan Kottoor", "bio": "Gopikrishnan Kottoor is a banker turned poet having multiple anthologies to his credit. His latest poetry releases include ` Poems from America` and ` A Land in the Sun.` He has won several national awards for his poetry. They have been included in journals ( Bloodaxe, Penguin, Sahitya Akademi) and anthologies of repute ( Best Asian Poetry, Converse, Both Sides of the Sky) in India and elsewhere ( Verse, Seattle, Plaza Japan, Nth Position, UK. Acumen, UK among various) .His seminal work ` Father , Wake Us in Passing,` won him an Augsburg Residency, and his work was", "photo": "assets/writers/382-earth-voice-v3.webp"}, {"id": "writer-79", "name": "Gourhari Das/ ଗୌରହରି ଦାସ", "bio": "Dr Gourahari Das is a prominent voice in contemporary Odia literature. He is a short story writer, novelist, translator,playwright , poet and columnist of repute. Along with many awards, he is recipient of Sahitya Akademi award twice, once for his original writing and secondly for translation.", "photo": "assets/writers/79-earth-voice-v1.webp"}, {"id": "writer-310", "name": "Goutam Jena/ଗୌତମ ଜେନା", "bio": "", "photo": "assets/writers/310-earth-voice-v1.webp"}, {"id": "writer-304", "name": "Haimanti Dutta Ray", "bio": "Haimanti Dutta Ray writes both poetry and prose. Since 2015, when her first book IN LOVING MEMORY was published, there`s been no looking back. But poems -whereby she expresses her emotions - comes first to mind so far as creative expression is concerned.", "photo": "assets/writers/304-earth-voice-v1.webp"}, {"id": "writer-164", "name": "Haraprit Kaur/ हरप्रीत कौर", "bio": "", "photo": "assets/writers/164-earth-voice-v1.webp"}, {"id": "writer-90", "name": "Hardaman Singh", "bio": "Hardaman Singh is a Bhubaneswar based bilingual poet. He writes both in English and Hindi. Poetry is a passion for him.", "photo": "assets/writers/90-earth-voice-v2.webp"}, {"id": "writer-63", "name": "Harinder Cheema", "bio": "Harinder Cheema is an internationally celebrated and versatile poet and author . She is the only Indian to receive the ` Naji Naaman International Literary Honor Prize for Complete Work in 2022`. She is the author of two Books, entitled,` The Temple Stop`and ` Soul Chants`.She is the co- author of 30 poetry anthologies and her articles have been published in various prestigious International magazines and Coffee Table Books. She is also the proud recipient of many prestigious global awards and honours in the field of Literature.Her name finds a mention in 101 most influential women 2020 and Glantor 100 Powerful Personalities 2022 and also in the National Book of Achievers as the , ` Most Creative Author`.", "photo": "assets/writers/63-earth-voice-v1.webp"}, {"id": "writer-400", "name": "Heba Fatima", "bio": "Heba Fatima is a Bhubaneswar based poet and a lecturer in English in a government aided college. She is a foodie who loves poetry and music.", "photo": "assets/writers/400-earth-voice-v1.webp"}, {"id": "writer-111", "name": "Himanshu Jena", "bio": "Himanshu Jena ( b.20.04.1980) is a bilingual poet, author,critic,teacher and researcher of global grace. His three anthologies, Tranquil Rapture ( 2019) , Spring of Serenity ( 2020) and Ripples of Reflection ( 2020) , have already been published and received wide acknowledgement throughout the world. His fourth and fifth anthology of poems , Heart of Humanity and Spectrum of Life ,are being published shortly. He beongs to Raipur under Jajpur district in Odisha, India.", "photo": "assets/writers/111-earth-voice-v1.webp"}, {"id": "writer-222", "name": "Himanshu Parida / ହିମାଂଶୁ ପରିଡା", "bio": "Himanshu Parida born 26th July 1959. Is a multilingual poet. He writes poems in Odia,Hindi and English. He has to his credit 6 Books of poem collection in Odia,one Book of poetry collection in Hindi and has published two story collection in Odia.His poems appeared in Odia literary magazines like Nabalipi,Gokarnika. Presently he has devoted more time in creative Criticism in Odia. His two most noteworthy books in Creative Criticism is Kabya Charcha and Metaphor. Shri Parida did his Master`s degree in English Literature and after a brief stint as a Lecturer in English in Colleges joined State Bank of India as an Officer. Now after retirement from service he has settled in Cuttack,Odisha.", "photo": "assets/writers/222-earth-voice-v1.webp"}, {"id": "writer-162", "name": "Hiranmayee Mishra/ ହିରଣ୍ମୟୀ ମିଶ୍ର", "bio": "Dr Hiranmayee Mishra has been writing poems, short stories and novels in Odia since last 32 years. She is an International Ford foundation fellow and currently teaching Gender Studies and Political Science in U.N. Autonomous College, Adaspur, Cuttack. She has been awarded Young Author Award by Kolkata Bhasha Parishad, Time Pass Booker Award, Kadambini award, Fakirmohan galpa Puraskar and many others. She has 15 story collections, 1 travelogue, 3 novels and 1 poetry collection published so far. She has edited a volume of stories, `Kinnara` , stories written in Odia on Transgender people which is published by Timepass publication.", "photo": "assets/writers/162-earth-voice-v1.webp"}, {"id": "writer-383", "name": "Inam Hussain Begg Mullick", "bio": "Inam Hussain Begg Mullick is an award-winning Kolkatan poet-editor and polymath. His most recent book of poems is The Magical Life of Inamorato (Writers Workshop). For many years, he wrote in The Statesman. He is the Director-Founder-Editor, The Kolkata Arts. Inam teaches Creative Writing.", "photo": "assets/writers/383-earth-voice-v1.webp"}, {"id": "writer-196", "name": "Ipsita Ganguli", "bio": "Ipsita Ganguli describes herself as Business Consultant at sunrise and Poet cum Travel Writer cum Heritage and Art Enthusiast at sunset. Ipsita writes...because she \"must\". Her poems have been published in several national and international e zines and anthologies .She is also one of the main characters of the poetryfilm Kolkata Cocktail. She has also ideated, conceptualised and conducted a series of online Talk Shows entitled Cafe Conversations as well as curated offline Poetry events for Kolkata Literary Meet at Victoria Memorial and at Kolkata Centre for Creativity, amongst others.", "photo": "assets/writers/196-earth-voice-v1.webp"}, {"id": "writer-118", "name": "Ipsita Sarangi/ଈପ୍ସିତା ଷଡ଼ଙ୍ଗୀ", "bio": "IPSITA SARANGI (1975): A leading voice of contemporary Odia poetry, a critic and translator ; has six poetry collections -Prakshi Pherini, Pheriba Katha, Punascha Buddha,Ketebele Kejani,Sabda Arapakha,Drushya Darpan; one book of critical essays,Ebara Kabita; and six translated books- Waiting for Manna: Stories of Sarojini Sahoo (co- translator),Childhood Days : Stories of Paresh Pattanaik co-translator),Octavio Paz nka Kabita,Bagha (Poetry Collection of Kedarnath Singh),Obscure Goddess : (co- translator of the story of Mahasweta Sahoo) vi)Manhattan Ru Munnar: Novel by Anantini Jhumpa Mishra. Recipient of State Youth Award, prestigious Utkal Mani Yuva Prativa Samman 2017, Chausathi Yogini Pratibha puraskar, Basanta Muduli Smruti Samman and many other awards. Her poems, translated into English and Hindi and Bengali ,are published in many national and international journals and magazines like The Orbis, Indian Literature, Samakaleen Bharatiya Sahitya, Aajkaal, Antaranga, Hamara Bharat, museindia, Kriti Bahumat, etc. Teaches English at Niali College, Cuttack", "photo": "assets/writers/118-earth-voice-v1.webp"}, {"id": "writer-246", "name": "Jagari Mukherjee", "bio": "The winner of the 2020 Women Empowered Award, Jagari Mukherjee is the Founder and Chief Executive Editor of the literary journal, EKL Review. She has authored five solo collections of poetry--two chapbooks and three full-length volumes. Her most recent collection is \"Exit Noire\" (2023) published by Bookwryter. Her book \"The Elegant Nobody\" (Hawakal, 2020) was shortlisted for the Rabindranath Tagore Literary Prize.", "photo": "assets/writers/246-earth-voice-v1.webp"}, {"id": "writer-301", "name": "Jay Jagdev", "bio": "Jay Jagdev is an entrepreneur, academic, action researcher and author. He is known for his work around sustainable development and policy implementation. He, as the President of Udayagiri Foundation, works to preserve and develop native language, literature, and heritage by improving its usage and consumption.", "photo": "assets/writers/301-earth-voice-v1.webp"}, {"id": "writer-93", "name": "Jayanta Mohapatra/ଜୟନ୍ତ ମହାପାତ୍ର", "bio": "", "photo": "assets/writers/93-earth-voice-v1.webp"}, {"id": "writer-71", "name": "Jayanti Rath/ଜୟନ୍ତୀ ରଥ", "bio": "Dr.Jayanti Rath is a noted Short story writer. Novelist and Researcher. A recipient of Odisha Sahitya Akademy Award for Short story, she has a good number of publications to her credit. She served as the Secretary, Odisha Sahitya Akademy and Superintendent of Odisha State Museum Bhubaneswar during her service career. After superannuation now she is now devoted to creative writing and historical research.", "photo": "assets/writers/71-earth-voice-v2.webp"}, {"id": "writer-37", "name": "Jayantika/ଜୟନ୍ତିକା", "bio": "A Professor of Political Science turned Poet, she has carved a niche in Odia poetry during last two decades. She has several poetry collections to her credit. Post superannuation she is dedicated to creative writing.", "photo": "assets/writers/37-earth-voice-v1.webp"}, {"id": "writer-225", "name": "Jaydeep Sarangi", "bio": "Jaydeep Sarangi (b.1973) is a widely anthologised poet with ten collections, latest being, letters in lower case (2022). Sarangi has been dubbed as ‘the bard of Dulung’ for his poems on the rivulet Dulung and people who reside on its banks. He edits Teesta, a journal devoted to poetry and poetry criticism. With Rob Harle of Lismore, Australia he has edited seven anthologies of poems from Australia and India which are a great literary link between the nations. His website is : https://jaydeepsarangi.in/", "photo": "assets/writers/225-earth-voice-v1.webp"}, {"id": "writer-53", "name": "Jernail Singh Anand", "bio": "Dr. Jernail Singh Anand is an Honorary Member of the Association of Serbian Writers. He is Prof Emeritus in Indian Literature at The European Institute of the Roma Studies and Research Belgrade. Dr Anand has authored more than 150 books in English poetry, fiction, non-fiction, spirituality and philosophy. He is credited with the theory of Biotext in critical theory. His work has been translated into more than twenty world languages. Author of 9 epics which are regarded as modern classics, Anand has organized 4 International Literary Conferences, latest of them, in Chandigarh.", "photo": "assets/writers/53-earth-voice-v1.webp"}, {"id": "writer-231", "name": "Jinatamam Darji", "bio": "Jinatamam Darji, a post graduate in Hindi literature and a promising poet (in Hindi and odia) from Bargarh district. Her poems are published in various news papers and magazines as well and a translator also.", "photo": "assets/writers/231-earth-voice-v1.webp"}, {"id": "writer-161", "name": "Jnani Debashis Mishra/ ଜ୍ଞାନୀ ଦେବାଶିଷ ମିଶ୍ର", "bio": "Jnanee Debasish Mishra(1985) is an acclaimed poet & critic in Odia. He is a recipient of Sahitya Akademi Yuva Puraskar(New Delhi) for poetry in 2016.The radio program of Jnanee received best program award for musical category from Prasar Bharati(New Delhi) and got first prize in 13th International Radio Workshop at Iran.He has four poetry collection, six criticism and four edited books to his credit. Now he is an Assistant Professor in Ravenshaw University.", "photo": "assets/writers/161-earth-voice-v1.webp"}, {"id": "writer-395", "name": "Johny Takkedasila", "bio": "Johny Takkedasila is an Indian Telugu Poet, Writer, Novelist, Critic, Translator and Editor born on 08.06.1991 in Pulivendula, Andhra Pradesh, India. His literary journey, which began as a Telugu poet, has seen the publication of 30 books. He has received numerous awards for his contributions. The Central Sahitya Akademi Yuva Puraskar for 2023 (National Award) was awarded to \"Vivechani,\" Criticism book in the Telugu language. His poetry has been featured in many international anthologies, and his stories and poetry have found a place in international magazines. In addition to writing in Telugu, Hindi, and English, he is also involved in translation. His literary style appears to aim at making readers contemplate and sensitize society through a compelling narrative. His other works Tiny Treasures, Puberty, Kattela Poyyi, Siva Reddy Kavitvam Oka Parisheelana, Akademi Aanimutyalu, Tella Rommu Nalla Rommu, Nadaka and Soochna were published by Ukiyoto Publishing House.", "photo": "assets/writers/395-earth-voice-v1.webp"}, {"id": "writer-363", "name": "Julie Miles", "bio": "", "photo": "assets/writers/363-earth-voice-v1.webp"}, {"id": "writer-462", "name": "Juya Tripathy / ଜୁୟା ତ୍ରିପାଠୀ", "bio": "Born in Bolangir , Odisha she’s staying in Bangalore now a days. She has interest in creative writing, particularly poetry.", "photo": "assets/writers/462-earth-voice-v1.webp"}, {"id": "writer-296", "name": "Jyosthnarani Bhoi/ଜ୍ୟୋତ୍ସ୍ନା ରାନୀ ଭୋଇ", "bio": "Jyotsnarani Bhoi is an Odia poet. She lives in Linepada, Patnagarh,Bolangir, A teacher by profession, she has been published in various literary magazines in Odisha.", "photo": "assets/writers/296-earth-voice-v1.webp"}, {"id": "writer-51", "name": "Jyoti Jha", "bio": "An author of three books, Jyoti Jha is a Former HR Professional, a Storyteller, a Columnist, and a Globetrotter. An esteemed winner of `TOI Write India Season 3`, she is a proud panellist and Guest Speaker in Events and Talk Shows at prestigious institutions like IIM Lucknow and IITs. She has been an honorable Judge at Kashiyatra, IIT BHU, Jury Member at the Literary Club, IIT BHU for Storytelling, and a guest speaker at distinguished literary events. Conferred Rastriya Samman and Global Progressive Women Award, she is the President of Savitribai Seva Foundation, Columnist at The Literary Mirror magazine, and contributes to both Hindi and English literature. She has delivered talk in a session `I Am Writer` at TEDx Shivaji College and she has been a speaker at the Twin Win Academy in `Rubaru Series` and IIT BHU in `Zindagi with Kitaab` series.", "photo": "assets/writers/51-earth-voice-v1.webp"}, {"id": "writer-295", "name": "Jyoti Nanda", "bio": "Jyoti Nanda is a poet, short story writer, translator, novelist and essayist. He is a rebel in himself having a number of publications to his credit. He lives in Bhubanwswar.", "photo": "assets/writers/295-earth-voice-v1.webp"}, {"id": "writer-223", "name": "Jyoti Shankar Panda “Hayat”", "bio": "", "photo": "assets/writers/223-earth-voice-v1.webp"}, {"id": "writer-443", "name": "Jyotirmaya Thakur", "bio": "Jyotirmaya Thakur born in India, is a retired Principal of Cambridge affiliated school ,bilingual author of around fifty books in five genres with many waiting to be published ,translated into over 43 languages and is a co-author in many International Anthologies. Her poems , stories , articles and research papers have been widely published and translated in many languages in highly acclaimed journals and reputed magazines. Jyotirmaya Thakur is an illustrious author and poet, Peace Ambassador and a veteran academic. A voice to adhere to in our tumultuous times. Her academic experience and intellect combine to make her books a very useful companion to anyone seeking a path in a maze of confusion.", "photo": "assets/writers/443-earth-voice-v1.webp"}, {"id": "writer-305", "name": "K. V. Dominic", "bio": "Prof. Dr. K. V. Dominic, English poet, critic, short story writer and editor has authored/edited 51 books including 14 collections of poems and 8 books of short stories. There are five critical books on his poetry and one on his short stories. He is the Secretary of GIEWEC and Editor of IJML and WEC.", "photo": "assets/writers/305-earth-voice-v1.webp"}, {"id": "writer-136", "name": "Kaberi Chattopadhyaya", "bio": "Kaberi Chattopadhyay was born and brought up in the bewitching state of Assam ,India . She completed her graduation (B.A.Hons )and B.ED from Calcutta University and NEHU(North Eastern Hill University) respectively. She worked as a teacher of English at Ramakrishna Vivekananda Mission and Army Public School,Barrackpore,West Bengal . In 2021 ,her Autobiography \"\" Peeping Through My Window\"\" was published by Virasat Art Publication in which she narrated her fierce and unrelenting battle with the life threatening BREAST CANCER . This year her debut collection of poems \"\" The Twilight Bells\"\" was published by Penprints publication.", "photo": "assets/writers/136-earth-voice-v1.webp"}, {"id": "writer-303", "name": "Kajal Chaudhury", "bio": "Kajal Chaudhury is a bi-lingual poet, writes both in Hindi and English.", "photo": "assets/writers/303-earth-voice-v1.webp"}, {"id": "writer-228", "name": "Kakoli Ghosh", "bio": "Kakoli Ghosh is an award winning bi- lingual poet and author from Kolkata, India. Many of her poems and short stories have been published worldline in various anthologies and story compilations. Her paintings adore the cover pages of several anthologies including her solo poetry book `The Bridge `.", "photo": "assets/writers/228-earth-voice-v1.webp"}, {"id": "writer-471", "name": "Kallol Choudhury", "bio": "Kallol Choudhury is a bilingual poet, short story writer, translator, researcher and social activist with fifteen published books to his credit. He has translated Sahitya Akademi Award Winning poetry book “Relationship” by Jayanta Mahapatra into Bengali and the Bengali version \" Samparka\" was published by Sahitya Akademi. Oxford University Press published his folktale , short story and translations of poems in its three volumes ( 2006,2011).He has received Invierno Revista Official Magazine 2023 Award from Argentina of Latin America.Penguin Random House included one of his short stories in LAPBAH - Stories from the North-East (2025).", "photo": "assets/writers/471-earth-voice-v1.webp"}, {"id": "writer-117", "name": "Kamadev Moharana/କାମଦେବ ମହାରଣା", "bio": "Kamadev Moharana (1979) is a poet and story teller.He has been writing poems and stories since his college days.He has three poetry collections(kabi,chhai Saha sabudina,coffee bagicha) and a novel ( Devi - published on an E - magazine `Odisha Sambada` ) to his credit.He has bagged many awards like Shreekshetra sahitya sansada yuba lekhaka sammana 2014, shreekshetra Shree sammana2018,Someswara sahitya sammana - 2021, pratisruti sahitya sammana 2021and so many for his literary activities.His poem describes Love, pain and suffering of common man with look of compassion.", "photo": "assets/writers/117-earth-voice-v1.webp"}, {"id": "writer-442", "name": "Kanak Manjari Sahoo", "bio": "Smt. Kanak Manjari Sahoo is a distinguished Odia writer and translator, renowned for translating major Bengali and Hindi literary works into Odia. An award-winning author of fiction, travelogues, and translations, her contributions are recognised by Sahitya Akademi publications and numerous national and international literary honours.", "photo": "assets/writers/442-earth-voice-v1.webp"}, {"id": "writer-387", "name": "Kavita Singh", "bio": "Kavita Singh Prava writes poetry in Hindi. She lives in Delhi.", "photo": "assets/writers/387-earth-voice-v1.webp"}, {"id": "writer-232", "name": "Kavita Singh", "bio": "Dr. Kavita Singh `Prabha` lives in Bangalore, Karnataka. Her qualifications include MSc, M.phill,PhD and B.Ed. She is an educationist, writer, editor and a critic She is the founder of `Kavita Prabhaa` Poetry Group. She writes poems, gazals, nazms, raps, articles and plays. Her work has been published in two solo Hindi poetry books `Kavita Prabha- Muskan Zindagi ki` and Suni Hai Aahat.` She has also contributed in more than 15 anthologies.", "photo": "assets/writers/232-earth-voice-v1.webp"}, {"id": "writer-155", "name": "Kedar Mishra/କେଦାର ମିଶ୍ର", "bio": "Kedar Mishra is a well known poet, editor, translator and art critic. Born in 1972, he has published 7 poetry collections and a couple of prose volumes in Odia. Dozens of his scholarly articles has been included in prestigious scholarly journals and newspapers. Widely recognised and awarded for his outstanding contributions to Odia poetry by various literary institutions.", "photo": "assets/writers/155-earth-voice-v1.webp"}, {"id": "writer-94", "name": "Ketaki Datta", "bio": "Ketaki Datta[Ph.D] is an Associate Professor in English of a Govt. College, Kolkata, India, to be precise. She is a novelist, translator, book reviewer[with Compulsive Reader, USA, and Muse India, Hyderabad, India], and a poet. She has two novels, “A Bird Alone” and “One Year for Mourning”, the last being published by Partridge Publishing Co. USA. Book of short stories is in press. Her stories have been widely anthologized. Her book of poems, “Across the Blue Horizon”was published by Feedaread Publishing, U.K. aided by Arts Council, England. Her book of poems with Prof. Wilfried Raussert has been published from Germany titled, “Urban Reflections: A Dialogue in Poetry and Photography”.Her latest book of poems “The Music of Eternity” has been published in India by Penprints Publications. Her translated novels are three in number, “The Last Salute” being published from Sahitya Akademi, New Delhi, India. She has academic books to her credit too. She went to Lisbon[CidadeUniversitaria], Univ. of Oxford and Univ. of California[Santa Barbara] to present her research papers on invitation.", "photo": "assets/writers/94-earth-voice-v1.webp"}, {"id": "writer-371", "name": "Ketaki Mazumdar", "bio": "Ketaki Mazumdar is a Mumbai based poet with roots in Kolkata. An educationist, author, Poet… she has won many accolades and writes prolifically on the Everyday, Nature, her Country, Love, Spirituality and Mysticism. Her poems are introspective, true to life, full of imagery and is gently healing.", "photo": "assets/writers/371-earth-voice-v1.webp"}, {"id": "writer-469", "name": "Krushna Kumar Mohanty", "bio": "Krushna Kumar Mohanty (born 28 April 1966) is an Indian author, poet, essayist, literary critic, reviewer, translator, and editor from Balasore, Odisha. Active in literature since the early 1990s, he has contributed extensively to both Odia and English literary publications. His published works include the short story collection Shyamali Das and the poetry collection Ruby Ray.", "photo": "assets/writers/469-earth-voice-v1.webp"}, {"id": "writer-441", "name": "Kumudini JEE/ କୁମୁଦିନୀ ଜୀ", "bio": "", "photo": "assets/writers/441-earth-voice-v1.webp"}, {"id": "writer-268", "name": "Kumudini Ved", "bio": "Kumudini Ved is an artist based in Mumbai. Maharashtra. India. She has done her Masters in English Literature. She pursues many interests like, painting, drawing & writing. She is,a published author.She is a trained singer. She speaks several languages & sings in as many. Everything that spells Nature... She loves it!", "photo": "assets/writers/268-earth-voice-v1.webp"}, {"id": "writer-213", "name": "Laszlo Aranyi", "bio": "Laszlo Aranyi (Frater Azmon) is a poet, anarchist, occultist from Hungary. As per his opinion he is marginalised in his own country. He is a painter also.", "photo": "assets/writers/213-user-selected-20261004.webp"}, {"id": "writer-402", "name": "LAVANYA NAYAK/ ଲାବଣ୍ୟ ନାୟକ", "bio": "Lavanya Nayak, a post graduate in Odia language writes in Odia. Her hubby is gardening, reading and writing poetry. She resides at Kuanshpur, Debidwar, Jajpur in Odisha. She has two collections of poetry to her credit.", "photo": "assets/writers/402-earth-voice-v1.webp"}, {"id": "writer-137", "name": "Leena Thampi", "bio": "Leena Thampi is a celebrated author and entrepreneur renowned for her captivating writing style that transcends the ordinary. With five published books and numerous internationally featured articles, her work has garnered widespread recognition and accolades. Recent accolades include Author Literary Awards from The Book Channel for her four books across different categories, the `Women Face of the Year 2024` award by Fox Story India, and the City Excellence Awards by Bharat Times. Her literary prowess has also been recognized with Rabindranath Tagore Memorial literary honors and Gujarat Sahitya Academy honors.", "photo": "assets/writers/137-earth-voice-v1.webp"}, {"id": "writer-84", "name": "Lipika Das/ ଲିପିକା ଦାସ", "bio": "", "photo": "assets/writers/84-earth-voice-v1.webp"}, {"id": "writer-81", "name": "Lipsa Patel / ଲିପସା ପଟେଲ", "bio": "", "photo": "assets/writers/81-earth-voice-v1.webp"}, {"id": "writer-300", "name": "Lisa Patnaik", "bio": "Lisha Patnaik is an IT professional ,working in the field for 12 years. Born and brought up in a beautiful hill township of Damanjodi, in far south of Odisha, she did her schooling in Delhi Public School. Right now , she stays at Bhubaneswar with her husband & 6 year old son. Juggling between work and family, she finds her own time to scribble. Being a English language enthusiast since childhood, she began writing poems at a tender age of 9 years. Since then Lisha has contributed to school & college magazines. As a child, her poems were published in reputed national newspapers. Poetry, to her, is a more of personal thing. She finds writing poems is a healing therapy. This is the reason why she lets her chaotic mind speak in her poems and find solace in them. Her muse is a concept of mutual respect, appreciation and kindness. She loves to read Shakespearean literature and Haruki Murakami.", "photo": "assets/writers/300-earth-voice-v1.webp"}, {"id": "writer-335", "name": "Lopamudra Banerjee", "bio": "Lopamudra Banerjee is an author, poet, translator, editor with eight solo books and six anthologies in fiction, nonfiction, poetry and translation. She lives in Texas, USA with her family, but she is originally from Kolkata, India. `Bakul Katha: Tale of the Emancipated Woman`, her English translation of Ashapurna Devi`s award-winning Bengali novel `Bakul Katha` has received Honorable Mention at London Book Festival in 2022. She also received the International Reuel Prize for Poetry (2017) and other honours for her writing. Her latest books are `We Are What We Are` in collaboration with Latina-American poet and storyteller Priscilla Rice and `The Bard and His Sister-in-Law` (English translation of `Kobir Bouthan by Mallika Sengupta), a historical novel on Jorasanko Thakurbari, Kolkata.", "photo": "assets/writers/335-earth-voice-v1.webp"}, {"id": "writer-108", "name": "Lopamudra Mishra", "bio": "", "photo": "assets/writers/108-earth-voice-v1.webp"}, {"id": "writer-436", "name": "Lopamudra Singh", "bio": "Lopamudra Singh is a literary enthusiast who actively engages with books through reading and reviewing. Professionally, she blends her analytical background as an Electrical Engineering graduate with her experience as an officer in the Commercial Tax and GST wing, Department of Finance, Government of Odisha.", "photo": "assets/writers/436-earth-voice-v1.webp"}, {"id": "writer-392", "name": "M.Rudra", "bio": "M. Rudraa, currently pursuing post-graduation in Economics at Ramadevi Women`s University, Bhubaneswar, Odisha, is a rising voice in contemporary poetry. An accomplished student-poet, she has been honoured with the prestigious Ekphrasis Excellence Awards and has received recognition from the ILA council for her thought-provoking poems like \"Silence: The Divine Missile\" and \"Why Not Peace?\" Her literary contributions include being a featured poet in the widely celebrated anthology Daughter: An Adorable Princess (\"She Is a Treasure\") and a co-author of the profound anthology Ink and Emotion (\"The Bleeding Soul\"). Additionally, her work has been published in Souvenirs of Indian Poetry in English 2024 (a poetry anthology)“Under My Sky”.", "photo": "assets/writers/392-earth-voice-v1.webp"}, {"id": "writer-423", "name": "Ma Yongbo", "bio": "Youngbo Ma is from mainland China and currently lives in Nanjing and Harbin. He writes poetry in both Chinese and English and translates poetry between Chinese and English.", "photo": "assets/writers/423-earth-voice-v1.webp"}, {"id": "writer-374", "name": "Madhu Jaiswal", "bio": "Madhu Jaiswal is an editor, translator and bilingual poet from the City of Joy Kolkata. She believes that penning your thoughts is therapeutic to the soul. Her musings are often featured in various e-zines and have been published in multiple national and international anthologies. An empathic person by core, she tries to impart affinity and kindness to all.", "photo": "assets/writers/374-earth-voice-v2.webp"}, {"id": "writer-185", "name": "Madhu Sriwastav", "bio": "Madhu Sriwastav is an academic, poet,short story writer, reviewer and translator based in Kolkata. She has also dabbled in theatre and wrote short plays and directed them. Her poems have been published and anthologised in National and International journals and magazines both online and print such as Setu, Saranga, Teesta Review etc. Her debut book of poems Trips Climbs Circleshas received rave reviews. She received the Jury award 2022 in Panorama International Literature Festival. She is a member of the Executive Committee of Intercultural Poetry and Performance Library, Kolkata. Her latest book is a translation of Chitra Mudgal`s award winning novel- Post Box No.203, Nala Sopara by Sahitya Akademi.", "photo": "assets/writers/185-earth-voice-v1.webp"}, {"id": "writer-138", "name": "Madhumita", "bio": "Born and brought up at Puri in an academic family I completed my Masters in English and subsequently did my MPhil English from bhanjavihar university Meanwhile while pursuing other studies , I did my masters in Journalism from Ignou. My interests include literature and photography which I fulfill passionately, whenever time permits. I am blessed with a beautiful and intelligent daughter, who is pursuing herBA LL.B at Symbiosis, Pune . I love to do social service and try to help others when ever I can.", "photo": "assets/writers/138-earth-voice-v1.webp"}, {"id": "writer-34", "name": "Madhuri Panda/ମାଧୁରୀ ପଣ୍ଡା", "bio": "", "photo": "assets/writers/34-earth-voice-v1.webp"}, {"id": "writer-457", "name": "Madhusudan Mishra", "bio": "Madhusudan Mishra, IAS (Retd.) is currently serving as the Registrar of Jagadguru Kripalu University, Banara, Cuttack, Odisha. A seasoned administrator, he has earlier served as District Collector and Magistrate of Nayagarh, Boudh, and Sonepur Odisha, besides holding key assignments across various government departments. At Jagadguru Kripalu University, he has played a pivotal role in drafting the Rules, Statutes, and core institutional policies, strengthening the university’s governance framework.", "photo": "assets/writers/457-earth-voice-v1.webp"}, {"id": "writer-334", "name": "Mahi Rao/ माही राव", "bio": "Mahi Rao is a native of Gurugaon, Haryana. She has been writing from her childhood. She is a Law graduate and writes in Hindi.", "photo": "assets/writers/334-earth-voice-v1.webp"}, {"id": "writer-411", "name": "Mahima Gantayat", "bio": "Mahima Gantayat a young writer and poetess from Rayagada, Odisha. Currently pursuing her higher studies in the Humanities stream at Women `s Higher Secondary School, Rayagada. Deeply passionate about literature from a young age ..she expresses herself through short stories, Hindi poetry and heartfelt shayari. Her words reflect emotions, reality and the essence of life capturing the attention of many. Mahima `s literary work has gained recognition across various digital platforms and continues to receive overwhelming appreciation on social media. Recently She has been honoured with Proficient Writer Awards for being the best poetess.", "photo": "assets/writers/411-earth-voice-v1.webp"}, {"id": "writer-110", "name": "Mahua Sen", "bio": "Bio- Mahua Sen is a multiple award winning poet/author/editor residing in Hyderabad. Her literary works are widely published both nationally and internationally. She has co-authored more than 70 anthologies and has edited three books. She works with Bull’s Eye Outsourcing as the Regional Director, South.", "photo": "assets/writers/110-review-retry-v1.webp"}, {"id": "writer-358", "name": "Maid Corbic", "bio": "Maid Corbic from Tuzla, 24 years old. In his spare time he writes poetry that repeatedly praised as well as rewarded. He also selflessly helps others around him, and he is moderator of the World Literature Forum WLFPH (World Literature Forum Peace and Humanity) for humanity and peace in the world. He is world 44. poet in the world and five in the Balkan. He has over the 10.000 successes on Facebook.", "photo": "assets/writers/358-earth-voice-v1.webp"}, {"id": "writer-356", "name": "Maitreyee B Chowdhury", "bio": "Maitreyee B Chowdhury is a poet and writer. She has four books to her credit, The Hungryalists , One Dozen-Hasan Azizul Huq( Trans) , Uttam Kumar and Suchitra Sen- Bengali Cinema`s First Couple and Where Even The Present Is Ancient: Benaras. Maitreyee is the editor of The Bangalore Review, and one of the founders of The Bengaluru Poetry Festival. Her forthcoming work is centred around the eccentric poet genius Binoy Majumdar. She can be found at https://www.maitreyeechowdhury.com/", "photo": "assets/writers/356-earth-voice-v1.webp"}, {"id": "writer-257", "name": "Majrooh Rashid", "bio": "Majrooh Rashid is a, poet, critic and short story writer. He writes in English, Urdu and his mother tongue Kashmiri. He has a number of publication to his credit and has been published in the country as well out side country. He worked in the university of kashmir and retired as professor. He headed the department of kashmiri twice and later joined the university of science and technology where he worked as a Director for one and a half years.", "photo": "assets/writers/257-earth-voice-v1.png"}, {"id": "writer-86", "name": "Makhan Kalita", "bio": "", "photo": "assets/writers/86-earth-voice-v2.webp"}, {"id": "writer-139", "name": "MALAKSHMI BORTHAKUR", "bio": "Malakshmi Borthakur is a contemporary Indian multilingual poet, short story writer and translator. An Assamese by birth and a resident of Lucknow city in the state of Uttar Pradesh, India, Malakshmi writes in English, Hindi and her native language, Assamese. She is a Post Graduate in English and Indian Classical (Vocal) Music. She has published many of her poems in reputed journals, E-zines and best-selling anthologies and has garnered huge appreciation worldwide. Her writing brought for her many international and national awards and accolades. . Her poetry book in English, SPLENDID SIGNATURE-RHYTHMIC STROKES OF A QUILL has been published by Black Eagle Book, USA.", "photo": "assets/writers/139-earth-voice-v1.webp"}, {"id": "writer-241", "name": "Malay Mishra", "bio": "", "photo": "assets/writers/241-earth-voice-v1.webp"}, {"id": "writer-311", "name": "Malaya Kumar Jati", "bio": "Malaya Kumar Jati is a lecturer in English, poet, critic and reviewer placed in Bhubaneswar.", "photo": "assets/writers/311-earth-voice-v1.webp"}, {"id": "writer-226", "name": "Malini Mohanty", "bio": "Malini Mohanty is from Bhubaneswar, Odisha. Presently she’s working as a teacher in a reputed school of Bhubaneswar . Writing is her hobby . She loves reading novels and writing poems.", "photo": "assets/writers/226-earth-voice-v1.webp"}, {"id": "writer-345", "name": "Mallika Tripathi", "bio": "Dr. Mallika Tripathi is an exceptional educator, an honorary legal consultant and a social worker with a distinguished career spanning over 23 years. Currently serving as Professor & Head, Deptt. of Applied Science & Humanities at Feroze Gandhi Institute of Engineering & Technology, Raebareli, she continues to make significant contribution in her field. Dr. Tripathi`s expertise extends beyond academia as she has authored numerous National and International papers, solidifying her reputation as a scholarly researcher. Her poems have been published in prestigious international peer reviewed and refereed journals, securing her a notable place in the world of poetry. She has been honoured by the Department of Posts and Telecommunication for her special contribution in the field of Academics.", "photo": "assets/writers/345-earth-voice-v1.webp"}, {"id": "writer-249", "name": "Mamata Kiran / ममता किरण", "bio": "Mamata Kiran is from Dwaraka. She is a poet, journalist, translator, news reader and anchor. She writes poetry as well as Ghazals.", "photo": "assets/writers/249-earth-voice-v1.webp"}, {"id": "writer-78", "name": "Mamata Pattnaik/ ମମତା ପଟ୍ଟନାୟକ", "bio": "Mamata Pattnaik is a well known name in Odia Literary world. She has been recognised for her creative contribution to the odia field of literature. With over 1000 poems published in different newspapers and magazines, she continues with her enthusiasm for writing more. Mamata has also recieved recognitory awards from many established organizations. She has already published 5 anthologies which continue to recieve appreciation from readers all over. Not just books but she has also dictated herself to the electronic media. She", "photo": "assets/writers/78-earth-voice-v1.webp"}, {"id": "writer-440", "name": "Manas Bakshi", "bio": "Manas Bakshi is a ` major voice ` in the world of Indian English poetry with fifteen books of repute from publishers like Rupa & Co, Firma KLM Pvt. Ltd, Cambridge India, Authors Press, Poetry Society Of India and others. A doctorate in Rural Economics, his poems have appeared in various noted publications in India, U.S.A, Canada, Japan, New Zealand etc.", "photo": "assets/writers/440-earth-voice-v1.webp"}, {"id": "writer-451", "name": "Manas Ranjan Mahapatra / ମାନସ ରଂଜନ ମହାପାତ୍ର", "bio": "Born at Puri in 1960,Manas Ranjan Mahapatra is a globally acclaimed poet, fiction writer, essayist, editor, cultural activist and folklorist. He has 7 anthologies of poetry, two in Hindi translation,three collections of stories, one novelette, one collection of essays two memoirs in English, Autobiography in two parts besides over 50 translations.", "photo": "assets/writers/451-earth-voice-v1.webp"}, {"id": "writer-106", "name": "Mandakini Bhattacherya", "bio": "Mandakini Bhattacherya, from Kolkata, is Associate Professor of English and a multi-lingual poet, literary critic and translator. She has her own Poetry Page on the Dallas-based Mad Swirl Magazine, and her poems feature in international and national anthologies and journals like Hibiscus, The Kali Project, Better Than Starbucks, The HyperTexts,Poetry Nation, The Bombay Review, Setu Magazine, The Dotism Journal,Hayati, Sahityanama, Different Truths and LangLit. She participated in the All India Young Writers’ Meet organised by SahityaAkademi, New Delhi in February, 2020, and delivered a talk there on Short Fiction in 2021. She edited the international short story anthology ‘The Mixed Fare’ in 2021, and is Associate Editor of the ‘Muse of Now Paradigm’ anthology (AuthorsPress, 2020).", "photo": "assets/writers/106-earth-voice-v1.webp"}, {"id": "writer-332", "name": "Manini Jena / ମାନିନୀ ଜେନା", "bio": "Ms. Manini jena is presently working as a lecturer in ODIA in Prananath College(A). She has been contributing to writing poetry since last couple of years. She also has a comfortable hand over writing criticisms on odia stories and fictions.", "photo": "assets/writers/332-earth-voice-v1.webp"}, {"id": "writer-116", "name": "Manini Mishra/ମାନିନୀ ମିଶ୍ର", "bio": "", "photo": "assets/writers/116-earth-voice-v1.webp"}, {"id": "writer-233", "name": "Manju Chouhan", "bio": "Dr Manju Chouhan is a professor of English literature at Chandigarh University. She is a bilingual poet and an author of two poetry collections.", "photo": "assets/writers/generic-feminine-earth-voice-v1.webp"}, {"id": "writer-45", "name": "Manjula Asthana Mahanti", "bio": "Manjula Asthana Mahanti is a trilingual poet, author, translator and editor.She has worked in prestigious college as head of the department, last worked as public high school principal. She has published eight books ,both the languages included. (Next in press) Solo editor of anthology `Lessez Aller` , thoughtful articles about women empowerment. Published short stories, poems, articles in many national and international anthologies, e-magazines, OPA, Glomag, Setu, Indie Blue publications etc . She has done translation of much talked novel in Hindi, named Abhishap Damini ka. She has translated many poems from English, Odia, and a short play from Odia to Hindi.", "photo": "assets/writers/45-earth-voice-v1.webp"}, {"id": "writer-376", "name": "Manoj Chola", "bio": "Monoj Chola writes poetry in English. He is from Kerala.", "photo": "assets/writers/376-earth-voice-v1.webp"}, {"id": "writer-21", "name": "Manorama Choudhury / ମନୋରମା ଚୌଧୁରୀ", "bio": "A Boston based Indian poet Manorama writes in English, Hindi and Odia. She is also an avid artist by passion. Besides, she has interest in Paining, Fashion Designing and other visual arts.", "photo": "assets/writers/21-earth-voice-v1.webp"}, {"id": "writer-472", "name": "Manoranjan Sahoo / ମନୋରଞ୍ଜନ ସାହୁ", "bio": "Manoranjan Sahoo is a published poet based at Kendrapara, Odisha.", "photo": "assets/writers/472-earth-voice-v1.webp"}, {"id": "writer-265", "name": "Manua Das / ମନୁଆ ଦାସ", "bio": "Manua Das is an original voice in contemporary Odia poetry. His diction and distinct style is remarkable. A clear visionary of the socio-cultural turbulence of our time, he creates beauty in his language expression. The sonorous rhythm of his poems makes it earthy and musical. He has made three books of poems: Mahufena (Beehive ), Kahari Akhire Nida Nahin (Sleepless Eyes), and Antabujula (Visceral).", "photo": "assets/writers/265-earth-voice-v2.webp"}, {"id": "writer-401", "name": "Marmasparshee Priyadarshini", "bio": "Marmasparshee Priyadarshini is an English Literature graduate and an emerging poet based in India. She writes in multiple languages, weaving personal reflection with aesthetic imagery. Her work often explores themes of nature, emotion, and transformation.", "photo": "assets/writers/401-earth-voice-v1.webp"}, {"id": "writer-339", "name": "Matralina Pati", "bio": "Matralina Pati is a Ph.D. research scholar working on marginal Bhasha literature in English translations. She lives in the town of Bankura in West Bengal. She is currently working in the Department of English, Bankura University in West Bengal as a Junior Research Fellow (UGC). She has completed her Masters in English Literature from Bankura University. She has secured the position of First Class First in her batch (2020). She has achieved 3rd position in a State level essay competition, organised by the Government of West Bengal. Besides penning poems and essays, she works as a translator. She has had her research papers published in a number of esteemed peer-reviewed journals. Her meditative works range from the literature of the marginalised to the literature of the absurd. She has presented papers in International, National and State level seminars. She has attended National and State level academic workshops as a resource person.", "photo": "assets/writers/339-earth-voice-v1.webp"}, {"id": "writer-357", "name": "May Manoj", "bio": "", "photo": "assets/writers/357-earth-voice-v1.webp"}, {"id": "writer-470", "name": "Meenakshi Goswami", "bio": "Meenakshi Goswami, a distinguished retired principal from Sonitpur, Assam, is an acclaimed educationist and the sole recipient of the 2022 National Awards to Teachers from Assam, honored by the President of India. She was also a recipient of the Prestigious OIL SHIKSHA RATNA PURASKAR given by OIL INDIA LIMITED in 2016 and State Awardee Teacher in 2018 . A prolific poet, she authored THE SENSUOUS ZEPHYR, WALTZING WORDS, and LUSH ECHOES, with works featured in prestigious national and international anthologies, including Sahitya Akademi’s. Celebrated for her captivating recitations at Global Poetry Festivals, and she is an active member of Lions International Club of Tezpur Greater, Assam.", "photo": "assets/writers/470-earth-voice-v1.webp"}, {"id": "writer-444", "name": "Meenakshi Mohan", "bio": "Dr. Meenakshi Mohan (USA) is an internationally published writer, scholar, art critic, children's writer, painter, and poet. She is on the editorial Committee for Inquiry in Education, a peer-reviewed journal published by National Louis University, Chicago, Illinois. She is an Advisory Editor for Confluence, UK. Meenakshi received the Setu and Panorama International Awards for Excellence in Literature. Her book, Symphonies of Life, won the Sudesh Kamra Memorial Award for the best debut poetry book at the Bhasha and Beyond Literary Festival, Pune. Meenakshi lives in the USA.", "photo": "assets/writers/444-earth-voice-v1.webp"}, {"id": "writer-465", "name": "Minati Pradhan", "bio": "Minati Pradhan is a bilingual writer, poet, author, editor and certified counsellor. Her poems, stories, and essays have appeared in numerous magazines, journals, and anthologies. Her published works include collections of poetry and short fiction- four as author and 29 as co-author.A sustainability enthusiast and co-nurturer of Vishwaneedam Center for Asian Blossoming.", "photo": "assets/writers/465-earth-voice-v1.webp"}, {"id": "writer-272", "name": "Minu Verma / मीनू वर्मा", "bio": "", "photo": "assets/writers/272-earth-voice-v1.webp"}, {"id": "writer-289", "name": "Misna Chanu", "bio": "Misna Chanu is a bilingual poetess, writer, author, humanitarian, translator and an editor from Assam, currently living in Gurgaon. She writes in her mother tongue Manipuri and in English. As an author, she has published three poetry books; “A Little Piece Of Melancholic Sky”, “Many Shades Of Love, “The Silent Whispers” and one short story book of children named “Once Upon A Time”. As an editor, she has published five anthologies of poetry and one anthology of short stories for children. She is publishing a series of anthology book under the name “May Love Heal the World” and donates her entire royalty from that series of book to different humanitarian organizations like WHO, UNICEF etc. Her email id – ", "photo": "assets/writers/289-review-retry-v1.webp"}, {"id": "writer-326", "name": "Mitra Samal", "bio": "Mitra Samal is a poet, writer, and software consultant, with a passion for both Technology and Literature. Her works have been published in Poetry Society India (Anthology), Muse India, Madras Courier, Borderless Journal, and Kitaab among others. She is also an avid reader and Toastmaster who loves to speak.", "photo": "assets/writers/326-user-selected-20261004.webp"}, {"id": "writer-302", "name": "Monalisa Dash Dwibedy", "bio": "Monalisa Dash Dwibedy is an IT Consultant by day and a poet by night. Her literary works are featured in many international journals and anthologies . She is the author of two poetry collections , Pearls of A Strawberry Moon( English) and Anjulae Smruti ( Odia) . She is a Columnist for OdishaPlus , her column “The Playful Traveller” takes the readers on a trip to the places she travels. As ardent lover of nature and mountains, she feels mountains always call her. Her goal is to befriend the Himalayan mountain ranges and talk to the moon some day.", "photo": "assets/writers/302-earth-voice-v1.webp"}, {"id": "writer-140", "name": "Monalisa Parida", "bio": "Monalisa Parida is a post graduate in English literature and a prolific poetess. Her poems have been translated into different languages and published in various e-journals and anthologies.", "photo": "assets/writers/140-earth-voice-v1.webp"}, {"id": "writer-115", "name": "Mousumi Das/ମୌସୁମୀ ଦାସ", "bio": "", "photo": "assets/writers/115-earth-voice-v1.webp"}, {"id": "writer-157", "name": "Mousumi Parida/ ମୌସୁମୀ ପରିଡା", "bio": "Dr. Mousumi Parida, is a trilingual fiction writer and poet as well as a novelist, columnist, translator and editor of an Odia e-magazine, India. Her poems, short stories, novels have been widely published in various leading national and international journals, news papers, magazines and e-magazines and well acclaimed by the readers and analisers.", "photo": "assets/writers/157-earth-voice-v1.webp"}, {"id": "writer-362", "name": "Mridula Menon", "bio": "Mridula Menon is a post graduate in English literature. Presently she is a Director in Bharati Electrical appliances. She is very passionate about writing from a very young age, especially she loves reading and writing poems. She loves listening to music, cooking, interior designing and also painting. She is a home maker, living with her husband and children and grandchildren.", "photo": "assets/writers/362-earth-voice-v1.webp"}, {"id": "writer-313", "name": "Mrinmoy Kumar Nath", "bio": "Poet- Dr Mrinmoy Kumar Nath is a Senior Dental Surgeon of Govt of Assam. He is a Poet, Lyricist, Literary Composer and Quiz Master. He has three books to his credit namely Mondarshani ( Song ), Dristi Nandini ( Song ) and Chakhyani Mon ( Poem). He lives in Mangaldoi, Dist Darrang ( Assam ).", "photo": "assets/writers/313-earth-voice-v1.webp"}, {"id": "writer-391", "name": "Mrutyunjay Sarangi", "bio": "Mrutyunjay Sarangi writes poems , short stories both in English and Odia. Currently he publishes an English literature webzine Literary Vibes.", "photo": "assets/writers/391-earth-voice-v1.webp"}, {"id": "writer-280", "name": "Mukul Kumar", "bio": "Mukul Kumar is a bureaucrat, novelist and poet. He is a civil servant, belonging to the 1997 batch of Indian Railway Traffic Service. Presentlyhe is working in the Ministry of Railways, Railway Board. His published works include three novels, `As Boys Become Men` (RUPA Publications), Seduction by Truth` (Bloomsbury, India) and Aarzoo-Arshan (e-book), and three poetry anthologies, `The Irrepressible Echoes`, `Catharsis` and “Rhythm of the Ruins”. His 4th fiction is slated to come out this year in October.", "photo": "assets/writers/280-earth-voice-v1.webp"}, {"id": "writer-72", "name": "Mukul Mishra/ମୁକୁଲ୍ ମିଶ୍ର", "bio": "Mukul is a prominent young Odia Poet, who has five poetry collections to her credit. She resides at Bolangir in western Odisha and devoted to poetry.", "photo": "assets/writers/72-earth-voice-v1.webp"}, {"id": "writer-89", "name": "Naheed Akhtar", "bio": "Naheed Akhtar is a lecturer, writer and poet based in the city of Hyderabad, the Southern part of the country. She is a bibliophile and loves reading Philosophy, History, Psychology, Literature and the Glossary of Literature. She is known for her love for nature with her fine imagination of being a wanderer, a lost who longs and lingers for the unseen and remote for her own reasons. She has three poetry collections to her credit, entitled `Phantasms of My Heart` `The Earth`s Love` and `The Morphine`. She can be reached at .", "photo": "assets/writers/89-earth-voice-v1.webp"}, {"id": "writer-141", "name": "Namitarani Panda", "bio": "Namita Rani Panda is a multilingual poet, story writer, editor and translator from Sambalpur, Odisha. She has five anthologies of poems to her credit: Blue Butterflies, Rippling Feelings, A Slice of Sky and A Song for Myself andColours of Love. She is co-translator of Rivulets of Reflections, a book of translated stories from Odia to English. She has co-authored Radical Rhythm Volume I to IV with the credit of editorship of Radical Rhythm II. She is co-editor of two anthologies of poems Resplendent Rainbowand Durga the Invincible. Her signature words are love, optimism and self-confidence. Presently she is working as Vice Principal of Jawahar Navodaya Vidyalaya Cuttack, Odisha.", "photo": "assets/writers/141-earth-voice-v1.webp"}, {"id": "writer-208", "name": "Nandini Mitra", "bio": "Nandini Mitra is a poet based in Kolkata. A post- graduate in English Literature from Jadavpur University. She is in the profession of teaching for last twenty -five years. She has published her first book of poetry, The Road To Tranquility, recently. Has worked as a freelance journalist for a prestigious Bengali magazine published from Kolkata. She is passionate about Music and is a trained classical singer. She believes in the religion of humanity, compassion and love. Her poems have featured in various national and international anthologies.", "photo": "assets/writers/208-earth-voice-v1.webp"}, {"id": "writer-57", "name": "Nandini Sahu", "bio": "Prof.Nandini Sahu, Amazon`s best-selling author 2022, Professor of English and Former Director, School of Foreign Languages, IGNOU, New Delhi, India, is an established Indian English poet, creative writer and folklorist. She is the author/editor of seventeen books. She is the recipient of the Literary Award/Gold Medal from the hon`ble Vice President of India for her contribution to English Studies. Her areas of research interest cover New Literatures, Critical Theory, Folklore and Culture Studies, Children`s Literature and American Literature.", "photo": "assets/writers/57-earth-voice-v1.webp"}, {"id": "writer-42", "name": "Nandita Samanta", "bio": "Nandita Samanta is a poet, short story writer, reviewer, artist, freelance parenting, and relationship advisor. Her writings published in her two personal compilations and many anthologies, webzines, and journals, are highly appreciated and translated into many languages.", "photo": "assets/writers/42-earth-voice-v1.webp"}, {"id": "writer-468", "name": "Narayan Sahoo", "bio": "Narayan Sahoo writes poetry in Odia.", "photo": "assets/writers/468-earth-voice-v1.webp"}, {"id": "writer-82", "name": "Narmada Nilotpala / ନର୍ମଦା ନୀଳୋତ୍ପଳା", "bio": "", "photo": "assets/writers/82-earth-voice-v1.png"}, {"id": "writer-192", "name": "Neelam Saxena Chandra", "bio": "Neelam Saxena Chandra has authored 5 novels 1 novella and 7 short story collections 38 poetry collections and 14 childrensbooksto her credit She is a bilingual writerwriting in English and Hindi. She holds a record with the Limca Book of Records 2015 for being the Author having the highest number of publications in a year in English and Hindi. She was listed in Forbes as one among 78 most popular authors in the country in 2014", "photo": "assets/writers/192-earth-voice-v1.webp"}, {"id": "writer-322", "name": "Neeta Sagar", "bio": "Neeta Sagar writes in English and Hindi.", "photo": "assets/writers/322-earth-voice-v1.webp"}, {"id": "writer-256", "name": "Neha Bhandarkar", "bio": "Neha Bhandarkar is widely published Iconic Marathi Poet, embellished with numerous national and international awards for her consummate literary skill mused about in her writings. She is published author of 15 books in various languages. She is trilingual authour writing in Marathi, Hindi and English and also a genuine translator. Many of her poems and stories are being published in many international anthologies, magazines and E Zines. Some of her poems, stories have been translated in French, Albanian, Phillipines, Nepali, Greece, Odia, Brail etc. She is winner of Hindi state Sahithya Academy Award twice. Her poems has been broadcast on QUICHOTTE RADIO FRANCE and Hindi RADIO CHICAGO (USA).", "photo": "assets/writers/256-earth-voice-v1.webp"}, {"id": "writer-248", "name": "Neha Vertika", "bio": "Neha Vertika is a management graduate who has previously worked with different reputed educational institutes as an academician and soft skill trainer . She hails from Lucknow UP but at present in based in Switzerland with family.At present she is pursuing her childhood passion of poetry and story writing and writes for various magazine and newspapers and also Pratilipi ( biggest Hindi digital platform for writers).She is also a Tarot Card Reader and Certified Crystal Healer. She has performed for Sahitya Aaj Tak,Saadhna Channel and also quite active in various Facebook online poetry meets .In recent past she has received many honours and recognition for her creative writing skill.", "photo": "assets/writers/248-earth-voice-v1.webp"}, {"id": "writer-263", "name": "Nibha Utpreksha", "bio": "Nibha Utpreksha is a poet based in Begusarai, Bihar. Her poems appear in many leading newspapers and journals.", "photo": "assets/writers/263-earth-voice-v1.webp"}, {"id": "writer-123", "name": "Nidhi Garga", "bio": "Dr. Nidhi Garg is a trained counselling psychologist with a master`s degree in counselling psychology and has Ph.D. in Mental Well-being of corporate employees. She runs her clinic in Bhubaneswar. Dr. Garg has more than a decade long experience in academia industry, social and personality development. She continues to contribute through media & literary interactions to empower adolescent and young women and men. She is also a guest faculty with number of institutes like NIFT and KIIT university. Apart from her interest in academics she is a published poet. She is the Ehsaas women of Bhubaneswar of Prabha Khaitan Foundation which runs literary programs in India and abroad.", "photo": "assets/writers/123-earth-voice-v1.webp"}, {"id": "writer-453", "name": "Niharika Ray Baral / ନିହାରିକା ରାୟ ବରାଳ", "bio": "NIharika Ray Baral is an eminent poet, translator, writing in Odia", "photo": "assets/writers/453-earth-voice-v1.webp"}, {"id": "writer-167", "name": "Nikhilesh Mishra/ ନିଖିଳେଶ ମିଶ୍ର", "bio": "Nikhilesh Mishra has written three poetry collections so far: `Kehi Jane Kejani Kouthi` (2018) and `Kabitie Marigala Pare` (2021) in Odia and `Someone Somewhere` (2020) in English. His books have been shortlisted for the Sahitya Akademi Yuva Puraskar four times in the past three years. He is the recipient of the KATHA Nabapratibha prize (2016) and the Tapasya Sambhabana prize (2018) among others. Apart from poetry, he writes short stories, columns and scripts and regularly translates as well. He has recently co-written a short film in the upcoming Odia anthology film, `Indradhanu`. His upcoming books include an Odia translation of Abbas Kiarostami`s poetry and a biography of the Odia filmmaker Nirad Mohapatra.", "photo": "assets/writers/167-earth-voice-v1.webp"}, {"id": "writer-75", "name": "Nilim Kumar", "bio": "NILIM KUMAR (b 1961) is an Indian poet writing in Assamese. He has published 21 volumes of poctry, three collections of short novels, and other prose writings. He has won several prominent awards, including the Uday Bharati Nation Award, Sabda Award, Raza Foundation Award, Ramanath Bhattacharya Foundation Award, Distinguished Leadership Award (USA), etc. His poems have been translated into French, Spanish, German, Portuguese, English, Nepali, Hindi, Gujarati, Kannada, Marathi, Urdu, Bengali, Hindi, Tamil, Telugu, etc. He also has two collections of poems in English translation, and two in Hindi. His poems are taught in Bengaluru University, Gauhati University, Dibrugarh University, and Cotton University. Nilim Kumar has presented his poetry in many national and international poetry festivals. He has also visited France as part of the Indo-French cultural exchange. He lives in Guwahati.", "photo": "assets/writers/75-earth-voice-v1.webp"}, {"id": "writer-244", "name": "Nilima Bora", "bio": "Nilima Bora is a prolific poet from Dibrugarh, Assam .", "photo": "assets/writers/244-earth-voice-v1.webp"}, {"id": "writer-317", "name": "Niranjan Barik", "bio": "Professor Niranjan Barik ,formerly Professor and Head, Department of Political Science at Ravenshaw University also served as a Professor of Pol.Sc and Principal , Khallikote Autonomous College, Berhampur, Odisha. A Fulbright Scholar-in-Residence at Miles College, Birmingham, AL, USA in 2007-08 , Prof Barik evinces interest in reading and writing short stories and poems in Odia and English. His poetry book , “Freedom from Bondage: An Ode to Nature” was recently launched at Bhubaneswar.Toshali Literary Festival )", "photo": "assets/writers/317-earth-voice-v1.webp"}, {"id": "writer-103", "name": "Nisha luthra", "bio": "Nisha luthra ,born and brought up in Chandigarh , is an Art Director,Poet and Playwright, Founder Director of The Narrators Performing Arts Society India. Works with theatre productions ,Book Launches by way of stage productions ,Heal workshops for youth ,works on the mental health issues,Director of Poetry films & short films .", "photo": "assets/writers/103-earth-voice-v1.webp"}, {"id": "writer-426", "name": "Nisha Raviprasad", "bio": "Nisha Raviprasad lives in Kochi, Kerala and is an ardent lover of poetry. She has written many poems and many have been published in various journals. Besides poetry , she enjoys reading and cooking.", "photo": "assets/writers/426-earth-voice-v1.webp"}, {"id": "writer-142", "name": "Nitish Raj", "bio": "A Literary Critic turned Author, Nitish Raj is the Co-Founder of Literia Insight and Editor-in-Chief at The Literary Mirror. Having been published and featured at multiple prominent media houses of both national and international repute, he has been an eminent speaker at prestigious institutions like IITs, IIM Lucknow, and NIT Silchar. A TEDx Speaker at `I Am Writer` series, Shivaji College, Host of a unique Talk Show `The Lit Talks`,he has been invited as Host to International Conference on Multi-Disciplinary Research, Mumbai, and as Guest Poet at International Poetry Conference, Tunisia (Africa). He has been featured in the prestigious The CEO Magazine as an Entrepreneur for `The Lit Tour`, an initiative to celebrate and bring Books, Drama & Screen together and he has been a proud panellist at the highly prestigious Ahmedabad International Literature Festival.", "photo": "assets/writers/142-earth-voice-v1.webp"}, {"id": "writer-252", "name": "Nivedita Roy", "bio": "Award winning author Nivedita Roy is a teacher by profession, bilingual poetess and writer. She resides in the Kingdom of Bahrain and belongs to Lucknow. She is the author of 3 solo books in English and Hindi. She has co-authored around 25 international anthologies till date. Her poems/articles are published in many newspapers ezine and websites all over the world. She organizes poetry and book talk shows on various online platforms. She worked as a radio jockey for 4 years for the Hindi radio in Bahrain. https://niveditaroy.info", "photo": "assets/writers/252-earth-voice-v1.webp"}, {"id": "writer-59", "name": "Nurul Hoque", "bio": "Nurul Hoque is predominantly a poet and time-conscious rhymer, novelist and editor. His acquaintance with literature is quite wide. He is skilled at composing poems, rhymes, stories and songs. He has been working as a writer for almost three decades. He is being praised globally for his tireless work . He was elected World Laureate in Literature in 2018 by the International Organisation World Nation Writers Union, Kazakhstan www.wnwu.org . Now he is an Executive Director of Munir Mezyed Foundation for Arts and Culture, Romania. He was the Editor of Odyssey International Anthology Of World Poets 2020 and Chief Coordinator of Odyssey International (Head quarter in Romania). He is the Editor of monthly periodicals, Amader Buriganga, which is published from Dhaka almost regularly and he is the Founder Chairman of Buriganga Foundation Bangladesh. Nurul wrote many books both in Bengali and English. Some of them are remarkable.", "photo": "assets/writers/59-earth-voice-v1.webp"}, {"id": "writer-291", "name": "Padmaja Saran", "bio": "Padmaja Saran is an acclaimed Odia poet. She has a good number of poetry collections in Odia to her credit.", "photo": "assets/writers/291-earth-voice-v1.webp"}, {"id": "writer-408", "name": "Padmashree R.P.", "bio": "Padmashree Niranjan is a Bangaluru based poet, teacher and teacher trainer.", "photo": "assets/writers/408-user-selected-20261004.webp"}, {"id": "writer-279", "name": "Palavali Vijayalakshmi Pandit", "bio": "Dr. Palavali Vijayalakshmi Pandit is from Hyderabad, Telangana State, India. She is a retired Professor and a bilingual Poet and Writer. Expressing in her poetry and writings the beauty and purpose of human life is her aptitude. She has published about 25 books between 2005 to 2023. Eight of her Telugu anthologies including 1 Hykoos .One English anthology titled “ Wisdom Of Oneness” was published by Patridge Publishes.(2015).Her 2 long poems in Telugu one on “ Save the Earth “ concept translated into English and Hindi titled “Mother Earth Bemoan ”( Authors Press), in Hindi “ Dharthi Ka Vilaap”(Academic Press, Delhi).The other Telugu long poem on Universal love and brotherhood translated into English and Hindi. She has translated Ravindranath Tagore`s Gitanjali into Telugu titled” Apoorva Gaanam “.", "photo": "assets/writers/279-earth-voice-v1.webp"}, {"id": "writer-404", "name": "Pallabi Das", "bio": "Pallabi Das writes poetry both in Odia and English.", "photo": "assets/writers/404-earth-voice-v1.webp"}, {"id": "writer-431", "name": "Pankajam Kottanath", "bio": "Pankajam, a bilingual writer, poet and novelist, is the author of 48 books including 30 books of poems, besides a French translation of one of her books and have contributed poems/articles and reviews to numerous national/international journals/anthologies. Her works havebeen discussed by literary critiques besides an exclusive book of research papers on her works. She is the recipient of awards like Rock Pebbles National Literary Award 2019, Reuel International Literary award for Lifetime Achievement 2022, Global Literary Leadership Award 2022 from Gujarat SahityaAkademi&MS, MVV Creative Writer Poetry Award 2023, ISISAR Literary Eloquence award, 2024, among others.", "photo": "assets/writers/431-earth-voice-v1.webp"}, {"id": "writer-183", "name": "Pankhuri Sinha", "bio": "Bilingual Indian poet and writer with ten books published, many lined up. Has won many prestigious, national-international awards, including Premio Galateo and Cittadel Galateo in Italy, and has been published in journals and anthologies, home and abroad. She has been translated in over twenty seven languages.", "photo": "assets/writers/183-earth-voice-v1.webp"}, {"id": "writer-62", "name": "Paramita Mukherjee Mullick", "bio": "Dr. Paramita Mukherjee Mullick is a scientist, a national scholar transformed into an internationally acclaimed and award-winning poet. She has published nine books. Her poems have been translated into 40 world languages and her poems have been widely published in national and international journals and anthologies. Paramita is the President and Initiator of the Mumbai Chapter of the Intercultural Poetry and Performance Library (IPPL). She is also the Cultural Convenor and Literary Coordinator (West India) of the International Society for Intercultural Studies and Research (ISISAR). She passionately promotes peace poetry, indigenous poetry, multilingual poetry and global poetry. She promotes fusion of poetry with other performing arts and uses poetry to promote awareness about climate change and conservation. Paramita also does a lot of workshops for teachers and students in schools to promote poetry in children. Apart from numerous awards from Indian Literary concerns for her poetry, she has been blessed with the Gold Rose Award from MS Productions, Buenos Aires, Argentina for promotion of Literature and Culture in 2019. Paramita was one of the recipients of the prestigious Panorama International Literature Award 2022, given by the World Capital Foundation, Greece for her poetry.", "photo": "assets/writers/62-earth-voice-v1.webp"}, {"id": "writer-58", "name": "Parashuram Rao Gande", "bio": "Parashuram Rao Gande is the former Head ,Department of English ,SRR Govt Arts and Science College,Karimnager.Je is the author two poetry books entitled `Pebbles in Pranahitha` and `The Sound of the Surging Waves.He contributed poems to Sixty International poetry anthologies.He was awarded with Enchanting Muse Award and Literary Honour 2022.", "photo": "assets/writers/58-earth-voice-v1.webp"}, {"id": "writer-43", "name": "Paresh Kumar Pattnaik, Managing Editor", "bio": "Paresh Kumar Patnaik, an eminent story teller and novelist writing in Odia, is well-known for his extra-ordinary style of writing short stories for the last three decades. A recipient of Odisha Sahitya Academy award, Patnaik has carved a niche for himself with the craft of his story telling. His novels and stories highlight social issues with unique style of humour and compassion. He is a strong voice against religious fanatism and superstitions, while his stories on mythology show new interpretation of characters. He has fifteen story collections and three novels to his credit. Sri Patnaik lives in Bhubaneswar . He can be contacted at .", "photo": "assets/editors/paresh-kumar-pattnaik-artistic-v2.webp"}, {"id": "writer-306", "name": "Paulami Sengupta", "bio": "Paulami Sengupta is a publishing professional based in Kolkata. Her poems (in English and Bengali) and translations have been published in The Dreaming Machine, Nether, Cold Noon, and The SunflowerLiterary Collective. Her recent collection of Bengali poems (under her pen name Anjashi) is titled Bayosandhir Haraf (Boibhashik, 2021). Her first collection of poems in English, Maximum Love in Patel Nagar (Red River), has been published this year.", "photo": "assets/writers/306-earth-voice-v1.webp"}, {"id": "writer-30", "name": "Phani Mohanty/ଫନୀ ମହାନ୍ତି", "bio": "Phani Mohanty is a major voice in contemporary Odia poetry. He has been active in creative literature for almost five decades. He has several poetry collections to his credit and few of them have been translated into English, Hindi and other Indian languages. A winner of Odisha Sahitya Akademi as well as Central Sahitya Akademi awards , he is presently staying with his family in Bhubaneswar.", "photo": "assets/writers/30-earth-voice-v1.webp"}, {"id": "writer-120", "name": "Piyusha Pattnaik/ପୀୟୂଷ ପଟ୍ଟନାୟକ", "bio": "", "photo": "assets/writers/120-earth-voice-v1.webp"}, {"id": "writer-180", "name": "Poonam Sood", "bio": "Poonam Chawla Sood is a bilingual Indian author and translator known for her published work in various journals and anthologies across the globe. She is the founder chairperson of Gulzar Sahitya Samiti. She has published two poetry collections and two translations.", "photo": "assets/writers/180-earth-voice-v1.webp"}, {"id": "writer-169", "name": "Prabashini Mahakuda", "bio": "Pravasini Mahakud is an Odia poet and translator. She has written thirteen odia poetry collections and also translated twenty books from hindi to odia. One of her odia poetry collections has also been translated into hindi. She is the recipient of the Odisha Sahitya Akademi Award, Jhankar award, Junior and Senior fellowship from the Ministry of Culture, Government of India.", "photo": "assets/writers/169-earth-voice-v1.webp"}, {"id": "writer-327", "name": "Prabhanjan K. Mishra", "bio": "Prabhanjan K Mishra, former editor of POIESIS, the journal of poetry of the association of poets, the `Poetry Circle` of Mumbai, the poet-association`s former president, a poet, writer, translator, reviewer, using English and Odia (his mother tongue) for writing, poetry and translation from one to the other. He is from Odisha but lives in Mumbai. (098215661608, for telephone and WhatsApp chat. For email )", "photo": "assets/writers/327-review-retry-v1.webp"}, {"id": "writer-474", "name": "Prachitara / ପ୍ରାଚୀତାରା", "bio": "Prachitara is a pioneer professional storyteller, former journalist, and anchor from Odisha with an MA and B.Ed. Trained in classical music, dance, and theatre, she conducts workshops for schools, teachers, and parents. She collaborates with government departments, NGO banners, and major festivals like BhuFeSto to promote culture and education.", "photo": "assets/writers/474-earth-voice-v1.webp"}, {"id": "writer-102", "name": "Pradeep Rath,", "bio": "Pradeep Rath, a retired bureaucrat, authored eight volumes of drama, one volume of Kavya, two volumes of criticism and two volumes of travelogue and one memoirs. A keen student of literature, history and contemporary politics, he divides his time in reading, writing and travels.", "photo": "assets/writers/102-earth-voice-v1.webp"}, {"id": "writer-197", "name": "Pradeepti Sharma", "bio": "Pradeepti Sharma is from Nagpur, Maharashtra. BE, MBA, ex banker. Now, a writer, and also work as an interior designer too. She love cooking and gardening. Love creating- Manifesting creative energy into a work of art, food, or an act of expression of love and warmth to kids and the aged.", "photo": "assets/writers/197-earth-voice-v1.webp"}, {"id": "writer-1", "name": "Pradip Biswal, Editor", "bio": "Sri. Pradeep Biswal is a reputed bilingual poet writing both in Odia and English for almost four decades. He has six poetry collections in Odia and two in English. Two poetry collections in Hindi have been published carrying his poems translated into Hindi. He is an accomplished translator and editor. His poems have been translated into various Indian languages and got published in reputed journals /e-journals and anthologies nationally and internationally. As a senior IAS officer he had held many senior positions in Government of Odisha and retired as Special Secretary in Finance Department. Presently, he is holding the post of Administrative Member,", "photo": "assets/editors/pradeep-biswal-artistic-v2.webp"}, {"id": "writer-315", "name": "Prafulla K. Panda", "bio": "Dr. Prafulla K. Panda (b. 1978..) is a Lecturer by profession and a poet by passion. He has been ardently writing about love and human relation; about life and death; about nature and societal issues. His poems have been widely published in various national and international anthologies, magazines and online platforms. He has published a collection of poetry named `Bounty of Silence: Verses Unveiling the Songs of Soul`, and edited an inter-continental anthology `Beyond the Horizon`. He hails from Tilada, under Khaira Block of Balasore District, Odisha, India.", "photo": "assets/writers/315-earth-voice-v1.webp"}, {"id": "writer-325", "name": "Pragyan Pattnaik", "bio": "Pragnya Patnaik is an Author-Activist who has authored two books in English, and one in Sambalpuri. She has also translated two international bestsellers to Odia. She is the recipient of the prestigious Dr. Nilamadhab Panigarhi Puraskar from Sambalpur University for the Sambalpuri book ‘Ranga’. She writes in various genres like poems, short stories, plays, columns, novels, and features. Pragnya is an IT Consultant by Profession. ?", "photo": "assets/writers/325-earth-voice-v1.webp"}, {"id": "writer-27", "name": "Prahallad Satapathy/ଡ଼.ପ୍ରହଲ୍ଲାଦ ଶତପଥୀ", "bio": "Dr. Prahallad Kumar Satapathy who hails from Balangir(odisha) is an retired associate professor in Economics. He is a bilingual poet ,writing both in Odia and English language. He has represented Odisha Sahitya academy twice as honorary member. To his credit he has five published anthologies in odia. His poems (both odia and English) are published in national and international anthologies. Recently he has shared creative space in KAVI SANDHI program of Kendra sahitya academy.", "photo": "assets/writers/27-earth-voice-v1.webp"}, {"id": "writer-205", "name": "Pranati Behera / ପ୍ରଣତି ବେହେରା", "bio": "", "photo": "assets/writers/205-earth-voice-v1.webp"}, {"id": "writer-212", "name": "Prasanna Kumar Swain / ପ୍ରସନ୍ନ କୁମାର ସ୍ଵାଇଁ", "bio": "Prasanna Kumar Swain writes poetry in Odia. He lives in Cuttack.", "photo": "assets/writers/212-earth-voice-v1.webp"}, {"id": "writer-70", "name": "Pratiksha Jena/ପ୍ରତୀକ୍ଷା ଜେନା", "bio": "Pratikhsha Jena writes in Odia. She is a Poet and Novelist of repute. She has five Poetry Collections and one Novel in Odia to her credit. The Sorrows of being God and other poems is her translated Poetry collection in English.", "photo": "assets/writers/70-earth-voice-v1.webp"}, {"id": "writer-121", "name": "Prativa Parida/ପ୍ରତିଭା ପରିଡା", "bio": "", "photo": "assets/writers/121-earth-voice-v1.webp"}, {"id": "writer-41", "name": "Pravakar Satapathy/ ପ୍ରଭାକର ଶତପଥୀ", "bio": "Pravakar Satpathy is a senior Odia poet having several poetry collections to his credit. He was once editing a literary journal ’ Anisha ‘ in Odia which had a distinct identity. His present address is village Banamalipur , via- Dharmasala District-Jajpur-755008. He can be contacted by Mobile Phone No-9437890095", "photo": "assets/writers/41-earth-voice-v3.webp"}, {"id": "writer-112", "name": "Preety Bora", "bio": "Preety Bora, born in the beautiful state of Assam, (India), and she lives in a small city called \" Golaghat \" with her family. She is a bilingual poet, she weaves poetry in both languages : in English and in Assamese ( mother tongue). Her poems have been featured in various anthologies and magazines in India and in foreign countries too. She is highly inspired by Nature. Besides writing, she is fond of cooking, designing and listening to music. The names of the books where she contributed poems are : \" Oh My Sweetest Love \", \"The World Anthology of Poetry \" , \"SEASON OF LOVE \", \"A SUBLIME COLLECTION of ACROSTICS \"(ON YAYATI MADAN GANDHI), \"SYMPHONY OF PEACE \", \"A bouquet of Verse ( Volume 1 )\", LOVE AT FIRST SIGHT \" \", \" GloMag \", \" Interdisciplinary Journal of Literature and Language \", \" Whispering Poiesis \", \" TRANQUIL MUSE \",\" My Tears\" etc, and she is one of the co-editors of a bilingual book entitled \" Hazar kobir sapun \" .", "photo": "assets/writers/112-earth-voice-v1.webp"}, {"id": "writer-316", "name": "Pritha Chakraborty", "bio": "Pritha Chakraborty is an Assistant Professor in the Post-Graduate Department of English, Maulana Azad College, Kolkata. Over the last two decades, she has taught at several colleges, presented papers in several conferences and has a number of publications to her credit. She has translated Bengali prose and poetry and her poems have been published in several anthologies. She is involved with an NGOs which works for post-cyclone rehabilitation and `Tiger Widows` of the Sundarbans. She is passionate about photography, travelling and Indian classical dance.", "photo": "assets/writers/316-earth-voice-v1.webp"}, {"id": "writer-199", "name": "Priyalakshmi Gogoi", "bio": "Priyalakshmi Gogoi is from Guwahati, Assam, India. A Teacher by profession and a poet by passion, she has been writing since her school days and her poems have been published in popular newspapers in her city.", "photo": "assets/writers/199-earth-voice-v1.webp"}, {"id": "writer-283", "name": "Priyanka Banerjee", "bio": "Priyanka Banerjee is a poet and an Academician from Kolkata, India. She has published her poetry in numerous International Anthologies and websites including ` Paradise on Earth`, ` Timeless Inspiration`,` Echoes of the African Drum`, williwashwordpress.com( Nigeria), globalpoetandpoetry.com(U.K), transcendental zero press( U.S) etc. Her first book,` Touches and Turbulences`got published in 2023 and it got WIP awarded. It also got nominated for the Right Livelihood Award or Alternative Nobel Award.", "photo": "assets/writers/283-earth-voice-v1.webp"}, {"id": "writer-364", "name": "Punyadeepa Khamari / पुण्यदीपा खमारी", "bio": "The poet holds a Master of Science degree in Botany and has made significant contributions to the world of poetry. Her first published work appeared in the poetry collection \"Nishan, Ghumura\" in 2010 marking the beginning of a prolific writing career. The poet has received numerous accolades for their work, including the \"Agami Sambhabana\" award from Rebati and recognition as a \"Pride Daughter of the Soil\". Her presence has been felt in various youth programs, where she served as a guest speaker in Odia as well as in a Hindi youth program called Jharko.Her contributions to literature have also led to invitations as a guest writer at the Kendra Sahitya Akademi.Notably, the poet has published a Hindi poetry book titled \"E Maan Thoda Thahar Ja.\"", "photo": "assets/writers/364-earth-voice-v1.webp"}, {"id": "writer-65", "name": "Purabi Das", "bio": "Purabi Das is a poet, translator and columnist. Born in 1967 to well known short story writer, Sudhir Kumar Bijayendra Narayan and Bandana Narayan, she has published eight books including four volumes of poetry. She is currently residing in Florida, USA.", "photo": "assets/writers/65-earth-voice-v1.webp"}, {"id": "writer-314", "name": "Purabi Satapathy/ ପୂରବୀ ଶତପଥି", "bio": "Purabi Satapathy was born on 13/06/81 in village Rasol of Dhenkanal District. Daughter of Mrs Satyabhama Mishra and Mr Bhakta Bandhu Satapathy, she works as a Social Worker. Though she started her poetic journey at an early age, her first book `Raaga Purvee` was published by Kendra Sahitya Akademi in the year 2021. Her second book Sandeepan is in the process for publication. She doesn `t like to be bound with any `ism` other than `Humanism`. Self awakening, love, imaginary pictures of hope, nature and revolt against social injustice are clearly seen in her poetry. She believes in mystery and versatility in poetry.", "photo": "assets/writers/314-earth-voice-v1.webp"}, {"id": "writer-361", "name": "Pusparani Patel/ ପୁଷ୍ପରାଣୀ ପଟେଲ", "bio": "Pusparani Patel, a Post Graduate in Physics with BEd teaches Science in a Government High School in Rourkela. Her native place is Kuchinda in Sambalpur district of Odisha. She writes poetry, short stories and novel in Odia. She is credited with two sortstory collections in Odia.", "photo": "assets/writers/361-earth-voice-v1.webp"}, {"id": "writer-214", "name": "Rabi Satapathy / ରବି ଶତପଥି", "bio": "Rabi Satapathy is a poet and essayist. His poems have been published in all reputed journals and news papers. Also, his poems have been translated in different Indian languages and English. Since last 30 years he has been working as a literary organizer to promote Odia language and literature in tribal belts of Koraput District. He teaches Odia language and literature at Nandapur college, Koraput, Odisha.", "photo": "assets/writers/214-earth-voice-v1.webp"}, {"id": "writer-109", "name": "Rachita Swain", "bio": "", "photo": "assets/writers/109-user-selected-20261004.webp"}, {"id": "writer-230", "name": "Raghu Seshabhattar", "bio": "Raghu Seshabhattar ( born on 18 November 1970 ) - Indian poet writing in Telugu, published 8 books which include SEVEN POETRY COLLECTIONS & a collection of Literary Essays. He lives in Hyderabad & working with Iffco - Tokio General Insurance as Chief Legal Manager.", "photo": "assets/writers/230-earth-voice-v1.webp"}, {"id": "writer-368", "name": "Raja Chakraborty", "bio": "Born and brought up in Kolkata, India, Raja Chakraborty is a much published bilingual poet, writing in English and Bengali. He has penned six books of English poems. His Bengali publications span across eight books of rhymes and poems. He is also a regular contributor to magazines and anthologies.", "photo": "assets/writers/368-earth-voice-v1.webp"}, {"id": "writer-270", "name": "Raja Rajeswari Seetha Raman", "bio": "Dr.Raja Rajeswari Seetha Raman hails from Malaysia. She is a freelance lecturer, bilingual poet, researcher, certified translator, literary critic and essayist. Recipient of 16 literary prizes and awards, local and international. Her poems have been translated into forty world languages. Four poems are Malay songs. Her excellent contribution in the field of Malay Literature was made a documentary by The National Film Department of Malaysia and broadcast twice on TV1 in 2009 and 2012. In 2014 she was honored by the National Film Department of Malaysia as Icon of National Language Month and in 2020 as Women of the Year by MWAW (Malaysian Women at Work). A panel member of National Literary Policy and National Culture Policy for Malaysian Government. A member of World Nations Writers Union (WNWU).", "photo": "assets/writers/270-review-retry-v1.webp"}, {"id": "writer-104", "name": "Rajashree Mohapatra", "bio": "", "photo": "assets/writers/104-earth-voice-v1.webp"}, {"id": "writer-85", "name": "Rajendra Padhi", "bio": "Rajendra Kumar Padhi is a bilingual poet, novelist and translator. He attended world poetry Conference in Africa and recipient of Universal Inspirational Poet. His poems and articles have been published in more than 80 books and magazines. He has written 5 poetry books and one English novel. He has edited several books has translated into English Mahimandala Gita and Life of Saint Arakhita Das. His interviews have been published in and outside India.", "photo": "assets/writers/85-earth-voice-v1.webp"}, {"id": "writer-44", "name": "Rajorshi Patranabis", "bio": "Rajorshi Patranabis is a multilingual poet, translator and editor delving into myriad forms of poetry. A food consultant, by profession, and a Wiccan, by philosophy, his collections in English boasts of supernatural and metaphysical love poems( Crossover-love beyond eternity), sonnets(Pregnant), haiku(Solstice ), ghazals in English with a pen name Kafir( Through your Eyes), a collection of sonnets about 30 women characters from Ramayana and Mahabharata (Shaktirupen), collection of haibuns(Pallette ), in Bengali poems of love (Feriwala) and a couple of Assamese translation projects( Nirjon Soikot-Luit Hooghly, Ramp). He has been widely published in national and international journals and anthologies.", "photo": "assets/writers/44-user-selected-20261004.webp"}, {"id": "writer-359", "name": "Rakesh Chandra", "bio": "Dr. Rakesh Chandra is a former civil servant. He is a bilingual poet writing in English and Hindi. He has published five collections of poetry in English and ond in Hindi. His English poems have found place on various print and online spaces.", "photo": "assets/writers/359-earth-voice-v1.webp"}, {"id": "writer-422", "name": "Rakshak Nayak / ରକ୍ଷକ ନାୟକ", "bio": "Rakshak Nayak writes poetry in odia language. He is a recipient of Odisha Sahitya Academy Award. He lives in Bhubaneswar.", "photo": "assets/writers/422-earth-voice-v1.webp"}, {"id": "writer-352", "name": "Ramakanta Samantaray/ ରମାକାନ୍ତ ସାମନ୍ତରାୟ", "bio": "", "photo": "assets/writers/352-earth-voice-v1.webp"}, {"id": "writer-209", "name": "Ramakrushna/ ରାମକୃଷ୍ଣ", "bio": "Ramakrushna writes poetry in Odia. A post graduate in Odia, he has six collections of Odia poetry along with two books in English. He has four literature criticism books in Odia to his credit. He has receives several of awards for his contribution to Odia literature.", "photo": "assets/writers/209-earth-voice-v1.webp"}, {"id": "writer-341", "name": "Randy Brooks", "bio": "Dr. Randy Brooks is Professor of English Emeritus at Millikin University in Decatur, Illinois, where he teaches courses on haiku, tanka, and Japanese poetics. He and his wife, Shirley Brooks, are publishers of Brooks Books and co-editors of Mayfly haiku magazine. His most recent books include Walking the Fence: Selected Tanka and The Art of Reading and Writing Haiku: A Reader Response Approach.", "photo": "assets/writers/341-earth-voice-v1.webp"}, {"id": "writer-182", "name": "Ranjan Kumar Das", "bio": "Ranjan Kumar Das is multilingual writer writes both in English and Odia, He has twenty eight books to his credit. He writes in almost all fields of literature, be it poetry, short story, drama , travelogue, lyrics, columns or dialogue for films. He is a Senior Bureaucrat and presently working as Director, Culture in Govt. of Odisha.", "photo": "assets/writers/182-earth-voice-v1.webp"}, {"id": "writer-144", "name": "RANJANA SHARAN SINHA", "bio": "Dr. Ranjana Sharan Sinha is an eminent poet, author and retired professor of English from Nagpur, Maharashtra, India. She is a well-known voice in Indian Poetry in English with international recognition. Her poems from her collection \"Scents and Shadows\" are included in Postgraduate University Syllabus and have been translated into German, Greek, Albanian, Spanish, Persian, Russian, Mexican, Nepali, Chinese and Hindi languages. She has received a number of awards for her contribution to poetry that includes a commendation from the former President of India A.P.J.Abdul Kalam for her poem\"Mother Nature\" contained in her collection\"Spring Zone\". She has authored and published 09 books in different genres and 50 research papers. Her poems, short stories, articles and research papers have been widely published in acclaimed dailies, magazines, e-zines, archives and journals in print and online.", "photo": "assets/writers/144-earth-voice-v1.webp"}, {"id": "writer-145", "name": "Ranjit Dutta", "bio": "Dr Ranjit Dutta M.A,M.Phil,Ph.D , is a bilingual Poet ,Novelist ,Critic , lyricist and Translator and published in Assamese ,English language.He has authored three novels in Assamese namely \"Keijonman Bondhu dutiman Golpo Aru Ekhon Upayanakh\",\"Kolahirar Dekholoi\" and \"Nishter Kothare\" ,six volumes of poetry in Assamese such as \"Hridoyot Junak\", \"Kehraj Buliya Anubhob\",\"Kobita Mur Mouna Prohoror\",\"Niribili Nijanote\" ,\"Hur Eti Diyana\" Hunyata Aru Kulaholor Dumujat\" and five Translation volumes of world poetry from English to Assamese language such as \" Esati Hugodhi Moloya Part -I , Part II and part-III and East Wind and \"Flows Like a River\" \"Peeping through the Windows\" from Assamese to English.", "photo": "assets/writers/145-earth-voice-v1.webp"}, {"id": "writer-186", "name": "Ranjita Panda", "bio": "Ranjita Panda is a prominent young voice in contemporary Odia poetry. She has six anthologies to her credit. She has also published one novel in Odia.", "photo": "assets/writers/186-user-selected-20261004.webp"}, {"id": "writer-318", "name": "Ranu Uniyal", "bio": "Ranu Uniyal is Professor of English at Lucknow University. Her poetry has appeared in Mascara Literary Review, Jaggery, Medulla Review, Sketch Book, Twenty 20, Whispers, Littlewood Press, Muse India, Kavya Bharati, Femina, Manushi, Indian Literature and several anthologies both in India and abroad. She has published four poetry collections: Across the Divide (2006) and December Poems (2012). Her English poems have been translated in Hindi, Malayalam, Urdu and Uzbek languages. She also writes poetry in Hindi. She is a founding member of a day care centre for children with special needs in Lucknow.", "photo": "assets/writers/318-earth-voice-v1.webp"}, {"id": "writer-76", "name": "Rashmi Mohapatra/ ରଶ୍ମି ମହାପାତ୍ର", "bio": "Masters in economics from JNU, NewDelhi. Took VRS from a nationalised bank as an official in senior management grade. Four anthologies of Odia Poems have since been published. One anthology of English poems, one of Odia poems and one compilation of Haikus are in final stage of publication. Lives in Mumbai. Writes poetry in Odia and English.", "photo": "assets/writers/76-earth-voice-v1.webp"}, {"id": "writer-254", "name": "Ratnamala Swain / ରତ୍ନମାଳା ସ୍ବାଇଁ", "bio": "Ratnamala Swain is an architect and builder by profession but a poet by passion. He is also translator of repute", "photo": "assets/writers/254-earth-voice-v1.webp"}, {"id": "writer-342", "name": "Reema Sinha", "bio": "Reema Sinha is from Lucknow, She has a BSc degree with Doctorate in literature. She works as a writer along with Bureau Chief in Country of India newspaper, Vice Chairman in Print media working journalist association, Founder of Niharika Sahitya Manch. Her published works are Asha, Noyonika and many shared collection. She got got many online and offline awards, main awards are Bharat Ratna Atal samman, Mahadevi verma smriti samman, Amrita Pritam samman etc.", "photo": "assets/writers/342-earth-voice-v1.webp"}, {"id": "writer-267", "name": "Reetwika Banerjee", "bio": "Reetwika Banerjee is a Cybersecurity Specialist by profession. She is representing Bengal as the State President of Public Safety & Security Council of Women`s Indian Chamber of Commerce & Industry. But creative writing, filmmaking and travel at leisure make her complete. She has authored ten bestsellers including `The Secret Murder Witness of Siraj-ud-Daulah`, `Zenova`, `Travel Tales` series to name a few. She is an invited speaker at London`s Silent Voice Radio Station. Celebrities like Babul Supriyo, Urmimala Basu, Subrata Dutta, Saheb Chatterjee, Chaiti Ghoshal, Bhaswar Chatterjee, Srabanti Majumdar etc have narrated her stories on BigFM, Radio Mirchi and other radio channels. Her latest crime thriller novel hallmarked the To 10 Must Reads of 2021 by Outlook India magazine.", "photo": "assets/writers/267-user-selected-20261004.webp"}, {"id": "writer-203", "name": "Renette D Souza", "bio": "Renette D Souza - A writer, editor entrepreneur is a strong believer in the simple policy of Live and let live with love and peace and with a passion for travelling, photography and writing poetry, her work has been published in many National as well International Anthologies on a broad range of subjects. A recipient of many awards, her poems have also aired on live shows and featured in various e-magazines.", "photo": "assets/writers/203-earth-voice-v1.webp"}, {"id": "writer-410", "name": "Rima Sinha", "bio": "Rima Sinha writes poetry in Hindi.", "photo": "assets/writers/410-earth-voice-v1.webp"}, {"id": "writer-293", "name": "Rita Chugh", "bio": "World Record Holder Rita Chugh is an Internationally recognized, Award - Winning bilingual Poetess, Author, Editor, Social Activist, International Ambassador Of Peace, Universal Icon Of Poetry, recipient of several National and International Awards. She has authored two Hindi and an English poetry books, co-author of 46 Anthologies. Her poems have been published in many Magazines, Journals, E-zines and Newspapers. Her poems have been translated into many International languages. She has been featured as one of the World`s Contemporary poet, invited as Guest of Honour by many Literary Organizations, featured on many national and international TV channels and has been recognized as ` World Literature Star`.", "photo": "assets/writers/293-earth-voice-v1.webp"}, {"id": "writer-269", "name": "Ritamvara Bhattacharya", "bio": "Ritamvara Bhattacharya writes from a darling`s heart, Darjeeling. She believes in what Sylvia Plath said, “And by the way, everything in life is writable about if you have the outgoing guts to do it, and the imagination to improvise. The worst enemy to creativity is self-doubt.” She writes for the pleasure of it. She writes for the `I am in her heart, a voice that creates ripples and sensation. She received The Nissim International Poetry Prize in the year 2020 and the Tagore Poetry Prize in 2020. Her poems have been published in some noted portals like The Muse India, Café Dissensus, The Sunflower Collective, Aynanagor, Chakkar, The Indian Periodical, Plato`s Cave and others. Her debut chapbook,` In the mirror, our graves` along with veteran writer Ravi Shankar N published in 2021 has received accolades. She is an avid lover of life, literature, colours and has lived in awe for the past quarter-century. She intends to see the world stricken with fear and courage, in silence and sound, in love and hatred et all. She believes contradiction adds to the aroma of living and would love to dwell in the same giving birth to more celebratory bells.", "photo": "assets/writers/269-earth-voice-v1.webp"}, {"id": "writer-165", "name": "Ritu Mahipal / रितु महिपाल", "bio": "", "photo": "assets/writers/165-earth-voice-v1.webp"}, {"id": "writer-98", "name": "Rituparna Khan", "bio": "Raina alias Rituparna Khan is an author drowned in her own world of dream-weaving. Two books, one short story and a book of poetry , are credited to her. Her third work, a novella is to be published shortly.", "photo": "assets/writers/98-earth-voice-v1.webp"}, {"id": "writer-245", "name": "Riyahh Nanda/ରିୟା ନନ୍ଦ", "bio": "Riyahh Nanda is a budding young poet from Bhubaneswar, Odisha. She is also a TV anchor and model.", "photo": "assets/writers/245-user-selected-20261004.webp"}, {"id": "writer-435", "name": "Rohit Dash", "bio": "Rohit Dash writes poetry in Odia and English", "photo": "assets/writers/435-earth-voice-v1.webp"}, {"id": "writer-172", "name": "Rumpa Ray-Ghosh", "bio": "Rumpa Ray-Ghosh is a published poet, a curriculum developer , blogger and a trained classical vocal singer.", "photo": "assets/writers/172-earth-voice-v1.webp"}, {"id": "writer-105", "name": "Runa Srivastava", "bio": "Runa Srivastava is an author of two books, Anchor and Rescued. She has also contributed to many anthologies and journals. Being a botanist she did some work on genetic engineering. She is a keen photographer and is widely travelled. She lives in Kolkata with her husband", "photo": "assets/writers/105-earth-voice-v1.webp"}, {"id": "writer-385", "name": "Rupa Rao", "bio": "Rupa Rao is a USA based bilingual inker, she holds an MBA and LLB from Bombay in India. She is on hiatus from corporate career. Her writings are featured in multiple poetry anthologies, magazines and literary platforms. She juggles writing, moderating and administration tasks for a few literary groups. She`s a dedicated nature walker, enjoys regular yoga, and picks meaningful engagements to constantly grow. She has curated, edited and co-authored Four poetry anthologies.", "photo": "assets/writers/385-earth-voice-v1.webp"}, {"id": "writer-337", "name": "Sabita Singh Meera/ सविता सिंह मीरा", "bio": "Sabita Singh Meera is an acclaimed Hindi poetess of repute having several collections of poetry. Her poems are widely translated into other languages. She resides in Jamsedpur.", "photo": "assets/writers/337-earth-voice-v2.webp"}, {"id": "writer-319", "name": "Sabyasachi Bisoi/ ସବ୍ୟସାଚୀ ବିଷୋୟୀ", "bio": "Sabyasachi Bisoi is a new generation poet writing in Odia. He resides at Kantamal under Nawrangpur District", "photo": "assets/writers/319-earth-voice-v1.webp"}, {"id": "writer-450", "name": "Sailabala Mahapatra / ଶୈଳବାଳା ମହାପାତ୍ର", "bio": "Sailabala Mahapatra (1960) is one of the contemporary major Indian women`s voices in poetry . She has 7 anthologies of poetry in Odia, 3 in Hindi, two collections of essays and 6 books for children in Odia, English and Hindi besides over hundred translations to her credit. She is also an educationist and editor. Her poems have been widely translated globally into various languages", "photo": "assets/writers/450-user-selected-20261004.webp"}, {"id": "writer-308", "name": "Sakti Sekhar Dash", "bio": "Sakti Sekhar Dash is a Fellow of Social Science Research Council, Open Association of Research Society, USA. He holds a PhD from Ravenshaw University, India. With a profound interest in literature, history, and culture, he has extensively studied the myths, legends, and folklore of ancient Greece, Egypt, Rome, and India. As a researcher he loves to revisit and re-examine ancient texts from multiple perspectives. An experienced educator and honorary member of Illinois Medieval Association, he has served as the editor-in-chief of an international peer-reviewed journal. He has extensively written and published on a diverse range of topics, including, modernism, Greek drama, environmental studies, Theatre of the Absurd, and Shakespearean drama.", "photo": "assets/writers/308-earth-voice-v1.webp"}, {"id": "writer-277", "name": "Sandhya Ghadei / ସଂଧ୍ଯା ଘଡେଇ", "bio": "Sandhya Ghadei is a teacher by profession and a poet by passion. She also writes short stories. She has few collections of short stories and poems to her credit.", "photo": "assets/writers/277-earth-voice-v1.webp"}, {"id": "writer-290", "name": "Sangarm Jena", "bio": "Sangram Jena is a bilingual poet writing both in English and Odia, His poems are translated in to Hindi, Bengli and Assamese languages. He edits an Odia magazine Nishant. He lives in Bhubaneswar.", "photo": "assets/writers/290-user-selected-20261004.webp"}, {"id": "writer-340", "name": "Sangeeta Dey ( Roy)", "bio": "Sangeeta Dey ( Roy) is a author, poet fiction and non-fiction essayist whose works has been published in several magazines, souvenirs, newspapers e journals national and international anthologies.She worked as a editor and co-editor in a few of these. “Whispers in the Blue”,is her debut book of poetry.Some of her quotes are google searchable.She`s a member of IPPL and ispell ( Assam Forum). A teacher by profession she loves this joyful vocation. She hails from Haflong DimaHasao, Assam.", "photo": "assets/writers/340-earth-voice-v1.webp"}, {"id": "writer-412", "name": "Sanghamitra Bhanja/ ସଂଘମିତ୍ରା ଭଞ୍ଜ", "bio": "Dr. Sanghamitra Bhanja is an eminent odia poet, short story writer and essayist.", "photo": "assets/writers/412-earth-voice-v1.webp"}, {"id": "writer-88", "name": "Sanghamitra Raiguru / ସଂଘମିତ୍ରା ରାଏଗୁରୁ", "bio": "Sanghamitra Raiguru, is Bsc Bed,MA in Hindi literature and a poet, translator and performer. She has six Odia books and two Hindi books to her credit. She has translated Premchand’s two Novels into Odia.She has bagged a good number of Awards for her contribution to Literature. She can be contacted at .", "photo": "assets/writers/88-earth-voice-v1.webp"}, {"id": "writer-333", "name": "Sangita Das/ ସଂଗୀତା ଦାସ", "bio": "Sangeeta Das writes in Odia, She resides in Cuttack and works as a Guest Lecturer in English at BOSE, Cuttack.", "photo": "assets/writers/333-earth-voice-v1.webp"}, {"id": "writer-413", "name": "Sangram Maharana/ ସଂଗ୍ରାମ ମହାରଣା", "bio": "Sangram Maharana writes poetry in odia.", "photo": "assets/writers/413-earth-voice-v1.webp"}, {"id": "writer-349", "name": "Sanjay Kumar Sahoo/ ସଂଜୟ କୁମାର ସାହୁ", "bio": "", "photo": "assets/writers/349-earth-voice-v1.webp"}, {"id": "writer-461", "name": "Sanjukta Dash", "bio": "Sanjukta Dash is a bilingual poet writing in Odia and English for over three decades. Her poems capture the fragrance of emotions, the rhythm of nature, and the many shades of human life. Till date she has published four Anthologies of Poems in Odia and One in English.", "photo": "assets/writers/461-earth-voice-v1.webp"}, {"id": "writer-427", "name": "Sankar Narayan Mallick", "bio": "Sankar Narayan Mallick is a bilingual poet, writer and translator. He lives in Bhubaneswar.", "photo": "assets/writers/427-user-selected-20261004.webp"}, {"id": "writer-393", "name": "Sankha Ranjan Patra", "bio": "Sankha Ranjan Patra is a poet and author . He belongs to India.He writes in English, Bengali and Hindi. His published books are Muse,Mute ,All About Love and Borsha . Muse and Mute are poetry books in English. All About Love is a novel in English. Borsha is a poetry book in Bengali.He has contributed for many anthologies and magazines. He has been honoured by different literary societies.", "photo": "assets/writers/393-earth-voice-v1.webp"}, {"id": "writer-215", "name": "Santasree Choudhury", "bio": "Shantashree Choudhury is an award winning social entrepreneur, women`s rights activist, writer, poet, poetry film maker. She is the Founder trustee of Green Tara Social Initiative. She lives in Kolkata.", "photo": "assets/writers/215-earth-voice-v1.webp"}, {"id": "writer-107", "name": "Santosh Bakya", "bio": "", "photo": "assets/writers/107-earth-voice-v1.webp"}, {"id": "writer-418", "name": "Sarbani Chakravarti", "bio": "Ms. Sarbani Chakravarti has a master`s degree in both English and Business Administration. After having worked in different corporate sectors like banking, insurance and advertising, she migrated to the academic field and has been in the teaching profession for more than a decade. She has worked as an English Language teacher in a bilingual school in Zurich, Switzerland and has also conducted sessions with parents and children Ms. Chakravarti is a published author and poet, podcaster, independent researcher, motivational speaker, compere, model, blogger, avid reader and globetrotter.", "photo": "assets/writers/418-earth-voice-v1.webp"}, {"id": "writer-146", "name": "Sarita Jenamani", "bio": "Sarita Jenamani is an Austria-based poet of Indian origin, a literary translator, anthologist, human rights activist and feminist. She is the editor of a bilingual magazine for migrant literature: Words & Worlds, and general secretary of PEN International`s Austrian chapter. She has so far been published in three collections of poetry. Jenamani is the co-editor of the anthology Silence Between the Notes: a collection of partition poetry from South Asia. She has also edited the first-ever anthology of poetry on violence against women in South Asia: Still We Sing. Jenamani has translated several Austrian poets including, Rainer Maria Rilke, Georg Trakl, Rose Ausländer etc. into Hindi and Odia. She has received many literary fellowships in Germany and Austria .", "photo": "assets/writers/146-earth-voice-v1.webp"}, {"id": "writer-101", "name": "Sarita Naik", "bio": "Sarita Naik is a prominent budding poet who works as a lecturer in English at Pipli College,Puri. She is a writer, author,poet, Dancer and Singer by Passion. Miss Naik has received Gold Medal in M.phil in English literature from GMU(Gangadhar Meher University). She weaves poetry in three languages English, Odia and Hindi. Miss Naik is the editor of a literary Journal named “ Srujanika “. She has been appreciated by the national and international literary circles.", "photo": "assets/writers/101-earth-voice-v1.webp"}, {"id": "writer-424", "name": "Sarita Pradhan / ସରିତା ପ୍ରଧାନ", "bio": "Sarita Pradhan is a housewife residing at Cuttack. She is a post graduate in Odia and writes in Odia. She has been credited with one collection of poetry in Odia and her second book of poetry is likely to be published shortly.", "photo": "assets/writers/424-earth-voice-v1.webp"}, {"id": "writer-181", "name": "Sarita Prusty", "bio": "Sarita Prusty is Former lecturer in English At Kanhu charan Degree Mahavidyala, Korei, Jajpur Former creative writing and public speaking Trainer at Planet Spark (online) Spoken English Trainer at FITA Academy, Chennai. An anchor, singer and poet.", "photo": "assets/writers/181-earth-voice-v1.webp"}, {"id": "writer-235", "name": "Sasmita Rout", "bio": "Sasmita Rout is from Talcher ,Anugul, Odisha.Her poems get published in various literary pages in Odia.", "photo": "assets/writers/235-earth-voice-v1.webp"}, {"id": "writer-475", "name": "Saswati Hota  / ଶାଶ୍ଵତୀ ହୋତା", "bio": "Saswati Hota  writes Odia poetry.", "photo": "assets/writers/475-earth-voice-v1.webp"}, {"id": "writer-276", "name": "Satya Meher/ ସତ୍ଯ ମେହେର", "bio": "Satya Meher is a Riyadh based Odia poet who has been active in creative writing since eighties. His poems get published in reputed literary journals at regular intervals.", "photo": "assets/writers/276-earth-voice-v1.webp"}, {"id": "writer-448", "name": "Satya Sundar Samanta", "bio": "satyasundar samanta 10:59 (5 minutes ago) to me Dr. Satya Sundar Samanta is an eminent English poet in the history of Indian English literature of the twenty first century. His earlier poetry books are \"Border Poems\", \"The Still Times\" and \"The Subarnarekha\". His critical work is \"Autobiographical Elements of John Keats\". He is an honours and MA in English Literature. He did M.Phil from CSJM University. He also completed Ph.D in English Literature from MSCB University. His 24 research articles have been published in different journals and magazines. His poems are regularly published in different journals, magazines and newspapers. Plantation is his hobby. He has either planted or given more than 10, 000 plants across the country. He has been awarded five times for his poems and social activities.", "photo": "assets/writers/448-earth-voice-v1.webp"}, {"id": "writer-399", "name": "Satyananda Sarangi", "bio": "Satyananda Sarangi is a young civil servant by profession. A graduate in electrical engineering, his works have featured in The HyperTexts, Shot Glass Journal, Snakeskin, WestWard Quarterly, Sparks of Calliope,The Society of Classical Poets, Page & Spine, Glass: Facets of Poetry, The GreenSilk Journal and elsewhere. In 2024, he became the 1st and only Indian poet placed in the Honorable Mention Category of the Annual International Poetry Competition of The Society of Classical Poets, New York for two consecutive years. Recently, his poem “The School Bell” has been put up on public display by Poetry Box Organisation in Portland, Oregon, USA. He currently resides in Odisha, India.", "photo": "assets/writers/399-earth-voice-v1.webp"}, {"id": "writer-297", "name": "Satyaranjan Praharaj/ ସତ୍ୟ ରଞ୍ଜନ ପ୍ରହରାଜ", "bio": "Satyaranjan Praharaj is from Jajpur. He works in state Secretariat, Bhubaneswar. His first poetry collection `Michha Jahnarati`,is published recently and appreciated by poetry lovers.", "photo": "assets/writers/297-earth-voice-v1.webp"}, {"id": "writer-239", "name": "Seema Sharma", "bio": "", "photo": "assets/writers/239-review-retry-v1.webp"}, {"id": "writer-189", "name": "Seeta Maya Rai", "bio": "Seeta Maya Rai, an author of `Seasons and Senses` is a high school graduate from Dorokha Lumbay belonging to Samtse District. From her early days in school and till so far, she has written more than hundred poems whereby some of them are published and featured in many anthologies such as Bhutan at her Best, Bharat Vision, World Poetry Tree. She is also a recipient of many writing awards and out of all, the Order of Shakespeare Medal and Rabindranath Tagore Memorial Literary Honour are the prominent international honours in literature awarded by Motivational Stripes, one of the word`s active writers` forum.", "photo": "assets/writers/189-earth-voice-v1.webp"}, {"id": "writer-288", "name": "Selma Kopic", "bio": "Selma Kopic is poet from Bosnia.", "photo": "assets/writers/288-earth-voice-v1.webp"}, {"id": "writer-69", "name": "Senapati Pradyumna Keshari/ସେନାପତି ପ୍ରଦ୍ୟୁମ୍ନ କେଶରୀ", "bio": "Senapati Dr. Pradyumna Keshari, Associate professor in Odia(retd) a widely nationally acclaimed poet of contemporary odia literature.He has authored ten poetry collections to his credit.", "photo": "assets/writers/69-earth-voice-v1.webp"}, {"id": "writer-360", "name": "Shakuntala Gupta/ ଶକୁନ୍ତଳା ଗୁପ୍ତା", "bio": "Dr Shakuntala Gupta, writes in both Odia and English. She is a member of poet association SAPNE, Boston chapter, Odiya Sahitya Tungi literature group. She currently works as a teaching and research faculty at Rourkela, Odisha.", "photo": "assets/writers/360-earth-voice-v1.webp"}, {"id": "writer-365", "name": "Shankar Chhatria / ଶଙ୍କର ଚ୍ଛତ୍ରିଆ", "bio": "", "photo": "assets/writers/365-user-selected-20261004.webp"}, {"id": "writer-220", "name": "Shankar Parida/ଶଙ୍କର ପରିଡା", "bio": "", "photo": "assets/writers/220-review-retry-v1.webp"}, {"id": "writer-96", "name": "Sharanya", "bio": "Sharanya is a literature student from Trivandrum (Kerala, India). Her poems have been published in several online and offline literary magazines such as Madras Courier, Literary Vibes, LiveWire, Indus Woman Writing, Annual anthology by Poetry Society of India etc. She won the fifth place in the Rabindranath Tagore International Poetry Competition 2022 and was the first prize winner of the short story competition by Half Baked Beans publishers. Her poem was among the top 10 selected entries for the \"Poetry in Pamphlets 2022\" by Verse of Silence magazine.", "photo": "assets/writers/96-user-selected-20261004.webp"}, {"id": "writer-46", "name": "Sharmila Ray", "bio": "Sharmila Ray is a poet and non-fiction essayist, writing in English and anthologized and featured in India and abroad. Her poems, and non fictional essays have appeared in various national and international magazines and journals. She has authored books of poetry. She has edited books on Indian English poetry. The latest being a bilingual anthology of American and Indian writers-Bridging Continents with Gopal Lahiri.", "photo": "assets/writers/46-earth-voice-v1.webp"}, {"id": "writer-35", "name": "Sharmistha Sahoo/ଶର୍ମିଷ୍ଠା ସାହୁ", "bio": "", "photo": "assets/writers/35-earth-voice-v1.webp"}, {"id": "writer-193", "name": "Sheba Jamal", "bio": "Sheba Jamal is a prolific writer in English and Hindi. She works as an English teacher in a high school in Patna . Her mother is a literary genius in Urdu literature. Sheba has penchant for creative work. Despite her hectic schedule she finds time for creativity. Her writings include poems and short stories both in English and Hindi which are published in various national and international anthologies.", "photo": "assets/writers/193-earth-voice-v1.webp"}, {"id": "writer-396", "name": "Sheila Mary Fraser Porter", "bio": "Sheila Mary Fraser Porter writes in English.", "photo": "assets/writers/396-earth-voice-v1.webp"}, {"id": "writer-353", "name": "Shishir Naik/ ଶିଶିର ନାୟକ", "bio": "", "photo": "assets/writers/353-earth-voice-v1.webp"}, {"id": "writer-31", "name": "Shuvashri Subhasmita Mishra/ଶୁଭଶ୍ରୀ ଶୁଭସ୍ମିତା ମିଶ୍ର", "bio": "", "photo": "assets/writers/31-earth-voice-v1.webp"}, {"id": "writer-148", "name": "Sigma", "bio": "Dr Sigma, a widely published Indian poet, is currently the HoD of English at VTMNSS College inTrivandrum. She worked for Oman Ministry of Manpower as a Faculty of English. Sigma`s poems appeared in many anthologies and received Mirabhai Literary Award .She has a good number of poetry books .", "photo": "assets/writers/148-earth-voice-v1.webp"}, {"id": "writer-156", "name": "Snehalata Prusty/ ସ୍ନେହଲତା ପୃଷ୍ଟି", "bio": "A familiar name in Odia literary circle, Snehalata Prusty is an adept poet and an accomplished novelist, besides being an editor of a monthly literary magazine, Ratnachira. A lecturer in Odia by profession, Smt Prusty has published four novels and four anthologies of Poetry so far. Her novels are Bhala Paibara Bhasha,bouku chithi,atikaya ,pahi asuthiba rati and her books of poetry are Krushna, bharijane tume shyamal pritira dukha, srabana pauni bhala meghaku.", "photo": "assets/writers/156-earth-voice-v1.webp"}, {"id": "writer-122", "name": "Snehaprava Das", "bio": "Snehaprava Das is a distinguished poet, critic, short story writer and translator based in Bhubaneswar.", "photo": "assets/writers/122-earth-voice-v1.webp"}, {"id": "writer-173", "name": "Sohela Chhotaray", "bio": "Sohela Chhotaray is a multilingual poet writing for about two decades. Got published in around ten national and international anthologies , authored two books. By profession a lecturer, teaches Botany and doing awareness about Environment on a Facebook page named Basics of life. Owns a community group Rudra Tamash.", "photo": "assets/writers/173-earth-voice-v1.webp"}, {"id": "writer-458", "name": "Someeta Das", "bio": "Someeta Das is a retired Professor from Maharaja Manindra Chandra College, Kolkata with twenty eight of teaching experience. She enjoy traveling , writing poems, short stories and travelogues.Her work have found homes in Glomag, Muse India, Setu, The Statesman, Women`s era , several Anthologies and a number of e-zines", "photo": "assets/writers/458-earth-voice-v1.webp"}, {"id": "writer-434", "name": "Somolekha", "bio": "Somolekha is a well-known Kolkata based poet and author. Her books, Little Tales from La La Land, Conundrum, Zilch, Distant Brontide, Oud & Amber and Yellow Goggles were her efforts to introduce the intense visions in her mindscape to the world. She currently teaches in the Bhawanipur College and is the COO of Azure ad agency. She writes in both Bengali and English with equal élan. Her English poems are regularly published in national and international magazines (online and offline) like Teesta Review, Scorpion, Expression, Prosopisia, The Kolkata Arts, Lit Review (Texas, USA), international online journals like Writers Cafe etc.", "photo": "assets/writers/434-earth-voice-v1.webp"}, {"id": "writer-175", "name": "Sonali Pattnaik", "bio": "Dr.SonaliPattnaik (PhD) is an award-winning poet,academic, educatorand visual artist. She is the author of when the flowers begin to speak (Writers Workshop, 2021). Her poetry and art have appeared in several international and national anthologies and journals. A Delhi University alumnus and professor, she currently teaches Masters in English Literature at St. Xavier`s College, Ahmedabad.", "photo": "assets/writers/175-user-selected-20261004.webp"}, {"id": "writer-187", "name": "Sonia Gupta", "bio": "Dr. Sonia Gupta is a poet, writer, reviewer, editor and translator. She hails from Dera Bassi, Mohali, Punjab, India. By profession, she is a Dentist (MDS). Poetry is her passion. She writes in English, Hindi & Punjabi languages. She has authored sixteen independent books, out of which ten are in English and six are in Hindi. She has won several awards in various literary contests. Her compositions are the part of vivid anthologies, newspapers, journals and magazines. She has edited several poems, articles, papers and anthologies and has translated many poems of different poems from the world into English, Hindi and Punjabi languages. She is also fond of painting, teaching, reading, singing, dancing, knitting, embroidery and cooking. She has got several scientific publications in PubMed & Scopus indexed International and National Journals related to her professional field. Her many projects are underway.", "photo": "assets/writers/187-earth-voice-v1.webp"}, {"id": "writer-419", "name": "Sonnet Mondal", "bio": "Sonnet Mondal is an Indian English poet, editor from Kolkata and the author of 10 books of poetry including `An Afternoon in My Mind` and `Clamour for a Handful of Rice`. He has represented India in Literature Festivals in over 35 countries including France, Macedonia, Italy, Germany, Colombia, Ireland, South Africa, Morocco including numerous literary festivals of India. He led the cultural delegation of India to Slovakia in 2016 and 2024 and was the Guest of Honour in `Les Journees Poetry International Festival`, France in 2025. He is the founder director of `Chair Poetry Evenings—Kolkata International Poetry Festival` and his works have been translated in over 30 languages worldwide.", "photo": "assets/writers/419-earth-voice-v1.webp"}, {"id": "writer-25", "name": "Soubhagyabanta Moharana/ସୌଭାଗ୍ୟବନ୍ତ ମହାରଣା", "bio": "Mr. Soubhagyabanta Maharana is born in the Bolangir town on 15th August 1951. He has been writing Odia poetry since 1975. He is a bilingual poet and translator of Odia and English. He has to his credit 19 poetry collections and 5 essay collections on modern Odia poetry. He has received Odisha Sahitya Akademi Award for poetry for 2010. Besides , he is the awardee of Jhankar Poetry Award, Kadambini Poetry Award, Basant Muduli Poetry Award, Gangadhar Meher Literary Award , Rock Pebbles Literary Award and many others. His poems have been translated into English, Hindi, Gujarati, Assamese and Bengali. Mr.Maharana is a good translator of Odia poetry into English language. He is now living in the Sambalpur city after retiring from LIC of India as a Divisional Manager. Soubhagyabanta Maharana, Sambalpur Mobile number-9437457736", "photo": "assets/writers/25-earth-voice-v1.webp"}, {"id": "writer-177", "name": "Soumen Roy", "bio": "Soumen Roy is writing since many years and a passionate lover of literature.He is the author of the Novel Scar and Poetry book titled Lyrical Musings.", "photo": "assets/writers/177-earth-voice-v1.webp"}, {"id": "writer-331", "name": "Soumya Sephali Sahoo", "bio": "Soumya Sephali Sahoo is a Gold Medalist in English from Bhubaneswar. She published her debut book Elfin Verses and Nifty Proverbs in November 2020. She has Co-authored four more books- Unbottomed Purple Nous and Resplendent Rainbow in 2021, Virtuoso and Durga- The Invincible in 2022 which are anthologies of poems and short stories. Later on she contributed as a co-author in anthologies- Aurora over the Skyline and Silhouette of the night. It shows her passion towards poetry and literature. With more than 10 publications in her bag she wishes to write more everyday. Through her writings she hints at women subjugation, prejudiced traditions, materialism and spiritual reconciliations. Recently she has received The 21st Century Emily Dickinson Award for her excellency in poetry. She has written more than 500 quotes which are google searchable and is fond of writing on gothic and spiritual themes. She has also contributed papers on philosophical research, tribal communities and indigenous poetry in National level seminars.", "photo": "assets/writers/331-earth-voice-v1.webp"}, {"id": "writer-147", "name": "Sreedharan Parokode", "bio": "Sreedharan Parokode a bi lingual poet and lyricist has thirty books of poetry to his credit, including `Weeping Womb`, `Slum Flowers,``Mahatma Gandhi` etc. His childrens` literature includes `Sathyagraham` and `Mazhavillinodu`.He has also written songs for professional dramas, and devotional songs. He has written songs for animation film also. He attended and presented his poems in Belgrade, Serbia in 2007. He also presented his poems at World Congress of Poets, in Taiwan, 2015. Sreedharan Parokode attended World Congress of Poets, China, in 2018.", "photo": "assets/writers/147-earth-voice-v1.webp"}, {"id": "writer-467", "name": "Sreekala Sivasankaran", "bio": "Dr. Sreekala Sivasankaran is a poet, author, scholar, essayist and translator based in Kottayam, Kerala. Formerly, she was Associate Professor at the Indira Gandhi National Centre for the Arts (IGNCA), New Delhi. Prior to that she was a fellow at the Nehru Memorial Museum and Library, Teenmurti, New Delhi. She has taught in various institution, including Hidayatullah National Law University, Raipur.", "photo": "assets/writers/467-user-selected-20261004.webp"}, {"id": "writer-432", "name": "Sreema Satpathy", "bio": "Sreema Satpathy is a TV journalist and a brilliant young poet. Her poems appear in social media platforms and journals regularly.", "photo": "assets/writers/432-earth-voice-v1.webp"}, {"id": "writer-100", "name": "Sreetanwi Chakraborty", "bio": "Sreetanwi Chakraborty is an Assistant Professor of English and the Chief Editor of Litinfinite Bilingual Journal. A bilingual poet and translator, she was invited by Sahitya Akademi, Samyukta Poetry, and the Chandrabhaga Poetry Festival to read her poems. She is a regular contributor to newspapers and magazines in India, Bangladesh, and South Africa, including Ekdin,Uttarer Saradin, Setumag, The Darjeeling Times, The Darjeeling Times,Agathos, The IUP Journal of English Studies, Dhaka Tribune, Grihasobha (Bangla), The Times of India, Muse India, The Taj Mahal Review, Kochi Post, Masik Kavitapatra, Daily Observer (Bangladesh), Samvad Samayiki (Bangladesh), Chinho (Rajshahi University, Bangladesh), Kavya Bharati, the Bombay Literary Review, Asian Cha, Dainik Gati (Silchar) and in notable English anthologies from Red River, Authorspress, and Silk Route Anthology from Egypt. She is an active member of Modern Language Association (NY), a voting member of Crossref (USA), and is an invited advisor of Transstellar and IJBST Group of Journals (the Humanities segment).", "photo": "assets/writers/100-earth-voice-v1.webp"}, {"id": "writer-384", "name": "Subash Singh Parajuli", "bio": "Subash Singh Parajuli is a poet, educator and avid traveller from the Eastern part of Nepal. He has written three anthologies of poetry in the English language and is the recipient of multiple awards from around the world.", "photo": "assets/writers/384-earth-voice-v1.webp"}, {"id": "writer-414", "name": "Subhashree Lenka/ ଶୁଭଶ୍ରୀ ଲେଙ୍କା", "bio": "Subhshree Lenka writes poetry in Odia. Her poems are translated into English and Hindi.", "photo": "assets/writers/414-earth-voice-v1.webp"}, {"id": "writer-445", "name": "Subhasmita Tripathy / ଶୁଭସ୍ମିତା ତ୍ରିପାଠୀ", "bio": "Subhasmita Tripathy writes Odia poetry", "photo": "assets/writers/445-earth-voice-v1.webp"}, {"id": "writer-191", "name": "Subrat Kumar Senapati", "bio": "Subrat Kumar Senapati is a poet and short story writer who received many awards including Katha Nabaprativa Award-2012. Currently, Subrat is a Ph.D. research scholar in Department of Floriculture and Landscaping in College of Agriculture, Odisha University of Agriculture & Technology, Bhubaneswar.He can be reached at ", "photo": "assets/writers/191-earth-voice-v1.webp"}, {"id": "writer-282", "name": "Suchismita Ghoshal", "bio": "Suchismita Ghoshal hails from West Bengal, India. At the age of 25, she has been continuously leaving her footprints in the contemporary literary world. She is a widely published author, internationally reputed bilingual poetess, spoken word poetess, professional writer, content writer, editor and critic, language translator, interpreter and transcriptor (Bengali, English), performing poet, communicator and literary influencer, an independent thinker, humanitarian, change enthusiast and philanthropist. She`s been invited to many international festivals and open mics. Her awards, accolades and achievements not only inspire her more to write but also to influence her through the kindness of her words. Her solo books \"Fields of Sonnet\", \"Emotions & Tantrums\" & \"Poetries in Quarantine\" are available on Amazon website.", "photo": "assets/writers/282-review-retry-v1.webp"}, {"id": "writer-262", "name": "Sudeshna Mukherjee", "bio": "An avid Nature lover, Sudeshna Mukherjee`s poems deal with varied human nature. A keen observer she absorbs and then chronicles the happenings around her with a sardonic slant and humour. \"Meanderings of the Mind \" and \"Mélange\" are her published collection of poems. She is the first recipient of Kashinath Memorial Award for her humorous and satirical writings. Her poems have been published in many ezines.", "photo": "assets/writers/262-earth-voice-v1.webp"}, {"id": "writer-354", "name": "Sudhakar Gaidhani", "bio": "Sudhakar Gaidhani is from Nagpur -Maharashtra. His mother tongue is Marathi. He knows three languages, Marathi, Hind and English.His poems have been translated into 35 languages of the world. 2 epic poems, 6 poetry collections, three stage plays and 125 short Radio plays are to his credit. He has received many State, National and International awards.", "photo": "assets/writers/354-earth-voice-v1.webp"}, {"id": "writer-281", "name": "Sudipta Mishra", "bio": "Sudipta Mishra is a multi-faceted artist and dancer excelling in various fields of art and culture. She has weaved more than a hundred books. Her book, `The Essence of Life, is credited with Amazon`s bestseller, and `The Songs of My Heart` is scaling newer heights of glory. Her poems are a beautiful amalgamation of imagery and metaphors. She garnered numerous accolades from international literary organizations like the famous Rabindranath Tagore Memorial, Women Leadership Award, Mahadevi Verma Sahitya Siromani Award, and so on. She regularly pens articles in newspapers as a strong female voice against gender discrimination, global warming, domestic violence against women, pandemics, and the ongoing war. She is pursuing a Ph.D. degree in English.", "photo": "assets/writers/281-earth-voice-v1.webp"}, {"id": "writer-40", "name": "Sujata Dash", "bio": "Sujata Dash is a retired banker. She is a Post Graduate in English Literature from Utkal University, Odisha. She is an avid lover of nature and deeply spiritual as a person. She loves to travel, read and write. She has published two poetry books in english. They are- “More than mere – a bunch of poems” by Authors Press in 2014, \"Riot of Hues\" in 2021 by Authors Press again. Both the anthologies say a lot about her admiration for nature and longing for the divine. She is a regular contributor to anthologies published nationwide and worldwide. She edits Bank of India`s in-house journal (Odisha edition) as well. She writes in three languages i.e., Odia, Hindi and English, but most of her work is in English", "photo": "assets/writers/40-earth-voice-v1.webp"}, {"id": "writer-154", "name": "Sujata Mishra/ସୁଜାତା ମିଶ୍ର", "bio": "Sujata Mishra is a very assiduous and hard working poet who impresses the readers with her insight into poetry. She writes very well in Odia and her poems are very intriguing in English too. She already has collections of poetry to her credit that are well spoken of by the readers.", "photo": "assets/writers/154-user-selected-20261004.webp"}, {"id": "writer-26", "name": "Sujata Parashar", "bio": "Bestselling novelist, short-story writer and poet, Sujata Parashar became widely popular with her ‘Pursuit’ series and has so far written twelve books across genres. AMaster’s inHuman Rights, Sujata, has a rich and diverse work experience. Apart from authoring bestsellers, she is also apsychosocial trainer and the founder of a talk-therapybased platform, The Talk-It-Out-Express;a platform to enhance emotional wellbeing.She’s also the Vice-President of Women’s Indian Chamber of Commerce and Industry’s (WICCI) Arts leadership Council, Delhi chapter.Sujatahas received the prestigious PVLF Author Excellence Award 2022 for her non fiction, ‘Going Solo – Raising Happy Kids.’It’s a handguide on single parenting. Her other prominent awards and accomplishments include, reconginition as one of the Women Achievers of 2021 by ApekshaSandesh News. And the 100 Women Faces 2018 award and several other literary awards.You can find out more about her on her website, www.sujataparashar.in", "photo": "assets/writers/26-user-selected-20261004.webp"}, {"id": "writer-49", "name": "Sujit Kumar Satapathy/ସୁଜିତ କୁମାର ଶତପଥି", "bio": "Sujit Kumar Satapathy (1991) who hails from Balangir(odisha) is a science Teacher under govt of odisha. He is a bilingual poet ,writing both in Odia and Koshli language. To his credit he has four published poetry anthologies in odia and a single poetry anthology in Koshli language. Also he has a book of criticism work. His first odia poetry anthology ICHCHHAVATI was selected and published by Sahitya Akademi under navodaya scheme 2015 Also recenly his first Koshli poetry anthology NURAA also published by Sahitya Akademi New Delhi. he has already shared creative space in MULAKAT and YUVA SAHITI program of Kendra sahitya academy.", "photo": "assets/writers/49-earth-voice-v1.webp"}, {"id": "writer-149", "name": "Sukanti Mohapatra", "bio": "Dr. Sukanti Mohapatra, an Assistant Professor of English in the Higher Education Department, Govt. of Odisha is a bilingual writer writing both in Odia and English with equal flair. Her poems, stories and articles are published in many state, national and international magazines and journals. She has three published anthologies of poems to her credit.", "photo": "assets/writers/149-review-retry-v1.webp"}, {"id": "writer-459", "name": "Sulagna Kar / ସୁଲଗ୍ନା କର", "bio": "Mrs Sulagna Kar is a lecturer in sociology in an aided college in Odisha. Her passion is writing poems and critical reviews. Her poems are published in many national and international poetry platforms.", "photo": "assets/writers/459-earth-voice-v1.webp"}, {"id": "writer-278", "name": "Sulekha Sarkar", "bio": "Sulekha is a Siliguri, West Bengal based poet and researcher.", "photo": "assets/writers/278-earth-voice-v1.webp"}, {"id": "writer-428", "name": "Sumana Bhattacharjee", "bio": "Sumana Bhattacharjee is an English poetry and quote writer from India. She born and brought up in city Calcutta and still residing there with her family. She is a published poet and quote writer and her poems have been published in many National and International anthologies, ezines and blogs. She is the founder of an online poetry group and working as an admin of three other literary group. She is passionate about music and poetry and she belives she can spread love and peace through her ink around the world.", "photo": "assets/writers/428-earth-voice-v1.webp"}, {"id": "writer-207", "name": "Sumati Mund / ସୁମତି ମୁଣ୍ଡ", "bio": "Sumati Mund writes story, poem, features and drama (laghu natak) in Odia. A teacher by profession she also works in AIR as a casual. She lives in Bhawanipatna.", "photo": "assets/writers/207-earth-voice-v1.webp"}, {"id": "writer-266", "name": "Sumit Panda / ସୁମିତ ପଣ୍ଡା", "bio": "Sumit Panda is a new generation Odia poet. He is frequently published in leading newspapers and journals. An Indian Lyricist and TV script and screen writer. He has also penned 3 Poetry books and more than 55+ album lyrics. He has written the Story,Dialogue & Lyrics of \"Byaase Sunucha\". Currently he is working as a Team Lead in IBM ltd.", "photo": "assets/writers/266-user-selected-20261004.webp"}, {"id": "writer-166", "name": "Sunanda Pattanaik Janah / सुनन्दा पट्टनायक जाना", "bio": "Sunanda Pattanaik Janah (Bhubaneswar) is a bilingual poet , author but specially writes in Hindi . Her poems are Published in many National Anthology. She has participated in many national and international poetry festivals. Literature and music are her passions. Being born in a musical family , she can hear an orchestra in rain a smell the essence of poetry from the fragrance of the Earth.", "photo": "assets/writers/166-earth-voice-v1.webp"}, {"id": "writer-466", "name": "Sunanda Pradhan", "bio": "Sunanda Pradhan writes in Odia. Lives in Bhubaneswar, her phone number- 9439366566", "photo": "assets/writers/466-earth-voice-v1.webp"}, {"id": "writer-421", "name": "Sunanda Tripathy / ଡ଼. ସୁନନ୍ଦା ତ୍ରିପାଠୀ", "bio": "Sunanda Triparthy is an academician writes poetry in odia language.", "photo": "assets/writers/421-user-selected-20261004.webp"}, {"id": "writer-87", "name": "Sunil Sharma", "bio": "Sunil Sharma,PhD (English), is currently Toronto-based academic, critic, literary editor and author with 25 published books: Seven collections of poetry; five of short fiction; one novel; a critical study of the novel, and, ten joint anthologies on prose, poetry and criticism, and, one joint poetry collection. He is, among others, a recipient of the UK-based Destiny Poets’ inaugural Poet of the Year award---2012. His poems were published in the prestigious UN project: Happiness: The Delight-Tree: An Anthology of Contemporary International Poetry, in the year 2015.", "photo": "assets/writers/87-earth-voice-v1.webp"}, {"id": "writer-48", "name": "Sunita Paul", "bio": "Sunita Paul is an award-winning entrepreneur and publisher from the City of Joy, Kolkata, West Bengal, India. The Managing Director of AABS Publishing House, CEO of AABS Events and Entertainment, Co-founder of Paul Consultancy Services, Sunita is the Editor-in-chief of Reader’s Choice Magazine and organizer of many events of high repute. She is also the assistant editor of Atunis Galaktika, a premium European poetry platform. Recently she has been appointed as the Director Operations in the esteemed G-100 Country Club of Wicci.", "photo": "assets/writers/48-user-selected-20261004.webp"}, {"id": "writer-259", "name": "Surbhi Islam", "bio": "Surbhi Islam is a reader, a thinker, a poet, a writer and a reviewer. She writes in Hindi, English and Bengali. She has Authored three books, `The Bliss of Solitude`, a poetry collection in Hindi, `She fell to rise in Love`, a novel in English and her latest, `Silent Uproar`, a poetry collection in English.", "photo": "assets/writers/259-earth-voice-v1.webp"}, {"id": "writer-299", "name": "Surendra Panigrahi/ ସୁରେନ୍ଦ୍ର ପାଣିଗ୍ରାହୀ", "bio": "Surendra Panigrahi is a poet and translator. He has six poetry collections to his credit. He has translated a good number of books into Odia. A widely published poet Sri Panigrahi has been awarded in several literary forums. He lives in Bhubaneswar.", "photo": "assets/writers/299-review-retry-v1.webp"}, {"id": "writer-309", "name": "Suresh Kumar Nayak/ସୁରେଶ କୁମାର ନାୟକ", "bio": "", "photo": "assets/writers/309-earth-voice-v1.webp"}, {"id": "writer-160", "name": "Susama Dash/ସୁଷମା ଦାଶ୍", "bio": "", "photo": "assets/writers/160-earth-voice-v1.webp"}, {"id": "writer-188", "name": "Sushant Thapa", "bio": "Sushant Thapa (1993) is from Biratnagar, Nepal. He is an M.A. in English literature from Jawaharlal Nehru University, New Delhi, India. His fourth and upcoming book of poems titled “Love`s Cradle” is going to be published by World Inkers Printing and Publishing, New York, USA. He teaches Business English to undergraduate students in Biratnagar, Nepal.", "photo": "assets/writers/188-earth-voice-v1.webp"}, {"id": "writer-464", "name": "Susmindar Jeet Kaur", "bio": "Susmindar Jeet Kaur is a poet, editor and academician based in Ludhiana, Punjab", "photo": "assets/writers/464-earth-voice-v1.webp"}, {"id": "writer-200", "name": "Susmita Patel", "bio": "Susmita Patel writes both Poetry and fiction in Odia. She has three collections of poetry to her credit. She has also published one Novel Antahin Pratikshya and one Short Story Collection Dairy. She lives in Kuchinda, Sambalpur, Odisha.", "photo": "assets/writers/200-earth-voice-v1.webp"}, {"id": "writer-150", "name": "Sutanuka Ghosh Roy", "bio": "Dr.Sutanuka Ghosh Roy is an AssociateProfessor in the Department of Englishat Tarakeswar Degree College, The University of Burdwan, India. She is a reviewer, a critic, and a poet. The titles of her books are Critical Inquiry: Text, Context, and Perspectives and Commentaries: Elucidating Poetry, Rassundari Dasi`s Amar Jiban: A Comprehensive Study, Asprishya( The Untouchables, a novel by Sharan Kumar Limbale translated into Bengali)", "photo": "assets/writers/150-user-selected-accepted-retry-20261004.webp"}, {"id": "writer-328", "name": "Swagatika Mishra/ ସ୍ବାଗତିକା ମିଶ୍ର", "bio": "Swagatika Mishra writes Odia poetry. Young energetic Swagatika is a journalist by profession.", "photo": "assets/writers/328-earth-voice-v1.webp"}, {"id": "writer-60", "name": "Swapna Behera", "bio": "Swapna Behera is a trilingual poet, translator ,environmentalist ,editor ,peace activist from India and author of seven books of different genres including one on children`s literature on Environment .She is the recipient of International UGADI AWARD 2019, honoured from Gujurat Sahitya Akademi 2022,2021 International Poesis Award of Honor as Jury,Pentasi B World Fellow Poet, Honoured Poet of India from Seychelles Government and International awards from Algeria, Morocco ,Kajhakhstan ,Kyrgyzstan, modern Arabic Literary Renaissance of Egypt , International Arts Council Argentina etc. Her stories, poems ,articles are published in many International and National magazines and ezines . Her poem A NIGHT IN THE REFUGEE CAMP is translated into 67 languages. She has bagged naerly70 National and Internatioanl Awards .At present She is the Cultural Ambassador for India and South Asia of Inner Child Press U.S ,The Chief Admn of India and Middle east Zone of India Office of Motivational Strips , Cultural Convenor& Literary Coordinator of International Society for Intercultural Studies and Research ISSIAR and the life member of Odisha Environmental Society ,", "photo": "assets/writers/60-review-retry-v1.webp"}, {"id": "writer-372", "name": "Swapna Mishra/ ସ୍ଵପ୍ନା ମିଶ୍ର", "bio": "Swapna Mishra (b. 1970) graduated from Utkal University with a Ph.D. in Odia on the linguistic study of Odia Bhagabata. Since then, she has written various texts with a fondness for literature in her heart. These texts include anthologies of poetry (e.g. Chadha Utara, PrathamaPruthibi, Sabda Banchirahe etc.), anthologies of prose (e.g. Prarthanara Niaghera, Nabagunjara etc.), novels (e.g. Daga, Jala, Nirabatara Uccharana, Pheta), and translations (e.g. SamudraGhoda, Sansayatma, LomasaJalahasti). She has been felicitated with awards like Ankura Puraskara, Sreekshetra Samman, Rajdhani Pustakamela Puraskara, Dr. Sachidananda Routray Nabaparba Puraskar and many more.", "photo": "assets/writers/372-earth-voice-v1.webp"}, {"id": "writer-273", "name": "Swapnajita Sankhua / ସ୍ଵପ୍ନାଜିତା ଶଙ୍ଖୁଆ", "bio": "Swapnajita Sankhua is one of the new generation poets in Odia, who is widely published in different magazines and journals. Her poems have been widely appreciated by the readers.", "photo": "assets/writers/273-earth-voice-v1.webp"}, {"id": "writer-463", "name": "Swatilekha Roy", "bio": "She’s a poet based in Silchar, Assam", "photo": "assets/writers/463-user-selected-20261004.webp"}, {"id": "writer-227", "name": "Sweety Sony Lall", "bio": "Sweety Sony Lall is from Patna Bihar. She has graduated in English Honours from IGNOU Patna. Writing is her hobby and she is fond of sharing her thoughts with everyone through words.", "photo": "assets/writers/227-user-selected-accepted-retry-20261004.webp"}, {"id": "writer-38", "name": "Sweta Rout/ଶ୍ଵେତା ରାଉତ", "bio": "", "photo": "assets/writers/38-user-selected-20261004.webp"}, {"id": "writer-229", "name": "Tahera Mannan", "bio": "Dr. Tahera Mannan Premium member of International Poets` Group, USA. Academic Counsellor at Indira Gandhi Open University. Author of the book Heartstrings. Executive Editor of Cultural Reverence, an International Literary Magazine. Awardee of Faroque Junoon Award for Excellence in Literature.", "photo": "assets/writers/229-user-selected-candidate2-20261004.webp"}, {"id": "writer-237", "name": "Tamali Neogi", "bio": "Dr.Tamali Neogi teaches English at Gushkara College, Gushkara (West Bengal), India. As a creative writer she has published The Woman of Patashpur and edited Postmodern Voices, Volume VIII: An Anthology of Poems. Currently she is engaged in editing a book on Life Writings of women belonging to different continents. In an academic career spanning two decades, Dr.Neogi has published short stories in Tales of Our Times and Lapis Lazuli, presented research papers at National and International Seminars, presided over Paper Reading Sessions, and also published book reviews in reputed U.G.C. Care Listed Journals. Her second Anthology of short fiction will hit the stands by the end of this year.", "photo": "assets/writers/237-earth-voice-v1.webp"}, {"id": "writer-195", "name": "Tandra Mishra", "bio": "Tandra Mishra is from Raiganj, West Bengal, India. She is a bilingual(English and Bengali) writer,poetess and author of an English poetry book,`Oh Father`. She has completed master`s degree in English. She has been honoured with accolade in 2005 for writing poetry from `FUREC`, which was launched by our former president,Dr. APJ Abdul Kalam.Her poems have been published worldwide in many literary journals.", "photo": "assets/writers/195-user-selected-candidate2-20261004.webp"}, {"id": "writer-294", "name": "Tapeshwar Prasad", "bio": "Tapeshwar Prasad has authored blend of five surrealistic and realistic poetry books, and has been featured in Camel Saloon (U.K.), Cordite Poetry Review (Australia), The Aquillrelle Wall of Poetry, Crashing Waves (USA), Scaling Heights (an Anthology on Contemporary Indian English Poetry), inklinks, Anthesis, Episteme, Heavenly Hymns, I am A Poet, Just for you My Love, Kaafiyana, Resonance, The Significant Anthology, Rhyme with Reason, World Anthology of English Poetry, Acerbic Anthology, Mandela Tributes, Whispering Winds, Intercontinental Anthology of Poetry on Universal Peace, Muse India, Hall of Poets and many more. He has been included five times as ICOP: Roll of Honour (U.K.)", "photo": "assets/writers/294-user-selected-candidate2-20261004.webp"}, {"id": "writer-420", "name": "Tasneem Hossain", "bio": "Tasneem Hossain is a prominent poet of Bangladesh and is presently Director of Continuing Education Centre, Dhaka.", "photo": "assets/writers/420-user-selected-candidate2-20261004.webp"}, {"id": "writer-28", "name": "Tejaswini Patil", "bio": "Tejaswini Patil is the Head, Dept. of English, Arts and Commerce College, Kasegaon; Founder Director, Innsæi International Journal of Creative Literature, Art, Translation, and Research for Peace and Humanity (IJCLRATRPH) and Matru Akshar, International Journal of Indian Languages for Creative Literature, Translation and Research (IJILCLTR); an academician, poet, editor, and social worker. Four collections of poetry are to her credit. Editor, Tunisian Asian Anthology, Mystical Voices. Selected for prestigious RGVIPF, Texas, USA for 2018- 2021. Included in 25 Women of Virtue. Awards- Master of Creative Impulse (Punjab), A Great Poet and Writer Par Excellence, Daman; Certificate of Thanks and Gratitude on the occasion of the International Nonviolence Day 2nd October, by the administration of the World Peace Federation, The Union of Elite Arab Creative, and the Writer’s International Union headed by the Ambassador for the World Peace and Human Rights, Dr Narzine Bani Hashem; DIPLOMA Nominee for the World Award 2022 from Rahim Karim, Bangladesh; Aazaad International Award of Excellence by Aazaad Foundation, World Literature, India; Life Time Achievement Award (For Education) at 3rd International Women Empowerment Summit and Dr. Sarvepalli Radha Krishnan Award on 5th Sept. 2021, Vrindavan, India.", "photo": "assets/writers/28-earth-voice-v1.webp"}, {"id": "writer-234", "name": "Til Kumari Sharma", "bio": "Til Kumari Sharma was born in Bhorle- Hile, Paiyun 7, Parbat, West Nepal. She is known as Pushpa ( youngest daughter ) too. Her parents are Mr. Hari Prasad Basel Sharma ( Mayor of Village Assembly in the time of Kingdom ) and Mrs. Liladevi Bhusal Bashyal/ Basel. She has her school as ( Shree ) Janata Ma.Vi. Bhorle, Parbat, I.A. from People`s Campus, Paknajol, Kathmandu. She has her B.A. from R.R. Campus Pradarshani Marg, Kathmandu. B.Ed. ( Eng. and Pop.) from T. U. Kirtipur and M. A. from Tribhuvan University, Kirtipur and L L. B from Nepal Law Campus Pradarshani Marg, Kathmandu. Her PhD is in English Literature from Singhania University Pacheri Bari, Jhunjhunu in Rajasthan ( India ). She has published many thousands of poems, some essays, and stories and other literary writings ( in Amazon. com and Magazine from Russia, America, England, Scotland, Indonesia, Bangladesh, South Africa, Kenya, Nigeria, North Africa, Trinidad and Tobago , Spain, India and others ) from Nepal & different countries of world. Now she is world famous author and poet/ poetess. She is the featured poet in different books and magazines too. She is co- author in best -selling anthologies. She is Multi Award Winner from international sectors.", "photo": "assets/writers/234-earth-voice-v1.webp"}, {"id": "writer-274", "name": "Timothy Michael DiVito", "bio": "Timothy Michael DiVito has been writing poetry for 47 years. He has been published in The San Fernando Poetry Journal, The Rag Mag, Möbius, WYRD, Homagi, Kiroo E-Book, Pennsylvania Bard West Poetry Anthology, Creative Writers: Contemporary Writers, Amar Vishv Sahitya Anthology, Creating A Better World Anthology, Atunis Poetry Online, WordSmith International Interview, The World Peace Anthology, A Spark Of Hope 3 and WildFire Publications Staff Writer. He also sites on WordPress, Poetizer, lineofpoery, Facebook, Twitter, Instagram and Wix. He also has two books on Amazon- \"", "photo": "assets/writers/274-earth-voice-v1.webp"}, {"id": "writer-425", "name": "Tirna Sarkar", "bio": "Tirna Sarkar is from Kolkata, She has been writing since she was a teenager. For her writing is a catharsis that can give relief from all kinds of struggles. She studied English literature. Currently she Is a volunteer at an NGO as a part time teacher for underprivileged children.", "photo": "assets/writers/425-user-selected-candidate2-20261004.webp"}, {"id": "writer-403", "name": "Toolika Rani", "bio": "Squadron Leader (Dr) Toolika Rani is an Ex-Indian Air Force Officer, Mountaineer (Everest Climber), International Motivational Speaker (twice TEDx), Poet, Author and Assistant Professor of History. She has authored eight books, out of which three are her English Poetry books, and two are collections of her Hindi poems. She has also compiled an international anthology of poems on Himalaya, titled, The Mountain was Abuzz. She may be contacted at email id: .", "photo": "assets/writers/403-earth-voice-v1.webp"}, {"id": "writer-210", "name": "Trinath Singh/ ତ୍ରିନାଥ ସିଂ", "bio": "Trinath Singh is an Odia poet, writing for about four decades. His poems delineate the beauty in every aspect of life and sings the verse of Humanism. He is closely kindred to nature. He has published five poetry collections to his credit namely Ferantã Pakshi, Kolãhala, Semãnanka Poorbãpara, Pabana Bahuchhi Jemiti, Chupchãp Chaturthadhãdire.", "photo": "assets/writers/210-earth-voice-v1.webp"}, {"id": "writer-151", "name": "Trishna Basak", "bio": "Trishna Basak , born in 1970, Kolkata, is a notable poet, story writer, novelist and essayist of modern Bengali Literature. A B.E. and M.Tech from Jadavpur University, Trishna left her lucrative career to pursue her passion for literarure. Her 5 year stint with Sahitya Academi enabled her to get in close touch with Indian Literature. At present, She is a full time writer, editor and translator. She is also the secretary of Kolkata Translators Forum. She has more than 40 books of poems, short stories, novels, science fiction, essays and translated works to her credit. Trishna loves experimenting with complex themes. Her writings bear the wounds of modern terror stricken world as well as estrangement of technology dominated relationship. She lives in Kolkata. She is married to a Professor of Jadavpur Universiry and has a daughter.", "photo": "assets/writers/151-earth-voice-v1.webp"}, {"id": "writer-298", "name": "Tuhinamshu Rath", "bio": "Tuhinamshu Rath teaches Sociology in a college, but his passion for literature is unlimited. He has eight collections of poetry in Odia to his credit. He lives in Kantigadia, Jajpur in the state of Odisha. He can be contacted through .", "photo": "assets/writers/298-earth-voice-v1.webp"}, {"id": "writer-449", "name": "Tulika Bibidh Rang / तूलिका विविध रंग", "bio": "Ms. Tulika is an Assistant Professor at Amity School of Communication, Amity University Madhya Pradesh, and a poet whose words draw inspiration from the quiet beauty of everyday life. Moving gracefully between classrooms and creative expression, she believes that stories and poetry have the power to connect hearts and illuminate human experiences. Through her verses, she invites readers to pause, reflect, and rediscover the poetry hidden in life’s simplest moments.", "photo": "assets/writers/449-earth-voice-v1.webp"}, {"id": "writer-201", "name": "Umesh Chandra Mohapatra", "bio": "Dr. Umesh Chandra Mohapatra writes in both Odia and English, He has six anthologies of poetry to his credit, where two are in Odia. He teaches English in Panchayat College, Baragarh, Odisha.", "photo": "assets/writers/201-earth-voice-v1.webp"}, {"id": "writer-152", "name": "Urna Bose", "bio": "Urna Bose is an advertising professional, writer, poet, and editor. Her poetry has gone viral, globally. She won `The Enchanting Editor Award 2019`, from the Telangana Poetry Forum, and the `Women Empowered - Scintillating Creative Impactful – Feminine Power Inspiration Award 2020`. And the prestigious Nissim International Prize for Poetry, 2021. As the Deputy Editor for Different Truths, she also devotes her time to the `Poet 2 Poet` column. Having worked with advertising giants in India like R K Swamy/BBDO, McCann Erickson, Mudra, Lowe Lintas, and others, Urna has been the brainchild behind a vast body of iconic advertising campaigns and brand work. Urna`s campaigns have won both Indian and global creativity awards, and some are even industry case studies. Urna believes that soulful poetry and gooey chocolate cake can fix everything.", "photo": "assets/writers/152-earth-voice-v1.webp"}, {"id": "writer-287", "name": "Utpal Man", "bio": "Utpal Man is a bilingual poet and a short story writer. He has an anthology of two novels published last year under the same cover. He has been in this literary field for almost twenty five years. He has seven books of poetry, an anthology of short stories and a collection of two novels in Bengali to his own credit.", "photo": "assets/writers/287-earth-voice-v1.webp"}, {"id": "writer-190", "name": "Vandana Kumar", "bio": "Vandana Kumar is a French teacher, poet, translator, Indie film producer and cinephile residing in New Delhi, India. Her poems have been published in several national and international websites of repute. She has featured in literary journals like `Fine Lines` and anthologies like `Harbinger Asylum`, `Kali Project``But You Don`t Look Sick` etc. Her debut collection of poems `Mannequin Of Our Times` was published in February 2023.", "photo": "assets/writers/190-earth-voice-v1.webp"}, {"id": "writer-184", "name": "Varsha Saran", "bio": "Varsha Saran is a homemaker living in Meerut Utter Pradesh India .She did her post graduation from Ch Charan Sing University Meerut. She is a bilingual poetess ,story writer. Her many poems and stories have been published in different international anthologies , e-zines , magazines and newspapers .Her poems have been published in Setu, Driff truth, Glomag, Amravati poetic prism, Atunis poetry ,Raven cage ezine , Bharath Vision ,ALS international, Kubuli poems and Sarita Magazine She won many awards in writing.", "photo": "assets/writers/184-earth-voice-v1.webp"}, {"id": "writer-430", "name": "Veena Karmachandani", "bio": "Veena Karamchandani is a Jaipur based poet , fiction writer and storyteller. She’s used to write both in Sindhi and Hindi.", "photo": "assets/writers/430-earth-voice-v1.webp"}, {"id": "writer-377", "name": "Vikramaditya Singh / विक्रमादित्य सिंह", "bio": "Vikramaditya Singh is engaged in Hindi literature for last twenty years. He has two collections of poems to his credit. His writings including poems, short stories and essays are published in many journals at national level.", "photo": "assets/writers/377-user-selected-candidate2-20261004.webp"}, {"id": "writer-438", "name": "Zahir Hossain Baidya", "bio": "Zahir Hossain Baidya is a third-year student of English Honours at Fakir Chand College under Calcutta University. He tends to write things down when his emotions get triggered, be that in a pathetic way or in a very sweet and mesmerizing way. He writes and composes poems to let go of those intense thoughts that cause some kind of chemical reactions in his brain.", "photo": "assets/writers/438-earth-voice-v1.webp"}, {"id": "writer-218", "name": "Zakir Khan / ଜାକିର ଖାନ", "bio": "Zakir Khan is a poet, short story writer and novelist who works in OTV as a media professional.", "photo": "assets/writers/218-earth-voice-v1.webp"}];
